import { TranslationEntry } from './en';

export const englishBatch2: TranslationEntry[] = [
  { surahId: 41, ayahNumber: 1, text: 'Ha, Meem.' },
  { surahId: 41, ayahNumber: 2, text: '[This is] a revelation from the Entirely Merciful, the Especially Merciful -' },
  { surahId: 41, ayahNumber: 3, text: 'A Book whose verses have been detailed, an Arabic Qur\'an for a people who know,' },
  { surahId: 41, ayahNumber: 4, text: 'As a giver of good tidings and a warner; but most of them turn away, so they do not hear.' },
  { surahId: 41, ayahNumber: 5, text: 'And they say, "Our hearts are within coverings from that to which you invite us, and in our ears is deafness, and between us and you is a partition, so work; indeed, we are working."' },
  { surahId: 41, ayahNumber: 6, text: 'Say, O [Muhammad], "I am only a man like you to whom it has been revealed that your god is but one God; so take a straight course to Him and seek His forgiveness." And woe to those who associate others with Allah -' },
  { surahId: 41, ayahNumber: 7, text: 'Those who do not give zakah, and in the Hereafter they are disbelievers.' },
  { surahId: 41, ayahNumber: 8, text: 'Indeed, those who believe and do righteous deeds - for them is a reward uninterrupted.' },
  { surahId: 41, ayahNumber: 9, text: 'Say, "Do you indeed disbelieve in He who created the earth in two days and attribute to Him equals? That is the Lord of the worlds."' },
  { surahId: 41, ayahNumber: 10, text: 'And He placed on the earth firmly set mountains over its surface, and He blessed it and determined therein its [creatures\'] sustenance in four days without distinction - for [the information] of those who ask.' },
  { surahId: 41, ayahNumber: 11, text: 'Then He directed Himself to the heaven while it was smoke and said to it and to the earth, "Come [into being], willingly or by compulsion." They said, "We have come willingly."' },
  { surahId: 41, ayahNumber: 12, text: 'And He completed them as seven heavens within two days and inspired in each heaven its command. And We adorned the nearest heaven with lamps and as protection. That is the determination of the Exalted in Might, the Knowing.' },
  { surahId: 41, ayahNumber: 13, text: 'But if they turn away, then say, "I have warned you of a thunderbolt like the thunderbolt [that struck] \'Aad and Thamud.' },
  { surahId: 41, ayahNumber: 14, text: '[That occurred] when the messengers had come to them before them and after them, [saying], "Worship not except Allah." They said, "If our Lord had willed, He would have sent down the angels, so indeed we, in that with which you have been sent, are disbelievers."' },
  { surahId: 41, ayahNumber: 15, text: 'As for \'Aad, they were arrogant upon the earth without right and said, "Who is greater than us in strength?" Did they not consider that Allah who created them was greater than them in strength? But they were rejecting Our signs.' },
  { surahId: 41, ayahNumber: 16, text: 'So We sent upon them a screaming wind during days of misfortune to make them taste the punishment of disgrace in the worldly life; but the punishment of the Hereafter is more disgracing, and they will not be helped.' },
  { surahId: 41, ayahNumber: 17, text: 'And as for Thamud, We guided them, but they preferred blindness over guidance, so the thunderbolt of humiliating punishment seized them for what they used to earn.' },
  { surahId: 41, ayahNumber: 18, text: 'And We saved those who believed and used to fear Allah.' },
  { surahId: 41, ayahNumber: 19, text: 'And [mention, O Muhammad], the Day when the enemies of Allah will be gathered to the Fire while they are [driven] assembled in rows,' },
  { surahId: 41, ayahNumber: 20, text: 'Until, when they reach it, their hearing and their eyes and their skins will testify against them of what they used to do.' },
  { surahId: 41, ayahNumber: 21, text: 'And they will say to their skins, "Why have you testified against us?" They will say, "We were made to speak by Allah, who has made everything speak; and He created you the first time, and to Him you are returned.' },
  { surahId: 41, ayahNumber: 22, text: 'And you were not covering yourselves, lest your hearing testify against you or your sight or your skins, but you assumed that Allah does not know much of what you do.' },
  { surahId: 41, ayahNumber: 23, text: 'And that was your assumption which you assumed about your Lord. It has brought you to ruin, and you have become among the losers."' },
  { surahId: 41, ayahNumber: 24, text: 'So [even] if they are patient, the Fire is a residence for them; and if they ask to appease [Allah], they will not be of those who are allowed to appease.' },
  { surahId: 41, ayahNumber: 25, text: 'And We appointed for them companions who made attractive to them what was before them and what was behind them [of sin], and the word has come into effect upon them among nations which had passed on before them of jinn and men. Indeed, they [all] were losers.' },
  { surahId: 41, ayahNumber: 26, text: 'And those who disbelieve say, "Do not listen to this Qur\'an and speak noisily during [the recitation of] it that perhaps you will overcome."' },
  { surahId: 41, ayahNumber: 27, text: 'But We will surely cause those who disbelieve to taste a severe punishment, and We will surely recompense them for the worst of what they had been doing.' },
  { surahId: 41, ayahNumber: 28, text: 'That is the recompense of the enemies of Allah - the Fire. For them therein is the home of eternity as recompense for what they, of Our verses, were rejecting.' },
  { surahId: 41, ayahNumber: 29, text: 'And those who disbelieved will [then] say, "Our Lord, show us those who misled us of the jinn and men [so] we may put them under our feet that they will be among the lowest."' },
  { surahId: 41, ayahNumber: 30, text: 'Indeed, those who have said, "Our Lord is Allah " and then remained on a right course - the angels will descend upon them, [saying], "Do not fear and do not grieve but receive good tidings of Paradise, which you were promised.' },
  { surahId: 41, ayahNumber: 31, text: 'We [angels] were your allies in worldly life and [are so] in the Hereafter. And you will have therein whatever your souls desire, and you will have therein whatever you request [or wish]' },
  { surahId: 41, ayahNumber: 32, text: 'As accommodation from a [Lord who is] Forgiving and Merciful."' },
  { surahId: 41, ayahNumber: 33, text: 'And who is better in speech than one who invites to Allah and does righteousness and says, "Indeed, I am of the Muslims."' },
  { surahId: 41, ayahNumber: 34, text: 'And not equal are the good deed and the bad. Repel [evil] by that [deed] which is better; and thereupon the one whom between you and him is enmity [will become] as though he was a devoted friend.' },
  { surahId: 41, ayahNumber: 35, text: 'But none is granted it except those who are patient, and none is granted it except one having a great portion [of good].' },
  { surahId: 41, ayahNumber: 36, text: 'And if there comes to you from Satan an evil suggestion, then seek refuge in Allah. Indeed, He is the Hearing, the Knowing.' },
  { surahId: 41, ayahNumber: 37, text: 'And of His signs are the night and day and the sun and moon. Do not prostrate to the sun or to the moon, but prostate to Allah, who created them, if it should be Him that you worship.' },
  { surahId: 41, ayahNumber: 38, text: 'But if they are arrogant - then those who are near your Lord exalt Him by night and by day, and they do not become weary.' },
  { surahId: 41, ayahNumber: 39, text: 'And of His signs is that you see the earth stilled, but when We send down upon it rain, it quivers and grows. Indeed, He who has given it life is the Giver of Life to the dead. Indeed, He is over all things competent.' },
  { surahId: 41, ayahNumber: 40, text: 'Indeed, those who inject deviation into Our verses are not concealed from Us. So, is he who is cast into the Fire better or he who comes secure on the Day of Resurrection? Do whatever you will; indeed, He is Seeing of what you do.' },
  { surahId: 41, ayahNumber: 41, text: 'Indeed, those who disbelieve in the message after it has come to them... And indeed, it is a mighty Book.' },
  { surahId: 41, ayahNumber: 42, text: 'Falsehood cannot approach it from before it or from behind it; [it is] a revelation from a [Lord who is] Wise and Praiseworthy.' },
  { surahId: 41, ayahNumber: 43, text: 'Nothing is said to you, [O Muhammad], except what was already said to the messengers before you. Indeed, your Lord is a possessor of forgiveness and a possessor of painful penalty.' },
  { surahId: 41, ayahNumber: 44, text: 'And if We had made it a non-Arabic Qur\'an, they would have said, "Why are its verses not explained in detail [in our language]? Is it a foreign [recitation] and an Arab [messenger]?" Say, "It is, for those who believe, a guidance and cure." And those who do not believe - in their ears is deafness, and it is upon them blindness. Those are being called from a distant place.' },
  { surahId: 41, ayahNumber: 45, text: 'And We had already given Moses the Scripture, but it came under disagreement. And if not for a word that preceded from your Lord, it would have been concluded between them. And indeed they are, concerning the Qur\'an, in disquieting doubt.' },
  { surahId: 41, ayahNumber: 46, text: 'Whoever does righteousness - it is for his [own] soul; and whoever does evil [does so] against it. And your Lord is not ever unjust to [His] servants.' },
  { surahId: 41, ayahNumber: 47, text: 'To him [alone] is attributed knowledge of the Hour. And fruits emerge not from their coverings nor does a female conceive or give birth except with His knowledge. And the Day He will call to them, "Where are My \'partners\'?" they will say, "We announce to You that there is [no longer] among us any witness [to that]."' },
  { surahId: 41, ayahNumber: 48, text: 'And lost from them will be those they were invoking before, and they will be certain that they have no place of escape.' },
  { surahId: 41, ayahNumber: 49, text: 'Man is not weary of supplication for good [things], but if evil touches him, he is hopeless and despairing.' },
  { surahId: 41, ayahNumber: 50, text: 'And if We let him taste mercy from Us after an adversity which has touched him, he will surely say, "This is [due] to me, and I do not think the Hour will occur; and [even] if I should be returned to my Lord, indeed, for me there will be with Him the best." But We will surely inform those who disbelieved about what they did, and We will surely make them taste a massive punishment.' },
  { surahId: 41, ayahNumber: 51, text: 'And when We bestow favor upon man, he turns away and distances himself; but when evil touches him, then he is full of extensive supplication.' },
  { surahId: 41, ayahNumber: 52, text: 'Say, "Have you considered: if the Qur\'an is from Allah and you disbelieved in it, who would be more astray than one who is in extreme dissension?"' },
  { surahId: 41, ayahNumber: 53, text: 'We will show them Our signs in the horizons and within themselves until it becomes clear to them that it is the truth. But is it not sufficient concerning your Lord that He is, over all things, a Witness?' },
  { surahId: 41, ayahNumber: 54, text: 'Unquestionably, they are in doubt about the meeting with their Lord. Unquestionably He is, of all things, encompassing.' },
  { surahId: 42, ayahNumber: 1, text: 'Ha, Meem.' },
  { surahId: 42, ayahNumber: 2, text: '\'Ayn, Seen, Qaf.' },
  { surahId: 42, ayahNumber: 3, text: 'Thus has He revealed to you, [O Muhammad], and to those before you - Allah, the Exalted in Might, the Wise.' },
  { surahId: 42, ayahNumber: 4, text: 'To Him belongs whatever is in the heavens and whatever is in the earth, and He is the Most High, the Most Great.' },
  { surahId: 42, ayahNumber: 5, text: 'The heavens almost break from above them, and the angels exalt [Allah] with praise of their Lord and ask forgiveness for those on earth. Unquestionably, it is Allah who is the Forgiving, the Merciful.' },
  { surahId: 42, ayahNumber: 6, text: 'And those who take as allies other than Him - Allah is [yet] Guardian over them; and you, [O Muhammad], are not over them a manager.' },
  { surahId: 42, ayahNumber: 7, text: 'And thus We have revealed to you an Arabic Qur\'an that you may warn the Mother of Cities [Makkah] and those around it and warn of the Day of Assembly, about which there is no doubt. A party will be in Paradise and a party in the Blaze.' },
  { surahId: 42, ayahNumber: 8, text: 'And if Allah willed, He could have made them [of] one religion, but He admits whom He wills into His mercy. And the wrongdoers have not any protector or helper.' },
  { surahId: 42, ayahNumber: 9, text: 'Or have they taken protectors [or allies] besides him? But Allah - He is the Protector, and He gives life to the dead, and He is over all things competent.' },
  { surahId: 42, ayahNumber: 10, text: 'And in anything over which you disagree - its ruling is [to be referred] to Allah. [Say], "That is Allah, my Lord; upon Him I have relied, and to Him I turn back."' },
  { surahId: 42, ayahNumber: 11, text: '[He is] Creator of the heavens and the earth. He has made for you from yourselves, mates, and among the cattle, mates; He multiplies you thereby. There is nothing like unto Him, and He is the Hearing, the Seeing.' },
  { surahId: 42, ayahNumber: 12, text: 'To Him belong the keys of the heavens and the earth. He extends provision for whom He wills and restricts [it]. Indeed He is, of all things, Knowing.' },
  { surahId: 42, ayahNumber: 13, text: 'He has ordained for you of religion what He enjoined upon Noah and that which We have revealed to you, [O Muhammad], and what We enjoined upon Abraham and Moses and Jesus - to establish the religion and not be divided therein. Difficult for those who associate others with Allah is that to which you invite them. Allah chooses for Himself whom He wills and guides to Himself whoever turns back [to Him].' },
  { surahId: 42, ayahNumber: 14, text: 'And they did not become divided until after knowledge had come to them - out of jealous animosity between themselves. And if not for a word that preceded from your Lord [postponing the penalty] until a specified time, it would have been concluded between them. And indeed, those who were granted inheritance of the Scripture after them are, concerning it, in disquieting doubt.' },
  { surahId: 42, ayahNumber: 15, text: 'So to that [religion of Allah] invite, [O Muhammad], and remain on a right course as you are commanded and do not follow their inclinations but say, "I have believed in what Allah has revealed of the Qur\'an, and I have been commanded to do justice among you. Allah is our Lord and your Lord. For us are our deeds, and for you your deeds. There is no [need for] argument between us and you. Allah will bring us together, and to Him is the [final] destination."' },
  { surahId: 42, ayahNumber: 16, text: 'And those who argue concerning Allah after He has been responded to - their argument is invalid with their Lord, and upon them is [His] wrath, and for them is a severe punishment.' },
  { surahId: 42, ayahNumber: 17, text: 'It is Allah who has sent down the Book in truth and [also] the balance. And what will make you perceive? Perhaps the Hour is near.' },
  { surahId: 42, ayahNumber: 18, text: 'Those who do not believe in it are impatient for it, but those who believe are fearful of it and know that it is the truth. Unquestionably, those who dispute concerning the Hour are in extreme error.' },
  { surahId: 42, ayahNumber: 19, text: 'Allah is Subtle with His servants; He gives provisions to whom He wills. And He is the Powerful, the Exalted in Might.' },
  { surahId: 42, ayahNumber: 20, text: 'Whoever desires the harvest of the Hereafter - We increase for him in his harvest. And whoever desires the harvest of this world - We give him thereof, but there is not for him in the Hereafter any share.' },
  { surahId: 42, ayahNumber: 21, text: 'Or have they other deities who have ordained for them a religion to which Allah has not consented? But if not for the decisive word, it would have been concluded between them. And indeed, the wrongdoers will have a painful punishment.' },
  { surahId: 42, ayahNumber: 22, text: 'You will see the wrongdoers fearful of what they have earned, and it will [certainly] befall them. And those who have believed and done righteous deeds will be in lush regions of the gardens [in Paradise] having whatever they will in the presence of their Lord. That is what is the great bounty.' },
  { surahId: 42, ayahNumber: 23, text: 'It is that of which Allah gives good tidings to His servants who believe and do righteous deeds. Say, [O Muhammad], "I do not ask you for this message any payment [but] only good will through kinship." And whoever commits a good deed - We will increase for him good therein. Indeed, Allah is Forgiving and Appreciative.' },
  { surahId: 42, ayahNumber: 24, text: 'Or do they say, "He has invented about Allah a lie"? But if Allah willed, He could seal over your heart. And Allah eliminates falsehood and establishes the truth by His words. Indeed, He is Knowing of that within the breasts.' },
  { surahId: 42, ayahNumber: 25, text: 'And it is He who accepts repentance from his servants and pardons misdeeds, and He knows what you do.' },
  { surahId: 42, ayahNumber: 26, text: 'And He answers [the supplication of] those who have believed and done righteous deeds and increases [for] them from His bounty. But the disbelievers will have a severe punishment.' },
  { surahId: 42, ayahNumber: 27, text: 'And if Allah had extended [excessively] provision for His servants, they would have committed tyranny throughout the earth. But He sends [it] down in an amount which He wills. Indeed He is, of His servants, Acquainted and Seeing.' },
  { surahId: 42, ayahNumber: 28, text: 'And it is He who sends down the rain after they had despaired and spreads His mercy. And He is the Protector, the Praiseworthy.' },
  { surahId: 42, ayahNumber: 29, text: 'And of his signs is the creation of the heavens and earth and what He has dispersed throughout them of creatures. And He, for gathering them when He wills, is competent.' },
  { surahId: 42, ayahNumber: 30, text: 'And whatever strikes you of disaster - it is for what your hands have earned; but He pardons much.' },
  { surahId: 42, ayahNumber: 31, text: 'And you will not cause failure [to Allah] upon the earth. And you have not besides Allah any protector or helper.' },
  { surahId: 42, ayahNumber: 32, text: 'And of His signs are the ships in the sea, like mountains.' },
  { surahId: 42, ayahNumber: 33, text: 'If He willed, He could still the wind, and they would remain motionless on its surface. Indeed in that are signs for everyone patient and grateful.' },
  { surahId: 42, ayahNumber: 34, text: 'Or He could destroy them for what they earned; but He pardons much.' },
  { surahId: 42, ayahNumber: 35, text: 'And [that is so] those who dispute concerning Our signs may know that for them there is no place of escape.' },
  { surahId: 42, ayahNumber: 36, text: 'So whatever thing you have been given - it is but [for] enjoyment of the worldly life. But what is with Allah is better and more lasting for those who have believed and upon their Lord rely' },
  { surahId: 42, ayahNumber: 37, text: 'And those who avoid the major sins and immoralities, and when they are angry, they forgive,' },
  { surahId: 42, ayahNumber: 38, text: 'And those who have responded to their lord and established prayer and whose affair is [determined by] consultation among themselves, and from what We have provided them, they spend.' },
  { surahId: 42, ayahNumber: 39, text: 'And those who, when tyranny strikes them, they defend themselves,' },
  { surahId: 42, ayahNumber: 40, text: 'And the retribution for an evil act is an evil one like it, but whoever pardons and makes reconciliation - his reward is [due] from Allah. Indeed, He does not like wrongdoers.' },
  { surahId: 42, ayahNumber: 41, text: 'And whoever avenges himself after having been wronged - those have not upon them any cause [for blame].' },
  { surahId: 42, ayahNumber: 42, text: 'The cause is only against the ones who wrong the people and tyrannize upon the earth without right. Those will have a painful punishment.' },
  { surahId: 42, ayahNumber: 43, text: 'And whoever is patient and forgives - indeed, that is of the matters [requiring] determination.' },
  { surahId: 42, ayahNumber: 44, text: 'And he whom Allah sends astray - for him there is no protector beyond Him. And you will see the wrongdoers, when they see the punishment, saying, "Is there for return [to the former world] any way?"' },
  { surahId: 42, ayahNumber: 45, text: 'And you will see them being exposed to the Fire, humbled from humiliation, looking from [behind] a covert glance. And those who had believed will say, "Indeed, the [true] losers are the ones who lost themselves and their families on the Day of Resurrection. Unquestionably, the wrongdoers are in an enduring punishment."' },
  { surahId: 42, ayahNumber: 46, text: 'And there will not be for them any allies to aid them other than Allah. And whoever Allah sends astray - for him there is no way.' },
  { surahId: 42, ayahNumber: 47, text: 'Respond to your Lord before a Day comes from Allah of which there is no repelling. No refuge will you have that day, nor for you will there be any denial.' },
  { surahId: 42, ayahNumber: 48, text: 'But if they turn away - then We have not sent you, [O Muhammad], over them as a guardian; upon you is only [the duty of] notification. And indeed, when We let man taste mercy from us, he rejoices in it; but if evil afflicts him for what his hands have put forth, then indeed, man is ungrateful.' },
  { surahId: 42, ayahNumber: 49, text: 'To Allah belongs the dominion of the heavens and the earth; He creates what he wills. He gives to whom He wills female [children], and He gives to whom He wills males.' },
  { surahId: 42, ayahNumber: 50, text: 'Or He makes them [both] males and females, and He renders whom He wills barren. Indeed, He is Knowing and Competent.' },
  { surahId: 42, ayahNumber: 51, text: 'And it is not for any human being that Allah should speak to him except by revelation or from behind a partition or that He sends a messenger to reveal, by His permission, what He wills. Indeed, He is Most High and Wise.' },
  { surahId: 42, ayahNumber: 52, text: 'And thus We have revealed to you an inspiration of Our command. You did not know what is the Book or [what is] faith, but We have made it a light by which We guide whom We will of Our servants. And indeed, [O Muhammad], you guide to a straight path -' },
  { surahId: 42, ayahNumber: 53, text: 'The path of Allah, to whom belongs whatever is in the heavens and whatever is on the earth. Unquestionably, to Allah do [all] matters evolve.' },
  { surahId: 43, ayahNumber: 1, text: 'Ha, Meem.' },
  { surahId: 43, ayahNumber: 2, text: 'By the clear Book,' },
  { surahId: 43, ayahNumber: 3, text: 'Indeed, We have made it an Arabic Qur\'an that you might understand.' },
  { surahId: 43, ayahNumber: 4, text: 'And indeed it is, in the Mother of the Book with Us, exalted and full of wisdom.' },
  { surahId: 43, ayahNumber: 5, text: 'Then should We turn the message away, disregarding you, because you are a transgressing people?' },
  { surahId: 43, ayahNumber: 6, text: 'And how many a prophet We sent among the former peoples,' },
  { surahId: 43, ayahNumber: 7, text: 'But there would not come to them a prophet except that they used to ridicule him.' },
  { surahId: 43, ayahNumber: 8, text: 'And We destroyed greater than them in [striking] power, and the example of the former peoples has preceded.' },
  { surahId: 43, ayahNumber: 9, text: 'And if you should ask them, "Who has created the heavens and the earth?" they would surely say, "They were created by the Exalted in Might, the Knowing."' },
  { surahId: 43, ayahNumber: 10, text: '[The one] who has made for you the earth a bed and made for you upon it roads that you might be guided' },
  { surahId: 43, ayahNumber: 11, text: 'And who sends down rain from the sky in measured amounts, and We revive thereby a dead land - thus will you be brought forth -' },
  { surahId: 43, ayahNumber: 12, text: 'And who created the species, all of them, and has made for you of ships and animals those which you mount.' },
  { surahId: 43, ayahNumber: 13, text: 'That you may settle yourselves upon their backs and then remember the favor of your Lord when you have settled upon them and say. "Exalted is He who has subjected this to us, and we could not have [otherwise] subdued it.' },
  { surahId: 43, ayahNumber: 14, text: 'And indeed we, to our Lord, will [surely] return."' },
  { surahId: 43, ayahNumber: 15, text: 'But they have attributed to Him from His servants a portion. Indeed, man is clearly ungrateful.' },
  { surahId: 43, ayahNumber: 16, text: 'Or has He taken, out of what He has created, daughters and chosen you for [having] sons?' },
  { surahId: 43, ayahNumber: 17, text: 'And when one of them is given good tidings of that which he attributes to the Most Merciful in comparison, his face becomes dark, and he suppresses grief.' },
  { surahId: 43, ayahNumber: 18, text: 'So is one brought up in ornaments while being during conflict unevident [attributed to Allah]?' },
  { surahId: 43, ayahNumber: 19, text: 'And they have made the angels, who are servants of the Most Merciful, females. Did they witness their creation? Their testimony will be recorded, and they will be questioned.' },
  { surahId: 43, ayahNumber: 20, text: 'And they said, "If the Most Merciful had willed, we would not have worshipped them." They have of that no knowledge. They are not but falsifying.' },
  { surahId: 43, ayahNumber: 21, text: 'Or have We given them a book before the Qur\'an to which they are adhering?' },
  { surahId: 43, ayahNumber: 22, text: 'Rather, they say, "Indeed, we found our fathers upon a religion, and we are in their footsteps [rightly] guided."' },
  { surahId: 43, ayahNumber: 23, text: 'And similarly, We did not send before you any warner into a city except that its affluent said, "Indeed, we found our fathers upon a religion, and we are, in their footsteps, following."' },
  { surahId: 43, ayahNumber: 24, text: '[Each warner] said, "Even if I brought you better guidance than that [religion] upon which you found your fathers?" They said, "Indeed we, in that with which you were sent, are disbelievers."' },
  { surahId: 43, ayahNumber: 25, text: 'So we took retribution from them; then see how was the end of the deniers.' },
  { surahId: 43, ayahNumber: 26, text: 'And [mention, O Muhammad], when Abraham said to his father and his people, "Indeed, I am disassociated from that which you worship' },
  { surahId: 43, ayahNumber: 27, text: 'Except for He who created me; and indeed, He will guide me."' },
  { surahId: 43, ayahNumber: 28, text: 'And he made it a word remaining among his descendants that they might return [to it].' },
  { surahId: 43, ayahNumber: 29, text: 'However, I gave enjoyment to these [people of Makkah] and their fathers until there came to them the truth and a clear Messenger.' },
  { surahId: 43, ayahNumber: 30, text: 'But when the truth came to them, they said, "This is magic, and indeed we are, concerning it, disbelievers."' },
  { surahId: 43, ayahNumber: 31, text: 'And they said, "Why was this Qur\'an not sent down upon a great man from [one of] the two cities?"' },
  { surahId: 43, ayahNumber: 32, text: 'Do they distribute the mercy of your Lord? It is We who have apportioned among them their livelihood in the life of this world and have raised some of them above others in degrees [of rank] that they may make use of one another for service. But the mercy of your Lord is better than whatever they accumulate.' },
  { surahId: 43, ayahNumber: 33, text: 'And if it were not that the people would become one community [of disbelievers], We would have made for those who disbelieve in the Most Merciful - for their houses - ceilings and stairways of silver upon which to mount' },
  { surahId: 43, ayahNumber: 34, text: 'And for their houses - doors and couches [of silver] upon which to recline' },
  { surahId: 43, ayahNumber: 35, text: 'And gold ornament. But all that is not but the enjoyment of worldly life. And the Hereafter with your Lord is for the righteous.' },
  { surahId: 43, ayahNumber: 36, text: 'And whoever is blinded from remembrance of the Most Merciful - We appoint for him a devil, and he is to him a companion.' },
  { surahId: 43, ayahNumber: 37, text: 'And indeed, the devils avert them from the way [of guidance] while they think that they are [rightly] guided' },
  { surahId: 43, ayahNumber: 38, text: 'Until, when he comes to Us [at Judgement], he says [to his companion], "Oh, I wish there was between me and you the distance between the east and west - how wretched a companion."' },
  { surahId: 43, ayahNumber: 39, text: 'And never will it benefit you that Day, when you have wronged, that you are [all] sharing in the punishment.' },
  { surahId: 43, ayahNumber: 40, text: 'Then will you make the deaf hear, [O Muhammad], or guide the blind or he who is in clear error?' },
  { surahId: 43, ayahNumber: 41, text: 'And whether [or not] We take you away [in death], indeed, We will take retribution upon them.' },
  { surahId: 43, ayahNumber: 42, text: 'Or whether [or not] We show you that which We have promised them, indeed, We are Perfect in Ability.' },
  { surahId: 43, ayahNumber: 43, text: 'So adhere to that which is revealed to you. Indeed, you are on a straight path.' },
  { surahId: 43, ayahNumber: 44, text: 'And indeed, it is a remembrance for you and your people, and you [all] are going to be questioned.' },
  { surahId: 43, ayahNumber: 45, text: 'And ask those We sent before you of Our messengers; have We made besides the Most Merciful deities to be worshipped?' },
  { surahId: 43, ayahNumber: 46, text: 'And certainly did We send Moses with Our signs to Pharaoh and his establishment, and he said, "Indeed, I am the messenger of the Lord of the worlds."' },
  { surahId: 43, ayahNumber: 47, text: 'But when he brought them Our signs, at once they laughed at them.' },
  { surahId: 43, ayahNumber: 48, text: 'And We showed them not a sign except that it was greater than its sister, and We seized them with affliction that perhaps they might return [to faith].' },
  { surahId: 43, ayahNumber: 49, text: 'And they said [to Moses], "O magician, invoke for us your Lord by what He has promised you. Indeed, we will be guided."' },
  { surahId: 43, ayahNumber: 50, text: 'But when We removed from them the affliction, at once they broke their word.' },
  { surahId: 43, ayahNumber: 51, text: 'And Pharaoh called out among his people; he said, "O my people, does not the kingdom of Egypt belong to me, and these rivers flowing beneath me; then do you not see?' },
  { surahId: 43, ayahNumber: 52, text: 'Or am I [not] better than this one who is insignificant and hardly makes himself clear?' },
  { surahId: 43, ayahNumber: 53, text: 'Then why have there not been placed upon him bracelets of gold or come with him the angels in conjunction?"' },
  { surahId: 43, ayahNumber: 54, text: 'So he bluffed his people, and they obeyed him. Indeed, they were [themselves] a people defiantly disobedient [of Allah].' },
  { surahId: 43, ayahNumber: 55, text: 'And when they angered Us, We took retribution from them and drowned them all.' },
  { surahId: 43, ayahNumber: 56, text: 'And We made them a precedent and an example for the later peoples.' },
  { surahId: 43, ayahNumber: 57, text: 'And when the son of Mary was presented as an example, immediately your people laughed aloud.' },
  { surahId: 43, ayahNumber: 58, text: 'And they said, "Are your gods better, or is he?" They did not present the comparison except for [mere] argument. But, [in fact], they are a people prone to dispute.' },
  { surahId: 43, ayahNumber: 59, text: 'Jesus was not but a servant upon whom We bestowed favor, and We made him an example for the Children of Israel.' },
  { surahId: 43, ayahNumber: 60, text: 'And if We willed, We could have made [instead] of you angels succeeding [one another] on the earth.' },
  { surahId: 43, ayahNumber: 61, text: 'And indeed, Jesus will be [a sign for] knowledge of the Hour, so be not in doubt of it, and follow Me. This is a straight path.' },
  { surahId: 43, ayahNumber: 62, text: 'And never let Satan avert you. Indeed, he is to you a clear enemy.' },
  { surahId: 43, ayahNumber: 63, text: 'And when Jesus brought clear proofs, he said, "I have come to you with wisdom and to make clear to you some of that over which you differ, so fear Allah and obey me.' },
  { surahId: 43, ayahNumber: 64, text: 'Indeed, Allah is my Lord and your Lord, so worship Him. This is a straight path."' },
  { surahId: 43, ayahNumber: 65, text: 'But the denominations from among them differed [and separated], so woe to those who have wronged from the punishment of a painful Day.' },
  { surahId: 43, ayahNumber: 66, text: 'Are they waiting except for the Hour to come upon them suddenly while they perceive not?' },
  { surahId: 43, ayahNumber: 67, text: 'Close friends, that Day, will be enemies to each other, except for the righteous' },
  { surahId: 43, ayahNumber: 68, text: '[To whom Allah will say], "O My servants, no fear will there be concerning you this Day, nor will you grieve,' },
  { surahId: 43, ayahNumber: 69, text: '[You] who believed in Our verses and were Muslims.' },
  { surahId: 43, ayahNumber: 70, text: 'Enter Paradise, you and your kinds, delighted."' },
  { surahId: 43, ayahNumber: 71, text: 'Circulated among them will be plates and vessels of gold. And therein is whatever the souls desire and [what] delights the eyes, and you will abide therein eternally.' },
  { surahId: 43, ayahNumber: 72, text: 'And that is Paradise which you are made to inherit for what you used to do.' },
  { surahId: 43, ayahNumber: 73, text: 'For you therein is much fruit from which you will eat.' },
  { surahId: 43, ayahNumber: 74, text: 'Indeed, the criminals will be in the punishment of Hell, abiding eternally.' },
  { surahId: 43, ayahNumber: 75, text: 'It will not be allowed to subside for them, and they, therein, are in despair.' },
  { surahId: 43, ayahNumber: 76, text: 'And We did not wrong them, but it was they who were the wrongdoers.' },
  { surahId: 43, ayahNumber: 77, text: 'And they will call, "O Malik, let your Lord put an end to us!" He will say, "Indeed, you will remain."' },
  { surahId: 43, ayahNumber: 78, text: 'We had certainly brought you the truth, but most of you, to the truth, were averse.' },
  { surahId: 43, ayahNumber: 79, text: 'Or have they devised [some] affair? But indeed, We are devising [a plan].' },
  { surahId: 43, ayahNumber: 80, text: 'Or do they think that We hear not their secrets and their private conversations? Yes, [We do], and Our messengers are with them recording.' },
  { surahId: 43, ayahNumber: 81, text: 'Say, [O Muhammad], "If the Most Merciful had a son, then I would be the first of [his] worshippers."' },
  { surahId: 43, ayahNumber: 82, text: 'Exalted is the Lord of the heavens and the earth, Lord of the Throne, above what they describe.' },
  { surahId: 43, ayahNumber: 83, text: 'So leave them to converse vainly and amuse themselves until they meet their Day which they are promised.' },
  { surahId: 43, ayahNumber: 84, text: 'And it is Allah who is [the only] deity in the heaven, and on the earth [the only] deity. And He is the Wise, the Knowing.' },
  { surahId: 43, ayahNumber: 85, text: 'And blessed is He to whom belongs the dominion of the heavens and the earth and whatever is between them and with whom is knowledge of the Hour and to whom you will be returned.' },
  { surahId: 43, ayahNumber: 86, text: 'And those they invoke besides Him do not possess [power of] intercession; but only those who testify to the truth [can benefit], and they know.' },
  { surahId: 43, ayahNumber: 87, text: 'And if you asked them who created them, they would surely say, "Allah." So how are they deluded?' },
  { surahId: 43, ayahNumber: 88, text: 'And [Allah acknowledges] his saying, "O my Lord, indeed these are a people who do not believe."' },
  { surahId: 43, ayahNumber: 89, text: 'So turn aside from them and say, "Peace." But they are going to know.' },
  { surahId: 44, ayahNumber: 1, text: 'Ha, Meem.' },
  { surahId: 44, ayahNumber: 2, text: 'By the clear Book,' },
  { surahId: 44, ayahNumber: 3, text: 'Indeed, We sent it down during a blessed night. Indeed, We were to warn [mankind].' },
  { surahId: 44, ayahNumber: 4, text: 'On that night is made distinct every precise matter -' },
  { surahId: 44, ayahNumber: 5, text: '[Every] matter [proceeding] from Us. Indeed, We were to send [a messenger]' },
  { surahId: 44, ayahNumber: 6, text: 'As mercy from your Lord. Indeed, He is the Hearing, the Knowing.' },
  { surahId: 44, ayahNumber: 7, text: 'Lord of the heavens and the earth and that between them, if you would be certain.' },
  { surahId: 44, ayahNumber: 8, text: 'There is no deity except Him; He gives life and causes death. [He is] your Lord and the Lord of your first forefathers.' },
  { surahId: 44, ayahNumber: 9, text: 'But they are in doubt, amusing themselves.' },
  { surahId: 44, ayahNumber: 10, text: 'Then watch for the Day when the sky will bring a visible smoke.' },
  { surahId: 44, ayahNumber: 11, text: 'Covering the people; this is a painful torment.' },
  { surahId: 44, ayahNumber: 12, text: '[They will say], "Our Lord, remove from us the torment; indeed, we are believers."' },
  { surahId: 44, ayahNumber: 13, text: 'How will there be for them a reminder [at that time]? And there had come to them a clear Messenger.' },
  { surahId: 44, ayahNumber: 14, text: 'Then they turned away from him and said, "[He was] taught [and is] a madman."' },
  { surahId: 44, ayahNumber: 15, text: 'Indeed, We will remove the torment for a little. Indeed, you [disbelievers] will return [to disbelief].' },
  { surahId: 44, ayahNumber: 16, text: 'The Day We will strike with the greatest assault, indeed, We will take retribution.' },
  { surahId: 44, ayahNumber: 17, text: 'And We had already tried before them the people of Pharaoh, and there came to them a noble messenger,' },
  { surahId: 44, ayahNumber: 18, text: '[Saying], "Render to me the servants of Allah. Indeed, I am to you a trustworthy messenger,"' },
  { surahId: 44, ayahNumber: 19, text: 'And [saying], "Be not haughty with Allah. Indeed, I have come to you with clear authority.' },
  { surahId: 44, ayahNumber: 20, text: 'And indeed, I have sought refuge in my Lord and your Lord, lest you stone me.' },
  { surahId: 44, ayahNumber: 21, text: 'But if you do not believe me, then leave me alone."' },
  { surahId: 44, ayahNumber: 22, text: 'And [finally] he called to his Lord that these were a criminal people.' },
  { surahId: 44, ayahNumber: 23, text: '[Allah said], "Then set out with My servants by night. Indeed, you are to be pursued.' },
  { surahId: 44, ayahNumber: 24, text: 'And leave the sea in stillness. Indeed, they are an army to be drowned."' },
  { surahId: 44, ayahNumber: 25, text: 'How much they left behind of gardens and springs' },
  { surahId: 44, ayahNumber: 26, text: 'And crops and noble sites' },
  { surahId: 44, ayahNumber: 27, text: 'And comfort wherein they were amused.' },
  { surahId: 44, ayahNumber: 28, text: 'Thus. And We caused to inherit it another people.' },
  { surahId: 44, ayahNumber: 29, text: 'And the heaven and earth wept not for them, nor were they reprieved.' },
  { surahId: 44, ayahNumber: 30, text: 'And We certainly saved the Children of Israel from the humiliating torment -' },
  { surahId: 44, ayahNumber: 31, text: 'From Pharaoh. Indeed, he was a haughty one among the transgressors.' },
  { surahId: 44, ayahNumber: 32, text: 'And We certainly chose them by knowledge over [all] the worlds.' },
  { surahId: 44, ayahNumber: 33, text: 'And We gave them of signs that in which there was a clear trial.' },
  { surahId: 44, ayahNumber: 34, text: 'Indeed, these [disbelievers] are saying,' },
  { surahId: 44, ayahNumber: 35, text: '"There is not but our first death, and we will not be resurrected.' },
  { surahId: 44, ayahNumber: 36, text: 'Then bring [back] our forefathers, if you should be truthful."' },
  { surahId: 44, ayahNumber: 37, text: 'Are they better or the people of Tubba\' and those before them? We destroyed them, [for] indeed, they were criminals.' },
  { surahId: 44, ayahNumber: 38, text: 'And We did not create the heavens and earth and that between them in play.' },
  { surahId: 44, ayahNumber: 39, text: 'We did not create them except in truth, but most of them do not know.' },
  { surahId: 44, ayahNumber: 40, text: 'Indeed, the Day of Judgement is the appointed time for them all -' },
  { surahId: 44, ayahNumber: 41, text: 'The Day when no relation will avail a relation at all, nor will they be helped -' },
  { surahId: 44, ayahNumber: 42, text: 'Except those [believers] on whom Allah has mercy. Indeed, He is the Exalted in Might, the Merciful.' },
  { surahId: 44, ayahNumber: 43, text: 'Indeed, the tree of zaqqum' },
  { surahId: 44, ayahNumber: 44, text: 'Is food for the sinful.' },
  { surahId: 44, ayahNumber: 45, text: 'Like murky oil, it boils within bellies' },
  { surahId: 44, ayahNumber: 46, text: 'Like the boiling of scalding water.' },
  { surahId: 44, ayahNumber: 47, text: '[It will be commanded], "Seize him and drag him into the midst of the Hellfire,' },
  { surahId: 44, ayahNumber: 48, text: 'Then pour over his head from the torment of scalding water."' },
  { surahId: 44, ayahNumber: 49, text: '[It will be said], "Taste! Indeed, you are the honored, the noble!' },
  { surahId: 44, ayahNumber: 50, text: 'Indeed, this is what you used to dispute."' },
  { surahId: 44, ayahNumber: 51, text: 'Indeed, the righteous will be in a secure place;' },
  { surahId: 44, ayahNumber: 52, text: 'Within gardens and springs,' },
  { surahId: 44, ayahNumber: 53, text: 'Wearing [garments of] fine silk and brocade, facing each other.' },
  { surahId: 44, ayahNumber: 54, text: 'Thus. And We will marry them to fair women with large, [beautiful] eyes.' },
  { surahId: 44, ayahNumber: 55, text: 'They will call therein for every [kind of] fruit - safe and secure.' },
  { surahId: 44, ayahNumber: 56, text: 'They will not taste death therein except the first death, and He will have protected them from the punishment of Hellfire' },
  { surahId: 44, ayahNumber: 57, text: 'As bounty from your Lord. That is what is the great attainment.' },
  { surahId: 44, ayahNumber: 58, text: 'And indeed, We have eased the Qur\'an in your tongue that they might be reminded.' },
  { surahId: 44, ayahNumber: 59, text: 'So watch, [O Muhammad]; indeed, they are watching [for your end].' },
  { surahId: 45, ayahNumber: 1, text: 'Ha, Meem.' },
  { surahId: 45, ayahNumber: 2, text: 'The revelation of the Book is from Allah, the Exalted in Might, the Wise.' },
  { surahId: 45, ayahNumber: 3, text: 'Indeed, within the heavens and earth are signs for the believers.' },
  { surahId: 45, ayahNumber: 4, text: 'And in the creation of yourselves and what He disperses of moving creatures are signs for people who are certain [in faith].' },
  { surahId: 45, ayahNumber: 5, text: 'And [in] the alternation of night and day and [in] what Allah sends down from the sky of provision and gives life thereby to the earth after its lifelessness and [in His] directing of the winds are signs for a people who reason.' },
  { surahId: 45, ayahNumber: 6, text: 'These are the verses of Allah which We recite to you in truth. Then in what statement after Allah and His verses will they believe?' },
  { surahId: 45, ayahNumber: 7, text: 'Woe to every sinful liar' },
  { surahId: 45, ayahNumber: 8, text: 'Who hears the verses of Allah recited to him, then persists arrogantly as if he had not heard them. So give him tidings of a painful punishment.' },
  { surahId: 45, ayahNumber: 9, text: 'And when he knows anything of Our verses, he takes them in ridicule. Those will have a humiliating punishment.' },
  { surahId: 45, ayahNumber: 10, text: 'Before them is Hell, and what they had earned will not avail them at all nor what they had taken besides Allah as allies. And they will have a great punishment.' },
  { surahId: 45, ayahNumber: 11, text: 'This [Qur\'an] is guidance. And those who have disbelieved in the verses of their Lord will have a painful punishment of foul nature.' },
  { surahId: 45, ayahNumber: 12, text: 'It is Allah who subjected to you the sea so that ships may sail upon it by His command and that you may seek of His bounty; and perhaps you will be grateful.' },
  { surahId: 45, ayahNumber: 13, text: 'And He has subjected to you whatever is in the heavens and whatever is on the earth - all from Him. Indeed in that are signs for a people who give thought.' },
  { surahId: 45, ayahNumber: 14, text: 'Say, [O Muhammad], to those who have believed that they [should] forgive those who expect not the days of Allah so that He may recompense a people for what they used to earn.' },
  { surahId: 45, ayahNumber: 15, text: 'Whoever does a good deed - it is for himself; and whoever does evil - it is against the self. Then to your Lord you will be returned.' },
  { surahId: 45, ayahNumber: 16, text: 'And We did certainly give the Children of Israel the Scripture and judgement and prophethood, and We provided them with good things and preferred them over the worlds.' },
  { surahId: 45, ayahNumber: 17, text: 'And We gave them clear proofs of the matter [of religion]. And they did not differ except after knowledge had come to them - out of jealous animosity between themselves. Indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ.' },
  { surahId: 45, ayahNumber: 18, text: 'Then We put you, [O Muhammad], on an ordained way concerning the matter [of religion]; so follow it and do not follow the inclinations of those who do not know.' },
  { surahId: 45, ayahNumber: 19, text: 'Indeed, they will never avail you against Allah at all. And indeed, the wrongdoers are allies of one another; but Allah is the protector of the righteous.' },
  { surahId: 45, ayahNumber: 20, text: 'This [Qur\'an] is enlightenment for mankind and guidance and mercy for a people who are certain [in faith].' },
  { surahId: 45, ayahNumber: 21, text: 'Or do those who commit evils think We will make them like those who have believed and done righteous deeds - [make them] equal in their life and their death? Evil is that which they judge.' },
  { surahId: 45, ayahNumber: 22, text: 'And Allah created the heavens and earth in truth and so that every soul may be recompensed for what it has earned, and they will not be wronged.' },
  { surahId: 45, ayahNumber: 23, text: 'Have you seen he who has taken as his god his [own] desire, and Allah has sent him astray due to knowledge and has set a seal upon his hearing and his heart and put over his vision a veil? So who will guide him after Allah? Then will you not be reminded?' },
  { surahId: 45, ayahNumber: 24, text: 'And they say, "There is not but our worldly life; we die and live, and nothing destroys us except time." And they have of that no knowledge; they are only assuming.' },
  { surahId: 45, ayahNumber: 25, text: 'And when Our verses are recited to them as clear evidences, their argument is only that they say, "Bring [back] our forefathers, if you should be truthful."' },
  { surahId: 45, ayahNumber: 26, text: 'Say, "Allah causes you to live, then causes you to die; then He will assemble you for the Day of Resurrection, about which there is no doubt, but most of the people do not know."' },
  { surahId: 45, ayahNumber: 27, text: 'And to Allah belongs the dominion of the heavens and the earth. And the Day the Hour appears - that Day the falsifiers will lose.' },
  { surahId: 45, ayahNumber: 28, text: 'And you will see every nation kneeling [from fear]. Every nation will be called to its record [and told], "Today you will be recompensed for what you used to do.' },
  { surahId: 45, ayahNumber: 29, text: 'This, Our record, speaks about you in truth. Indeed, We were having transcribed whatever you used to do."' },
  { surahId: 45, ayahNumber: 30, text: 'So as for those who believed and did righteous deeds, their Lord will admit them into His mercy. That is what is the clear attainment.' },
  { surahId: 45, ayahNumber: 31, text: 'But as for those who disbelieved, [it will be said], "Were not Our verses recited to you, but you were arrogant and became a people of criminals?' },
  { surahId: 45, ayahNumber: 32, text: 'And when it was said, \'Indeed, the promise of Allah is truth and the Hour [is coming] - no doubt about it,\' you said, \'We know not what is the Hour. We assume only assumption, and we are not convinced.\' "' },
  { surahId: 45, ayahNumber: 33, text: 'And the evil consequences of what they did will appear to them, and they will be enveloped by what they used to ridicule.' },
  { surahId: 45, ayahNumber: 34, text: 'And it will be said, "Today We will forget you as you forgot the meeting of this Day of yours, and your refuge is the Fire, and for you there are no helpers.' },
  { surahId: 45, ayahNumber: 35, text: 'That is because you took the verses of Allah in ridicule, and worldly life deluded you." So that Day they will not be removed from it, nor will they be asked to appease [Allah].' },
  { surahId: 45, ayahNumber: 36, text: 'Then, to Allah belongs [all] praise - Lord of the heavens and Lord of the earth, Lord of the worlds.' },
  { surahId: 45, ayahNumber: 37, text: 'And to Him belongs [all] grandeur within the heavens and the earth, and He is the Exalted in Might, the Wise.' },
  { surahId: 46, ayahNumber: 1, text: 'Ha, Meem.' },
  { surahId: 46, ayahNumber: 2, text: 'The revelation of the Book is from Allah, the Exalted in Might, the Wise.' },
  { surahId: 46, ayahNumber: 3, text: 'We did not create the heavens and earth and what is between them except in truth and [for] a specified term. But those who disbelieve, from that of which they are warned, are turning away.' },
  { surahId: 46, ayahNumber: 4, text: 'Say, [O Muhammad], "Have you considered that which you invoke besides Allah? Show me what they have created of the earth; or did they have partnership in [creation of] the heavens? Bring me a scripture [revealed] before this or a [remaining] trace of knowledge, if you should be truthful."' },
  { surahId: 46, ayahNumber: 5, text: 'And who is more astray than he who invokes besides Allah those who will not respond to him until the Day of Resurrection, and they, of their invocation, are unaware.' },
  { surahId: 46, ayahNumber: 6, text: 'And when the people are gathered [that Day], they [who were invoked] will be enemies to them, and they will be deniers of their worship.' },
  { surahId: 46, ayahNumber: 7, text: 'And when Our verses are recited to them as clear evidences, those who disbelieve say of the truth when it has come to them, "This is obvious magic."' },
  { surahId: 46, ayahNumber: 8, text: 'Or do they say, "He has invented it?" Say, "If I have invented it, you will not possess for me [the power of protection] from Allah at all. He is most knowing of that in which you are involved. Sufficient is He as Witness between me and you, and He is the Forgiving the Merciful."' },
  { surahId: 46, ayahNumber: 9, text: 'Say, "I am not something original among the messengers, nor do I know what will be done with me or with you. I only follow that which is revealed to me, and I am not but a clear warner."' },
  { surahId: 46, ayahNumber: 10, text: 'Say, "Have you considered: if the Qur\'an was from Allah, and you disbelieved in it while a witness from the Children of Israel has testified to something similar and believed while you were arrogant...?" Indeed, Allah does not guide the wrongdoing people.' },
  { surahId: 46, ayahNumber: 11, text: 'And those who disbelieve say of those who believe, "If it had [truly] been good, they would not have preceded us to it." And when they are not guided by it, they will say, "This is an ancient falsehood."' },
  { surahId: 46, ayahNumber: 12, text: 'And before it was the scripture of Moses to lead and as a mercy. And this is a confirming Book in an Arabic tongue to warn those who have wronged and as good tidings to the doers of good.' },
  { surahId: 46, ayahNumber: 13, text: 'Indeed, those who have said, "Our Lord is Allah," and then remained on a right course - there will be no fear concerning them, nor will they grieve.' },
  { surahId: 46, ayahNumber: 14, text: 'Those are the companions of Paradise, abiding eternally therein as reward for what they used to do.' },
  { surahId: 46, ayahNumber: 15, text: 'And We have enjoined upon man, to his parents, good treatment. His mother carried him with hardship and gave birth to him with hardship, and his gestation and weaning [period] is thirty months. [He grows] until, when he reaches maturity and reaches [the age of] forty years, he says, "My Lord, enable me to be grateful for Your favor which You have bestowed upon me and upon my parents and to work righteousness of which You will approve and make righteous for me my offspring. Indeed, I have repented to You, and indeed, I am of the Muslims."' },
  { surahId: 46, ayahNumber: 16, text: 'Those are the ones from whom We will accept the best of what they did and overlook their misdeeds, [their being] among the companions of Paradise. [That is] the promise of truth which they had been promised.' },
  { surahId: 46, ayahNumber: 17, text: 'But one who says to his parents, "Uff to you; do you promise me that I will be brought forth [from the earth] when generations before me have already passed on [into oblivion]?" while they call to Allah for help [and to their son], "Woe to you! Believe! Indeed, the promise of Allah is truth." But he says, "This is not but legends of the former people" -' },
  { surahId: 46, ayahNumber: 18, text: 'Those are the ones upon whom the word has come into effect, [who will be] among nations which had passed on before them of jinn and men. Indeed, they [all] were losers.' },
  { surahId: 46, ayahNumber: 19, text: 'And for all there are degrees [of reward and punishment] for what they have done, and [it is] so that He may fully compensate them for their deeds, and they will not be wronged.' },
  { surahId: 46, ayahNumber: 20, text: 'And the Day those who disbelieved are exposed to the Fire [it will be said], "You exhausted your pleasures during your worldly life and enjoyed them, so this Day you will be awarded the punishment of [extreme] humiliation because you were arrogant upon the earth without right and because you were defiantly disobedient."' },
  { surahId: 46, ayahNumber: 21, text: 'And mention, [O Muhammad], the brother of \'Aad, when he warned his people in the [region of] al-Ahqaf - and warners had already passed on before him and after him - [saying], "Do not worship except Allah. Indeed, I fear for you the punishment of a terrible day."' },
  { surahId: 46, ayahNumber: 22, text: 'They said, "Have you come to delude us away from our gods? Then bring us what you promise us, if you should be of the truthful."' },
  { surahId: 46, ayahNumber: 23, text: 'He said, "Knowledge [of its time] is only with Allah, and I convey to you that with which I was sent; but I see you [to be] a people behaving ignorantly."' },
  { surahId: 46, ayahNumber: 24, text: 'And when they saw it as a cloud approaching their valleys, they said, "This is a cloud bringing us rain!" Rather, it is that for which you were impatient: a wind, within it a painful punishment,' },
  { surahId: 46, ayahNumber: 25, text: 'Destroying everything by command of its Lord. And they became so that nothing was seen [of them] except their dwellings. Thus do We recompense the criminal people.' },
  { surahId: 46, ayahNumber: 26, text: 'And We had certainly established them in such as We have not established you, and We made for them hearing and vision and hearts. But their hearing and vision and hearts availed them not from anything [of the punishment] when they were [continually] rejecting the signs of Allah; and they were enveloped by what they used to ridicule.' },
  { surahId: 46, ayahNumber: 27, text: 'And We have already destroyed what surrounds you of [those] cities, and We have diversified the signs [or verses] that perhaps they might return [from disbelief].' },
  { surahId: 46, ayahNumber: 28, text: 'Then why did those they took besides Allah as deities by which to approach [Him] not aid them? But they had strayed from them. And that was their falsehood and what they were inventing.' },
  { surahId: 46, ayahNumber: 29, text: 'And [mention, O Muhammad], when We directed to you a few of the jinn, listening to the Qur\'an. And when they attended it, they said, "Listen quietly." And when it was concluded, they went back to their people as warners.' },
  { surahId: 46, ayahNumber: 30, text: 'They said, "O our people, indeed we have heard a [recited] Book revealed after Moses confirming what was before it which guides to the truth and to a straight path.' },
  { surahId: 46, ayahNumber: 31, text: 'O our people, respond to the Messenger of Allah and believe in him; Allah will forgive for you your sins and protect you from a painful punishment.' },
  { surahId: 46, ayahNumber: 32, text: 'But he who does not respond to the Caller of Allah will not cause failure [to Him] upon earth, and he will not have besides Him any protectors. Those are in manifest error."' },
  { surahId: 46, ayahNumber: 33, text: 'Do they not see that Allah, who created the heavens and earth and did not fail in their creation, is able to give life to the dead? Yes. Indeed, He is over all things competent.' },
  { surahId: 46, ayahNumber: 34, text: 'And the Day those who disbelieved are exposed to the Fire [it will be said], "Is this not the truth?" They will say, "Yes, by our Lord." He will say, "Then taste the punishment because you used to disbelieve."' },
  { surahId: 46, ayahNumber: 35, text: 'So be patient, [O Muhammad], as were those of determination among the messengers and do not be impatient for them. It will be - on the Day they see that which they are promised - as though they had not remained [in the world] except an hour of a day. [This is] notification. And will [any] be destroyed except the defiantly disobedient people?' },
  { surahId: 47, ayahNumber: 1, text: 'Those who disbelieve and avert [people] from the way of Allah - He will waste their deeds.' },
  { surahId: 47, ayahNumber: 2, text: 'And those who believe and do righteous deeds and believe in what has been sent down upon Muhammad - and it is the truth from their Lord - He will remove from them their misdeeds and amend their condition.' },
  { surahId: 47, ayahNumber: 3, text: 'That is because those who disbelieve follow falsehood, and those who believe follow the truth from their Lord. Thus does Allah present to the people their comparisons.' },
  { surahId: 47, ayahNumber: 4, text: 'So when you meet those who disbelieve [in battle], strike [their] necks until, when you have inflicted slaughter upon them, then secure their bonds, and either [confer] favor afterwards or ransom [them] until the war lays down its burdens. That [is the command]. And if Allah had willed, He could have taken vengeance upon them [Himself], but [He ordered armed struggle] to test some of you by means of others. And those who are killed in the cause of Allah - never will He waste their deeds.' },
  { surahId: 47, ayahNumber: 5, text: 'He will guide them and amend their condition' },
  { surahId: 47, ayahNumber: 6, text: 'And admit them to Paradise, which He has made known to them.' },
  { surahId: 47, ayahNumber: 7, text: 'O you who have believed, if you support Allah, He will support you and plant firmly your feet.' },
  { surahId: 47, ayahNumber: 8, text: 'But those who disbelieve - for them is misery, and He will waste their deeds.' },
  { surahId: 47, ayahNumber: 9, text: 'That is because they disliked what Allah revealed, so He rendered worthless their deeds.' },
  { surahId: 47, ayahNumber: 10, text: 'Have they not traveled through the land and seen how was the end of those before them? Allah destroyed [everything] over them, and for the disbelievers is something comparable.' },
  { surahId: 47, ayahNumber: 11, text: 'That is because Allah is the protector of those who have believed and because the disbelievers have no protector.' },
  { surahId: 47, ayahNumber: 12, text: 'Indeed, Allah will admit those who have believed and done righteous deeds to gardens beneath which rivers flow, but those who disbelieve enjoy themselves and eat as grazing livestock eat, and the Fire will be a residence for them.' },
  { surahId: 47, ayahNumber: 13, text: 'And how many a city was stronger than your city [Makkah] which drove you out? We destroyed them; and there was no helper for them.' },
  { surahId: 47, ayahNumber: 14, text: 'So is he who is on clear evidence from his Lord like him to whom the evil of his work has been made attractive and they follow their [own] desires?' },
  { surahId: 47, ayahNumber: 15, text: 'Is the description of Paradise, which the righteous are promised, wherein are rivers of water unaltered, rivers of milk the taste of which never changes, rivers of wine delicious to those who drink, and rivers of purified honey, in which they will have from all [kinds of] fruits and forgiveness from their Lord, like [that of] those who abide eternally in the Fire and are given to drink scalding water that will sever their intestines?' },
  { surahId: 47, ayahNumber: 16, text: 'And among them, [O Muhammad], are those who listen to you, until when they depart from you, they say to those who were given knowledge, "What has he said just now?" Those are the ones of whom Allah has sealed over their hearts and who have followed their [own] desires.' },
  { surahId: 47, ayahNumber: 17, text: 'And those who are guided - He increases them in guidance and gives them their righteousness.' },
  { surahId: 47, ayahNumber: 18, text: 'Then do they await except that the Hour should come upon them unexpectedly? But already there have come [some of] its indications. Then what good to them, when it has come, will be their remembrance?' },
  { surahId: 47, ayahNumber: 19, text: 'So know, [O Muhammad], that there is no deity except Allah and ask forgiveness for your sin and for the believing men and believing women. And Allah knows of your movement and your resting place.' },
  { surahId: 47, ayahNumber: 20, text: 'Those who believe say, "Why has a surah not been sent down? But when a precise surah is revealed and fighting is mentioned therein, you see those in whose hearts is hypocrisy looking at you with a look of one overcome by death. And more appropriate for them [would have been]' },
  { surahId: 47, ayahNumber: 21, text: 'Obedience and good words. And when the matter [of fighting] was determined, if they had been true to Allah, it would have been better for them.' },
  { surahId: 47, ayahNumber: 22, text: 'So would you perhaps, if you turned away, cause corruption on earth and sever your [ties of] relationship?' },
  { surahId: 47, ayahNumber: 23, text: 'Those [who do so] are the ones that Allah has cursed, so He deafened them and blinded their vision.' },
  { surahId: 47, ayahNumber: 24, text: 'Then do they not reflect upon the Qur\'an, or are there locks upon [their] hearts?' },
  { surahId: 47, ayahNumber: 25, text: 'Indeed, those who reverted back [to disbelief] after guidance had become clear to them - Satan enticed them and prolonged hope for them.' },
  { surahId: 47, ayahNumber: 26, text: 'That is because they said to those who disliked what Allah sent down, "We will obey you in part of the matter." And Allah knows what they conceal.' },
  { surahId: 47, ayahNumber: 27, text: 'Then how [will it be] when the angels take them in death, striking their faces and their backs?' },
  { surahId: 47, ayahNumber: 28, text: 'That is because they followed what angered Allah and disliked [what earns] His pleasure, so He rendered worthless their deeds.' },
  { surahId: 47, ayahNumber: 29, text: 'Or do those in whose hearts is disease think that Allah would never expose their [feelings of] hatred?' },
  { surahId: 47, ayahNumber: 30, text: 'And if We willed, We could show them to you, and you would know them by their mark; but you will surely know them by the tone of [their] speech. And Allah knows your deeds.' },
  { surahId: 47, ayahNumber: 31, text: 'And We will surely test you until We make evident those who strive among you [for the cause of Allah] and the patient, and We will test your affairs.' },
  { surahId: 47, ayahNumber: 32, text: 'Indeed, those who disbelieved and averted [people] from the path of Allah and opposed the Messenger after guidance had become clear to them - never will they harm Allah at all, and He will render worthless their deeds.' },
  { surahId: 47, ayahNumber: 33, text: 'O you who have believed, obey Allah and obey the Messenger and do not invalidate your deeds.' },
  { surahId: 47, ayahNumber: 34, text: 'Indeed, those who disbelieved and averted [people] from the path of Allah and then died while they were disbelievers - never will Allah forgive them.' },
  { surahId: 47, ayahNumber: 35, text: 'So do not weaken and call for peace while you are superior; and Allah is with you and will never deprive you of [the reward of] your deeds.' },
  { surahId: 47, ayahNumber: 36, text: '[This] worldly life is only amusement and diversion. And if you believe and fear Allah, He will give you your rewards and not ask you for your properties.' },
  { surahId: 47, ayahNumber: 37, text: 'If He should ask you for them and press you, you would withhold, and He would expose your unwillingness.' },
  { surahId: 47, ayahNumber: 38, text: 'Here you are - those invited to spend in the cause of Allah - but among you are those who withhold [out of greed]. And whoever withholds only withholds [benefit] from himself; and Allah is the Free of need, while you are the needy. And if you turn away, He will replace you with another people; then they will not be the likes of you.' },
  { surahId: 48, ayahNumber: 1, text: 'Indeed, We have given you, [O Muhammad], a clear conquest' },
  { surahId: 48, ayahNumber: 2, text: 'That Allah may forgive for you what preceded of your sin and what will follow and complete His favor upon you and guide you to a straight path' },
  { surahId: 48, ayahNumber: 3, text: 'And [that] Allah may aid you with a mighty victory.' },
  { surahId: 48, ayahNumber: 4, text: 'It is He who sent down tranquillity into the hearts of the believers that they would increase in faith along with their [present] faith. And to Allah belong the soldiers of the heavens and the earth, and ever is Allah Knowing and Wise.' },
  { surahId: 48, ayahNumber: 5, text: '[And] that He may admit the believing men and the believing women to gardens beneath which rivers flow to abide therein eternally and remove from them their misdeeds - and ever is that, in the sight of Allah, a great attainment -' },
  { surahId: 48, ayahNumber: 6, text: 'And [that] He may punish the hypocrite men and hypocrite women, and the polytheist men and polytheist women - those who assume about Allah an assumption of evil nature. Upon them is a misfortune of evil nature; and Allah has become angry with them and has cursed them and prepared for them Hell, and evil it is as a destination.' },
  { surahId: 48, ayahNumber: 7, text: 'And to Allah belong the soldiers of the heavens and the earth. And ever is Allah Exalted in Might and Wise.' },
  { surahId: 48, ayahNumber: 8, text: 'Indeed, We have sent you as a witness and a bringer of good tidings and a warner' },
  { surahId: 48, ayahNumber: 9, text: 'That you [people] may believe in Allah and His Messenger and honor him and respect the Prophet and exalt Allah morning and afternoon.' },
  { surahId: 48, ayahNumber: 10, text: 'Indeed, those who pledge allegiance to you, [O Muhammad] - they are actually pledging allegiance to Allah. The hand of Allah is over their hands. So he who breaks his word only breaks it to the detriment of himself. And he who fulfills that which he has promised Allah - He will give him a great reward.' },
  { surahId: 48, ayahNumber: 11, text: 'Those who remained behind of the bedouins will say to you, "Our properties and our families occupied us, so ask forgiveness for us." They say with their tongues what is not within their hearts. Say, "Then who could prevent Allah at all if He intended for you harm or intended for you benefit? Rather, ever is Allah, with what you do, Acquainted.' },
  { surahId: 48, ayahNumber: 12, text: 'But you thought that the Messenger and the believers would never return to their families, ever, and that was made pleasing in your hearts. And you assumed an assumption of evil and became a people ruined."' },
  { surahId: 48, ayahNumber: 13, text: 'And whoever has not believed in Allah and His Messenger - then indeed, We have prepared for the disbelievers a Blaze.' },
  { surahId: 48, ayahNumber: 14, text: 'And to Allah belongs the dominion of the heavens and the earth. He forgives whom He wills and punishes whom He wills. And ever is Allah Forgiving and Merciful.' },
  { surahId: 48, ayahNumber: 15, text: 'Those who remained behind will say when you set out toward the war booty to take it, "Let us follow you." They wish to change the words of Allah. Say, "Never will you follow us. Thus did Allah say before." So they will say, "Rather, you envy us." But [in fact] they were not understanding except a little.' },
  { surahId: 48, ayahNumber: 16, text: 'Say to those who remained behind of the bedouins, "You will be called to [face] a people of great military might; you may fight them, or they will submit. So if you obey, Allah will give you a good reward; but if you turn away as you turned away before, He will punish you with a painful punishment."' },
  { surahId: 48, ayahNumber: 17, text: 'There is not upon the blind any guilt or upon the lame any guilt or upon the ill any guilt [for remaining behind]. And whoever obeys Allah and His Messenger - He will admit him to gardens beneath which rivers flow; but whoever turns away - He will punish him with a painful punishment.' },
  { surahId: 48, ayahNumber: 18, text: 'Certainly was Allah pleased with the believers when they pledged allegiance to you, [O Muhammad], under the tree, and He knew what was in their hearts, so He sent down tranquillity upon them and rewarded them with an imminent conquest' },
  { surahId: 48, ayahNumber: 19, text: 'And much war booty which they will take. And ever is Allah Exalted in Might and Wise.' },
  { surahId: 48, ayahNumber: 20, text: 'Allah has promised you much booty that you will take [in the future] and has hastened for you this [victory] and withheld the hands of people from you - that it may be a sign for the believers and [that] He may guide you to a straight path.' },
  { surahId: 48, ayahNumber: 21, text: 'And [He promises] other [victories] that you were [so far] unable to [realize] which Allah has already encompassed. And ever is Allah, over all things, competent.' },
  { surahId: 48, ayahNumber: 22, text: 'And if those [Makkans] who disbelieve had fought you, they would have turned their backs [in flight]. Then they would not find a protector or a helper.' },
  { surahId: 48, ayahNumber: 23, text: '[This is] the established way of Allah which has occurred before. And never will you find in the way of Allah any change.' },
  { surahId: 48, ayahNumber: 24, text: 'And it is He who withheld their hands from you and your hands from them within [the area of] Makkah after He caused you to overcome them. And ever is Allah of what you do, Seeing.' },
  { surahId: 48, ayahNumber: 25, text: 'They are the ones who disbelieved and obstructed you from al-Masjid al-Haram while the offering was prevented from reaching its place of sacrifice. And if not for believing men and believing women whom you did not know - that you might trample them and there would befall you because of them dishonor without [your] knowledge - [you would have been permitted to enter Makkah]. [This was so] that Allah might admit to His mercy whom He willed. If they had been apart [from them], We would have punished those who disbelieved among them with painful punishment' },
  { surahId: 48, ayahNumber: 26, text: 'When those who disbelieved had put into their hearts chauvinism - the chauvinism of the time of ignorance. But Allah sent down His tranquillity upon His Messenger and upon the believers and imposed upon them the word of righteousness, and they were more deserving of it and worthy of it. And ever is Allah, of all things, Knowing.' },
  { surahId: 48, ayahNumber: 27, text: 'Certainly has Allah showed to His Messenger the vision in truth. You will surely enter al-Masjid al-Haram, if Allah wills, in safety, with your heads shaved and [hair] shortened, not fearing [anyone]. He knew what you did not know and has arranged before that a conquest near [at hand].' },
  { surahId: 48, ayahNumber: 28, text: 'It is He who sent His Messenger with guidance and the religion of truth to manifest it over all religion. And sufficient is Allah as Witness.' },
  { surahId: 48, ayahNumber: 29, text: 'Muhammad is the Messenger of Allah; and those with him are forceful against the disbelievers, merciful among themselves. You see them bowing and prostrating [in prayer], seeking bounty from Allah and [His] pleasure. Their mark is on their faces from the trace of prostration. That is their description in the Torah. And their description in the Gospel is as a plant which produces its offshoots and strengthens them so they grow firm and stand upon their stalks, delighting the sowers - so that Allah may enrage by them the disbelievers. Allah has promised those who believe and do righteous deeds among them forgiveness and a great reward.' },
  { surahId: 49, ayahNumber: 1, text: 'O you who have believed, do not put [yourselves] before Allah and His Messenger but fear Allah. Indeed, Allah is Hearing and Knowing.' },
  { surahId: 49, ayahNumber: 2, text: 'O you who have believed, do not raise your voices above the voice of the Prophet or be loud to him in speech like the loudness of some of you to others, lest your deeds become worthless while you perceive not.' },
  { surahId: 49, ayahNumber: 3, text: 'Indeed, those who lower their voices before the Messenger of Allah - they are the ones whose hearts Allah has tested for righteousness. For them is forgiveness and great reward.' },
  { surahId: 49, ayahNumber: 4, text: 'Indeed, those who call you, [O Muhammad], from behind the chambers - most of them do not use reason.' },
  { surahId: 49, ayahNumber: 5, text: 'And if they had been patient until you [could] come out to them, it would have been better for them. But Allah is Forgiving and Merciful.' },
  { surahId: 49, ayahNumber: 6, text: 'O you who have believed, if there comes to you a disobedient one with information, investigate, lest you harm a people out of ignorance and become, over what you have done, regretful.' },
  { surahId: 49, ayahNumber: 7, text: 'And know that among you is the Messenger of Allah. If he were to obey you in much of the matter, you would be in difficulty, but Allah has endeared to you the faith and has made it pleasing in your hearts and has made hateful to you disbelief, defiance and disobedience. Those are the [rightly] guided.' },
  { surahId: 49, ayahNumber: 8, text: '[It is] as bounty from Allah and favor. And Allah is Knowing and Wise.' },
  { surahId: 49, ayahNumber: 9, text: 'And if two factions among the believers should fight, then make settlement between the two. But if one of them oppresses the other, then fight against the one that oppresses until it returns to the ordinance of Allah. And if it returns, then make settlement between them in justice and act justly. Indeed, Allah loves those who act justly.' },
  { surahId: 49, ayahNumber: 10, text: 'The believers are but brothers, so make settlement between your brothers. And fear Allah that you may receive mercy.' },
  { surahId: 49, ayahNumber: 11, text: 'O you who have believed, let not a people ridicule [another] people; perhaps they may be better than them; nor let women ridicule [other] women; perhaps they may be better than them. And do not insult one another and do not call each other by [offensive] nicknames. Wretched is the name of disobedience after [one\'s] faith. And whoever does not repent - then it is those who are the wrongdoers.' },
  { surahId: 49, ayahNumber: 12, text: 'O you who have believed, avoid much [negative] assumption. Indeed, some assumption is sin. And do not spy or backbite each other. Would one of you like to eat the flesh of his brother when dead? You would detest it. And fear Allah; indeed, Allah is Accepting of repentance and Merciful.' },
  { surahId: 49, ayahNumber: 13, text: 'O mankind, indeed We have created you from male and female and made you peoples and tribes that you may know one another. Indeed, the most noble of you in the sight of Allah is the most righteous of you. Indeed, Allah is Knowing and Acquainted.' },
  { surahId: 49, ayahNumber: 14, text: 'The bedouins say, "We have believed." Say, "You have not [yet] believed; but say [instead], \'We have submitted,\' for faith has not yet entered your hearts. And if you obey Allah and His Messenger, He will not deprive you from your deeds of anything. Indeed, Allah is Forgiving and Merciful."' },
  { surahId: 49, ayahNumber: 15, text: 'The believers are only the ones who have believed in Allah and His Messenger and then doubt not but strive with their properties and their lives in the cause of Allah. It is those who are the truthful.' },
  { surahId: 49, ayahNumber: 16, text: 'Say, "Would you acquaint Allah with your religion while Allah knows whatever is in the heavens and whatever is on the earth, and Allah is Knowing of all things?"' },
  { surahId: 49, ayahNumber: 17, text: 'They consider it a favor to you that they have accepted Islam. Say, "Do not consider your Islam a favor to me. Rather, Allah has conferred favor upon you that He has guided you to the faith, if you should be truthful."' },
  { surahId: 49, ayahNumber: 18, text: 'Indeed, Allah knows the unseen [aspects] of the heavens and the earth. And Allah is Seeing of what you do.' },
  { surahId: 50, ayahNumber: 1, text: 'Qaf. By the honored Qur\'an...' },
  { surahId: 50, ayahNumber: 2, text: 'But they wonder that there has come to them a warner from among themselves, and the disbelievers say, "This is an amazing thing.' },
  { surahId: 50, ayahNumber: 3, text: 'When we have died and have become dust, [we will return to life]? That is a distant return."' },
  { surahId: 50, ayahNumber: 4, text: 'We know what the earth diminishes of them, and with Us is a retaining record.' },
  { surahId: 50, ayahNumber: 5, text: 'But they denied the truth when it came to them, so they are in a confused condition.' },
  { surahId: 50, ayahNumber: 6, text: 'Have they not looked at the heaven above them - how We structured it and adorned it and [how] it has no rifts?' },
  { surahId: 50, ayahNumber: 7, text: 'And the earth - We spread it out and cast therein firmly set mountains and made grow therein [something] of every beautiful kind,' },
  { surahId: 50, ayahNumber: 8, text: 'Giving insight and a reminder for every servant who turns [to Allah].' },
  { surahId: 50, ayahNumber: 9, text: 'And We have sent down blessed rain from the sky and made grow thereby gardens and grain from the harvest' },
  { surahId: 50, ayahNumber: 10, text: 'And lofty palm trees having fruit arranged in layers -' },
  { surahId: 50, ayahNumber: 11, text: 'As provision for the servants, and We have given life thereby to a dead land. Thus is the resurrection.' },
  { surahId: 50, ayahNumber: 12, text: 'The people of Noah denied before them, and the companions of the well and Thamud' },
  { surahId: 50, ayahNumber: 13, text: 'And \'Aad and Pharaoh and the brothers of Lot' },
  { surahId: 50, ayahNumber: 14, text: 'And the companions of the thicket and the people of Tubba\'. All denied the messengers, so My threat was justly fulfilled.' },
  { surahId: 50, ayahNumber: 15, text: 'Did We fail in the first creation? But they are in confusion over a new creation.' },
  { surahId: 50, ayahNumber: 16, text: 'And We have already created man and know what his soul whispers to him, and We are closer to him than [his] jugular vein' },
  { surahId: 50, ayahNumber: 17, text: 'When the two receivers receive, seated on the right and on the left.' },
  { surahId: 50, ayahNumber: 18, text: 'Man does not utter any word except that with him is an observer prepared [to record].' },
  { surahId: 50, ayahNumber: 19, text: 'And the intoxication of death will bring the truth; that is what you were trying to avoid.' },
  { surahId: 50, ayahNumber: 20, text: 'And the Horn will be blown. That is the Day of [carrying out] the threat.' },
  { surahId: 50, ayahNumber: 21, text: 'And every soul will come, with it a driver and a witness.' },
  { surahId: 50, ayahNumber: 22, text: '[It will be said], "You were certainly in unmindfulness of this, and We have removed from you your cover, so your sight, this Day, is sharp."' },
  { surahId: 50, ayahNumber: 23, text: 'And his companion, [the angel], will say, "This [record] is what is with me, prepared."' },
  { surahId: 50, ayahNumber: 24, text: '[Allah will say], "Throw into Hell every obstinate disbeliever,' },
  { surahId: 50, ayahNumber: 25, text: 'Preventer of good, aggressor, and doubter,' },
  { surahId: 50, ayahNumber: 26, text: 'Who made [as equal] with Allah another deity; then throw him into the severe punishment."' },
  { surahId: 50, ayahNumber: 27, text: 'His [devil] companion will say, "Our Lord, I did not make him transgress, but he [himself] was in extreme error."' },
  { surahId: 50, ayahNumber: 28, text: '[Allah] will say, "Do not dispute before Me, while I had already presented to you the warning.' },
  { surahId: 50, ayahNumber: 29, text: 'The word will not be changed with Me, and never will I be unjust to the servants."' },
  { surahId: 50, ayahNumber: 30, text: 'On the Day We will say to Hell, "Have you been filled?" and it will say, "Are there some more,"' },
  { surahId: 50, ayahNumber: 31, text: 'And Paradise will be brought near to the righteous, not far,' },
  { surahId: 50, ayahNumber: 32, text: '[It will be said], "This is what you were promised - for every returner [to Allah] and keeper [of His covenant]' },
  { surahId: 50, ayahNumber: 33, text: 'Who feared the Most Merciful unseen and came with a heart returning [in repentance].' },
  { surahId: 50, ayahNumber: 34, text: 'Enter it in peace. This is the Day of Eternity."' },
  { surahId: 50, ayahNumber: 35, text: 'They will have whatever they wish therein, and with Us is more.' },
  { surahId: 50, ayahNumber: 36, text: 'And how many a generation before them did We destroy who were greater than them in [striking] power and had explored throughout the lands. Is there any place of escape?' },
  { surahId: 50, ayahNumber: 37, text: 'Indeed in that is a reminder for whoever has a heart or who listens while he is present [in mind].' },
  { surahId: 50, ayahNumber: 38, text: 'And We did certainly create the heavens and earth and what is between them in six days, and there touched Us no weariness.' },
  { surahId: 50, ayahNumber: 39, text: 'So be patient, [O Muhammad], over what they say and exalt [Allah] with praise of your Lord before the rising of the sun and before its setting,' },
  { surahId: 50, ayahNumber: 40, text: 'And [in part] of the night exalt Him and after prostration.' },
  { surahId: 50, ayahNumber: 41, text: 'And listen on the Day when the Caller will call out from a place that is near -' },
  { surahId: 50, ayahNumber: 42, text: 'The Day they will hear the blast [of the Horn] in truth. That is the Day of Emergence [from the graves].' },
  { surahId: 50, ayahNumber: 43, text: 'Indeed, it is We who give life and cause death, and to Us is the destination' },
  { surahId: 50, ayahNumber: 44, text: 'On the Day the earth breaks away from them [and they emerge] rapidly; that is a gathering easy for Us.' },
  { surahId: 50, ayahNumber: 45, text: 'We are most knowing of what they say, and you are not over them a tyrant. But remind by the Qur\'an whoever fears My threat.' },
  { surahId: 51, ayahNumber: 1, text: 'By those [winds] scattering [dust] dispersing' },
  { surahId: 51, ayahNumber: 2, text: 'And those [clouds] carrying a load [of water]' },
  { surahId: 51, ayahNumber: 3, text: 'And those [ships] sailing with ease' },
  { surahId: 51, ayahNumber: 4, text: 'And those [angels] apportioning [each] matter,' },
  { surahId: 51, ayahNumber: 5, text: 'Indeed, what you are promised is true.' },
  { surahId: 51, ayahNumber: 6, text: 'And indeed, the recompense is to occur.' },
  { surahId: 51, ayahNumber: 7, text: 'By the heaven containing pathways,' },
  { surahId: 51, ayahNumber: 8, text: 'Indeed, you are in differing speech.' },
  { surahId: 51, ayahNumber: 9, text: 'Deluded away from the Qur\'an is he who is deluded.' },
  { surahId: 51, ayahNumber: 10, text: 'Destroyed are the falsifiers' },
  { surahId: 51, ayahNumber: 11, text: 'Who are within a flood [of confusion] and heedless.' },
  { surahId: 51, ayahNumber: 12, text: 'They ask, "When is the Day of Recompense?"' },
  { surahId: 51, ayahNumber: 13, text: '[It is] the Day they will be tormented over the Fire' },
  { surahId: 51, ayahNumber: 14, text: '[And will be told], "Taste your torment. This is that for which you were impatient."' },
  { surahId: 51, ayahNumber: 15, text: 'Indeed, the righteous will be among gardens and springs,' },
  { surahId: 51, ayahNumber: 16, text: 'Accepting what their Lord has given them. Indeed, they were before that doers of good.' },
  { surahId: 51, ayahNumber: 17, text: 'They used to sleep but little of the night,' },
  { surahId: 51, ayahNumber: 18, text: 'And in the hours before dawn they would ask forgiveness,' },
  { surahId: 51, ayahNumber: 19, text: 'And from their properties was [given] the right of the [needy] petitioner and the deprived.' },
  { surahId: 51, ayahNumber: 20, text: 'And on the earth are signs for the certain [in faith]' },
  { surahId: 51, ayahNumber: 21, text: 'And in yourselves. Then will you not see?' },
  { surahId: 51, ayahNumber: 22, text: 'And in the heaven is your provision and whatever you are promised.' },
  { surahId: 51, ayahNumber: 23, text: 'Then by the Lord of the heaven and earth, indeed, it is truth - just as [sure as] it is that you are speaking.' },
  { surahId: 51, ayahNumber: 24, text: 'Has there reached you the story of the honored guests of Abraham? -' },
  { surahId: 51, ayahNumber: 25, text: 'When they entered upon him and said, "[We greet you with] peace." He answered, "[And upon you] peace, [you are] a people unknown.' },
  { surahId: 51, ayahNumber: 26, text: 'Then he went to his family and came with a fat [roasted] calf' },
  { surahId: 51, ayahNumber: 27, text: 'And placed it near them; he said, "Will you not eat?"' },
  { surahId: 51, ayahNumber: 28, text: 'And he felt from them apprehension. They said, "Fear not," and gave him good tidings of a learned boy.' },
  { surahId: 51, ayahNumber: 29, text: 'And his wife approached with a cry [of alarm] and struck her face and said, "[I am] a barren old woman!"' },
  { surahId: 51, ayahNumber: 30, text: 'They said, "Thus has said your Lord; indeed, He is the Wise, the Knowing."' },
  { surahId: 51, ayahNumber: 31, text: '[Abraham] said, "Then what is your business [here], O messengers?"' },
  { surahId: 51, ayahNumber: 32, text: 'They said, "Indeed, we have been sent to a people of criminals' },
  { surahId: 51, ayahNumber: 33, text: 'To send down upon them stones of clay,' },
  { surahId: 51, ayahNumber: 34, text: 'Marked in the presence of your Lord for the transgressors."' },
  { surahId: 51, ayahNumber: 35, text: 'So We brought out whoever was in the cities of the believers.' },
  { surahId: 51, ayahNumber: 36, text: 'And We found not within them other than a [single] house of Muslims.' },
  { surahId: 51, ayahNumber: 37, text: 'And We left therein a sign for those who fear the painful punishment.' },
  { surahId: 51, ayahNumber: 38, text: 'And in Moses [was a sign], when We sent him to Pharaoh with clear authority.' },
  { surahId: 51, ayahNumber: 39, text: 'But he turned away with his supporters and said," A magician or a madman."' },
  { surahId: 51, ayahNumber: 40, text: 'So We took him and his soldiers and cast them into the sea, and he was blameworthy.' },
  { surahId: 51, ayahNumber: 41, text: 'And in \'Aad [was a sign], when We sent against them the barren wind.' },
  { surahId: 51, ayahNumber: 42, text: 'It left nothing of what it came upon but that it made it like disintegrated ruins.' },
  { surahId: 51, ayahNumber: 43, text: 'And in Thamud, when it was said to them, "Enjoy yourselves for a time."' },
  { surahId: 51, ayahNumber: 44, text: 'But they were insolent toward the command of their Lord, so the thunderbolt seized them while they were looking on.' },
  { surahId: 51, ayahNumber: 45, text: 'And they were unable to arise, nor could they defend themselves.' },
  { surahId: 51, ayahNumber: 46, text: 'And [We destroyed] the people of Noah before; indeed, they were a people defiantly disobedient.' },
  { surahId: 51, ayahNumber: 47, text: 'And the heaven We constructed with strength, and indeed, We are [its] expander.' },
  { surahId: 51, ayahNumber: 48, text: 'And the earth We have spread out, and excellent is the preparer.' },
  { surahId: 51, ayahNumber: 49, text: 'And of all things We created two mates; perhaps you will remember.' },
  { surahId: 51, ayahNumber: 50, text: 'So flee to Allah. Indeed, I am to you from Him a clear warner.' },
  { surahId: 51, ayahNumber: 51, text: 'And do not make [as equal] with Allah another deity. Indeed, I am to you from Him a clear warner.' },
  { surahId: 51, ayahNumber: 52, text: 'Similarly, there came not to those before them any messenger except that they said, "A magician or a madman."' },
  { surahId: 51, ayahNumber: 53, text: 'Did they suggest it to them? Rather, they [themselves] are a transgressing people.' },
  { surahId: 51, ayahNumber: 54, text: 'So leave them, [O Muhammad], for you are not to be blamed.' },
  { surahId: 51, ayahNumber: 55, text: 'And remind, for indeed, the reminder benefits the believers.' },
  { surahId: 51, ayahNumber: 56, text: 'And I did not create the jinn and mankind except to worship Me.' },
  { surahId: 51, ayahNumber: 57, text: 'I do not want from them any provision, nor do I want them to feed Me.' },
  { surahId: 51, ayahNumber: 58, text: 'Indeed, it is Allah who is the [continual] Provider, the firm possessor of strength.' },
  { surahId: 51, ayahNumber: 59, text: 'And indeed, for those who have wronged is a portion [of punishment] like the portion of their predecessors, so let them not impatiently urge Me.' },
  { surahId: 51, ayahNumber: 60, text: 'And woe to those who have disbelieved from their Day which they are promised.' },
  { surahId: 52, ayahNumber: 1, text: 'By the mount' },
  { surahId: 52, ayahNumber: 2, text: 'And [by] a Book inscribed' },
  { surahId: 52, ayahNumber: 3, text: 'In parchment spread open' },
  { surahId: 52, ayahNumber: 4, text: 'And [by] the frequented House' },
  { surahId: 52, ayahNumber: 5, text: 'And [by] the heaven raised high' },
  { surahId: 52, ayahNumber: 6, text: 'And [by] the sea filled [with fire],' },
  { surahId: 52, ayahNumber: 7, text: 'Indeed, the punishment of your Lord will occur.' },
  { surahId: 52, ayahNumber: 8, text: 'Of it there is no preventer.' },
  { surahId: 52, ayahNumber: 9, text: 'On the Day the heaven will sway with circular motion' },
  { surahId: 52, ayahNumber: 10, text: 'And the mountains will pass on, departing -' },
  { surahId: 52, ayahNumber: 11, text: 'Then woe, that Day, to the deniers,' },
  { surahId: 52, ayahNumber: 12, text: 'Who are in [empty] discourse amusing themselves.' },
  { surahId: 52, ayahNumber: 13, text: 'The Day they are thrust toward the fire of Hell with a [violent] thrust, [its angels will say],' },
  { surahId: 52, ayahNumber: 14, text: '"This is the Fire which you used to deny.' },
  { surahId: 52, ayahNumber: 15, text: 'Then is this magic, or do you not see?' },
  { surahId: 52, ayahNumber: 16, text: '[Enter to] burn therein; then be patient or impatient - it is all the same for you. You are only being recompensed [for] what you used to do."' },
  { surahId: 52, ayahNumber: 17, text: 'Indeed, the righteous will be in gardens and pleasure,' },
  { surahId: 52, ayahNumber: 18, text: 'Enjoying what their Lord has given them, and their Lord protected them from the punishment of Hellfire.' },
  { surahId: 52, ayahNumber: 19, text: '[They will be told], "Eat and drink in satisfaction for what you used to do."' },
  { surahId: 52, ayahNumber: 20, text: 'They will be reclining on thrones lined up, and We will marry them to fair women with large, [beautiful] eyes.' },
  { surahId: 52, ayahNumber: 21, text: 'And those who believed and whose descendants followed them in faith - We will join with them their descendants, and We will not deprive them of anything of their deeds. Every person, for what he earned, is retained.' },
  { surahId: 52, ayahNumber: 22, text: 'And We will provide them with fruit and meat from whatever they desire.' },
  { surahId: 52, ayahNumber: 23, text: 'They will exchange with one another a cup [of wine] wherein [results] no ill speech or commission of sin.' },
  { surahId: 52, ayahNumber: 24, text: 'There will circulate among them [servant] boys [especially] for them, as if they were pearls well-protected.' },
  { surahId: 52, ayahNumber: 25, text: 'And they will approach one another, inquiring of each other.' },
  { surahId: 52, ayahNumber: 26, text: 'They will say, "Indeed, we were previously among our people fearful [of displeasing Allah].' },
  { surahId: 52, ayahNumber: 27, text: 'So Allah conferred favor upon us and protected us from the punishment of the Scorching Fire.' },
  { surahId: 52, ayahNumber: 28, text: 'Indeed, we used to supplicate Him before. Indeed, it is He who is the Beneficent, the Merciful."' },
  { surahId: 52, ayahNumber: 29, text: 'So remind [O Muhammad], for you are not, by the favor of your Lord, a soothsayer or a madman.' },
  { surahId: 52, ayahNumber: 30, text: 'Or do they say [of you], "A poet for whom we await a misfortune of time?"' },
  { surahId: 52, ayahNumber: 31, text: 'Say, "Wait, for indeed I am, with you, among the waiters."' },
  { surahId: 52, ayahNumber: 32, text: 'Or do their minds command them to [say] this, or are they a transgressing people?' },
  { surahId: 52, ayahNumber: 33, text: 'Or do they say, "He has made it up"? Rather, they do not believe.' },
  { surahId: 52, ayahNumber: 34, text: 'Then let them produce a statement like it, if they should be truthful.' },
  { surahId: 52, ayahNumber: 35, text: 'Or were they created by nothing, or were they the creators [of themselves]?' },
  { surahId: 52, ayahNumber: 36, text: 'Or did they create the heavens and the earth? Rather, they are not certain.' },
  { surahId: 52, ayahNumber: 37, text: 'Or have they the depositories [containing the provision] of your Lord? Or are they the controllers [of them]?' },
  { surahId: 52, ayahNumber: 38, text: 'Or have they a stairway [into the heaven] upon which they listen? Then let their listener produce a clear authority.' },
  { surahId: 52, ayahNumber: 39, text: 'Or has He daughters while you have sons?' },
  { surahId: 52, ayahNumber: 40, text: 'Or do you, [O Muhammad], ask of them a payment, so they are by debt burdened down?' },
  { surahId: 52, ayahNumber: 41, text: 'Or have they [knowledge of] the unseen, so they write [it] down?' },
  { surahId: 52, ayahNumber: 42, text: 'Or do they intend a plan? But those who disbelieve - they are the object of a plan.' },
  { surahId: 52, ayahNumber: 43, text: 'Or have they a deity other than Allah? Exalted is Allah above whatever they associate with Him.' },
  { surahId: 52, ayahNumber: 44, text: 'And if they were to see a fragment from the sky falling, they would say, "[It is merely] clouds heaped up."' },
  { surahId: 52, ayahNumber: 45, text: 'So leave them until they meet their Day in which they will be struck insensible -' },
  { surahId: 52, ayahNumber: 46, text: 'The Day their plan will not avail them at all, nor will they be helped.' },
  { surahId: 52, ayahNumber: 47, text: 'And indeed, for those who have wronged is a punishment before that, but most of them do not know.' },
  { surahId: 52, ayahNumber: 48, text: 'And be patient, [O Muhammad], for the decision of your Lord, for indeed, you are in Our eyes. And exalt [Allah] with praise of your Lord when you arise.' },
  { surahId: 52, ayahNumber: 49, text: 'And in a part of the night exalt Him and after [the setting of] the stars.' },
  { surahId: 53, ayahNumber: 1, text: 'By the star when it descends,' },
  { surahId: 53, ayahNumber: 2, text: 'Your companion [Muhammad] has not strayed, nor has he erred,' },
  { surahId: 53, ayahNumber: 3, text: 'Nor does he speak from [his own] inclination.' },
  { surahId: 53, ayahNumber: 4, text: 'It is not but a revelation revealed,' },
  { surahId: 53, ayahNumber: 5, text: 'Taught to him by one intense in strength -' },
  { surahId: 53, ayahNumber: 6, text: 'One of soundness. And he rose to [his] true form' },
  { surahId: 53, ayahNumber: 7, text: 'While he was in the higher [part of the] horizon.' },
  { surahId: 53, ayahNumber: 8, text: 'Then he approached and descended' },
  { surahId: 53, ayahNumber: 9, text: 'And was at a distance of two bow lengths or nearer.' },
  { surahId: 53, ayahNumber: 10, text: 'And he revealed to His Servant what he revealed.' },
  { surahId: 53, ayahNumber: 11, text: 'The heart did not lie [about] what it saw.' },
  { surahId: 53, ayahNumber: 12, text: 'So will you dispute with him over what he saw?' },
  { surahId: 53, ayahNumber: 13, text: 'And he certainly saw him in another descent' },
  { surahId: 53, ayahNumber: 14, text: 'At the Lote Tree of the Utmost Boundary -' },
  { surahId: 53, ayahNumber: 15, text: 'Near it is the Garden of Refuge -' },
  { surahId: 53, ayahNumber: 16, text: 'When there covered the Lote Tree that which covered [it].' },
  { surahId: 53, ayahNumber: 17, text: 'The sight [of the Prophet] did not swerve, nor did it transgress [its limit].' },
  { surahId: 53, ayahNumber: 18, text: 'He certainly saw of the greatest signs of his Lord.' },
  { surahId: 53, ayahNumber: 19, text: 'So have you considered al-Lat and al-\'Uzza?' },
  { surahId: 53, ayahNumber: 20, text: 'And Manat, the third - the other one?' },
  { surahId: 53, ayahNumber: 21, text: 'Is the male for you and for Him the female?' },
  { surahId: 53, ayahNumber: 22, text: 'That, then, is an unjust division.' },
  { surahId: 53, ayahNumber: 23, text: 'They are not but [mere] names you have named them - you and your forefathers - for which Allah has sent down no authority. They follow not except assumption and what [their] souls desire, and there has already come to them from their Lord guidance.' },
  { surahId: 53, ayahNumber: 24, text: 'Or is there for man whatever he wishes?' },
  { surahId: 53, ayahNumber: 25, text: 'Rather, to Allah belongs the Hereafter and the first [life].' },
  { surahId: 53, ayahNumber: 26, text: 'And how many angels there are in the heavens whose intercession will not avail at all except [only] after Allah has permitted [it] to whom He wills and approves.' },
  { surahId: 53, ayahNumber: 27, text: 'Indeed, those who do not believe in the Hereafter name the angels female names,' },
  { surahId: 53, ayahNumber: 28, text: 'And they have thereof no knowledge. They follow not except assumption, and indeed, assumption avails not against the truth at all.' },
  { surahId: 53, ayahNumber: 29, text: 'So turn away from whoever turns his back on Our message and desires not except the worldly life.' },
  { surahId: 53, ayahNumber: 30, text: 'That is their sum of knowledge. Indeed, your Lord is most knowing of who strays from His way, and He is most knowing of who is guided.' },
  { surahId: 53, ayahNumber: 31, text: 'And to Allah belongs whatever is in the heavens and whatever is in the earth - that He may recompense those who do evil with [the penalty of] what they have done and recompense those who do good with the best [reward] -' },
  { surahId: 53, ayahNumber: 32, text: 'Those who avoid the major sins and immoralities, only [committing] slight ones. Indeed, your Lord is vast in forgiveness. He was most knowing of you when He produced you from the earth and when you were fetuses in the wombs of your mothers. So do not claim yourselves to be pure; He is most knowing of who fears Him.' },
  { surahId: 53, ayahNumber: 33, text: 'Have you seen the one who turned away' },
  { surahId: 53, ayahNumber: 34, text: 'And gave a little and [then] refrained?' },
  { surahId: 53, ayahNumber: 35, text: 'Does he have knowledge of the unseen, so he sees?' },
  { surahId: 53, ayahNumber: 36, text: 'Or has he not been informed of what was in the scriptures of Moses' },
  { surahId: 53, ayahNumber: 37, text: 'And [of] Abraham, who fulfilled [his obligations] -' },
  { surahId: 53, ayahNumber: 38, text: 'That no bearer of burdens will bear the burden of another' },
  { surahId: 53, ayahNumber: 39, text: 'And that there is not for man except that [good] for which he strives' },
  { surahId: 53, ayahNumber: 40, text: 'And that his effort is going to be seen -' },
  { surahId: 53, ayahNumber: 41, text: 'Then he will be recompensed for it with the fullest recompense' },
  { surahId: 53, ayahNumber: 42, text: 'And that to your Lord is the finality' },
  { surahId: 53, ayahNumber: 43, text: 'And that it is He who makes [one] laugh and weep' },
  { surahId: 53, ayahNumber: 44, text: 'And that it is He who causes death and gives life' },
  { surahId: 53, ayahNumber: 45, text: 'And that He creates the two mates - the male and female -' },
  { surahId: 53, ayahNumber: 46, text: 'From a sperm-drop when it is emitted' },
  { surahId: 53, ayahNumber: 47, text: 'And that [incumbent] upon Him is the next creation' },
  { surahId: 53, ayahNumber: 48, text: 'And that it is He who enriches and suffices' },
  { surahId: 53, ayahNumber: 49, text: 'And that it is He who is the Lord of Sirius' },
  { surahId: 53, ayahNumber: 50, text: 'And that He destroyed the first [people of] \'Aad' },
  { surahId: 53, ayahNumber: 51, text: 'And Thamud - and He did not spare [them] -' },
  { surahId: 53, ayahNumber: 52, text: 'And the people of Noah before. Indeed, it was they who were [even] more unjust and oppressing.' },
  { surahId: 53, ayahNumber: 53, text: 'And the overturned towns He hurled down' },
  { surahId: 53, ayahNumber: 54, text: 'And covered them by that which He covered.' },
  { surahId: 53, ayahNumber: 55, text: 'Then which of the favors of your Lord do you doubt?' },
  { surahId: 53, ayahNumber: 56, text: 'This [Prophet] is a warner like the former warners.' },
  { surahId: 53, ayahNumber: 57, text: 'The Approaching Day has approached.' },
  { surahId: 53, ayahNumber: 58, text: 'Of it, [from those] besides Allah, there is no remover.' },
  { surahId: 53, ayahNumber: 59, text: 'Then at this statement do you wonder?' },
  { surahId: 53, ayahNumber: 60, text: 'And you laugh and do not weep' },
  { surahId: 53, ayahNumber: 61, text: 'While you are proudly sporting?' },
  { surahId: 53, ayahNumber: 62, text: 'So prostrate to Allah and worship [Him].' },
  { surahId: 54, ayahNumber: 1, text: 'The Hour has come near, and the moon has split [in two].' },
  { surahId: 54, ayahNumber: 2, text: 'And if they see a miracle, they turn away and say, "Passing magic."' },
  { surahId: 54, ayahNumber: 3, text: 'And they denied and followed their inclinations. But for every matter is a [time of] settlement.' },
  { surahId: 54, ayahNumber: 4, text: 'And there has already come to them of information that in which there is deterrence -' },
  { surahId: 54, ayahNumber: 5, text: 'Extensive wisdom - but warning does not avail [them].' },
  { surahId: 54, ayahNumber: 6, text: 'So leave them, [O Muhammad]. The Day the Caller calls to something forbidding,' },
  { surahId: 54, ayahNumber: 7, text: 'Their eyes humbled, they will emerge from the graves as if they were locusts spreading,' },
  { surahId: 54, ayahNumber: 8, text: 'Racing ahead toward the Caller. The disbelievers will say, "This is a difficult Day."' },
  { surahId: 54, ayahNumber: 9, text: 'The people of Noah denied before them, and they denied Our servant and said, "A madman," and he was repelled.' },
  { surahId: 54, ayahNumber: 10, text: 'So he invoked his Lord, "Indeed, I am overpowered, so help."' },
  { surahId: 54, ayahNumber: 11, text: 'Then We opened the gates of the heaven with rain pouring down' },
  { surahId: 54, ayahNumber: 12, text: 'And caused the earth to burst with springs, and the waters met for a matter already predestined.' },
  { surahId: 54, ayahNumber: 13, text: 'And We carried him on a [construction of] planks and nails,' },
  { surahId: 54, ayahNumber: 14, text: 'Sailing under Our observation as reward for he who had been denied.' },
  { surahId: 54, ayahNumber: 15, text: 'And We left it as a sign, so is there any who will remember?' },
  { surahId: 54, ayahNumber: 16, text: 'And how [severe] were My punishment and warning.' },
  { surahId: 54, ayahNumber: 17, text: 'And We have certainly made the Qur\'an easy for remembrance, so is there any who will remember?' },
  { surahId: 54, ayahNumber: 18, text: '\'Aad denied; and how [severe] were My punishment and warning.' },
  { surahId: 54, ayahNumber: 19, text: 'Indeed, We sent upon them a screaming wind on a day of continuous misfortune,' },
  { surahId: 54, ayahNumber: 20, text: 'Extracting the people as if they were trunks of palm trees uprooted.' },
  { surahId: 54, ayahNumber: 21, text: 'And how [severe] were My punishment and warning.' },
  { surahId: 54, ayahNumber: 22, text: 'And We have certainly made the Qur\'an easy for remembrance, so is there any who will remember?' },
  { surahId: 54, ayahNumber: 23, text: 'Thamud denied the warning' },
  { surahId: 54, ayahNumber: 24, text: 'And said, "Is it one human being among us that we should follow? Indeed, we would then be in error and madness.' },
  { surahId: 54, ayahNumber: 25, text: 'Has the message been sent down upon him from among us? Rather, he is an insolent liar."' },
  { surahId: 54, ayahNumber: 26, text: 'They will know tomorrow who is the insolent liar.' },
  { surahId: 54, ayahNumber: 27, text: 'Indeed, We are sending the she-camel as trial for them, so watch them and be patient.' },
  { surahId: 54, ayahNumber: 28, text: 'And inform them that the water is shared between them, each [day of] drink attended [by turn].' },
  { surahId: 54, ayahNumber: 29, text: 'But they called their companion, and he dared and hamstrung [her].' },
  { surahId: 54, ayahNumber: 30, text: 'And how [severe] were My punishment and warning.' },
  { surahId: 54, ayahNumber: 31, text: 'Indeed, We sent upon them one blast from the sky, and they became like the dry twig fragments of an [animal] pen.' },
  { surahId: 54, ayahNumber: 32, text: 'And We have certainly made the Qur\'an easy for remembrance, so is there any who will remember?' },
  { surahId: 54, ayahNumber: 33, text: 'The people of Lot denied the warning.' },
  { surahId: 54, ayahNumber: 34, text: 'Indeed, We sent upon them a storm of stones, except the family of Lot - We saved them before dawn' },
  { surahId: 54, ayahNumber: 35, text: 'As favor from us. Thus do We reward he who is grateful.' },
  { surahId: 54, ayahNumber: 36, text: 'And he had already warned them of Our assault, but they disputed the warning.' },
  { surahId: 54, ayahNumber: 37, text: 'And they had demanded from him his guests, but We obliterated their eyes, [saying], "Taste My punishment and warning."' },
  { surahId: 54, ayahNumber: 38, text: 'And there came upon them by morning an abiding punishment.' },
  { surahId: 54, ayahNumber: 39, text: 'So taste My punishment and warning.' },
  { surahId: 54, ayahNumber: 40, text: 'And We have certainly made the Qur\'an easy for remembrance, so is there any who will remember?' },
  { surahId: 54, ayahNumber: 41, text: 'And there certainly came to the people of Pharaoh warning.' },
  { surahId: 54, ayahNumber: 42, text: 'They denied Our signs, all of them, so We seized them with a seizure of one Exalted in Might and Perfect in Ability.' },
  { surahId: 54, ayahNumber: 43, text: 'Are your disbelievers better than those [former ones], or have you immunity in the scripture?' },
  { surahId: 54, ayahNumber: 44, text: 'Or do they say, "We are an assembly supporting [each other]"?' },
  { surahId: 54, ayahNumber: 45, text: '[Their] assembly will be defeated, and they will turn their backs [in retreat].' },
  { surahId: 54, ayahNumber: 46, text: 'But the Hour is their appointment [for due punishment], and the Hour is more disastrous and more bitter.' },
  { surahId: 54, ayahNumber: 47, text: 'Indeed, the criminals are in error and madness.' },
  { surahId: 54, ayahNumber: 48, text: 'The Day they are dragged into the Fire on their faces [it will be said], "Taste the touch of Saqar."' },
  { surahId: 54, ayahNumber: 49, text: 'Indeed, all things We created with predestination.' },
  { surahId: 54, ayahNumber: 50, text: 'And Our command is but one, like a glance of the eye.' },
  { surahId: 54, ayahNumber: 51, text: 'And We have already destroyed your kinds, so is there any who will remember?' },
  { surahId: 54, ayahNumber: 52, text: 'And everything they did is in written records.' },
  { surahId: 54, ayahNumber: 53, text: 'And every small and great [thing] is inscribed.' },
  { surahId: 54, ayahNumber: 54, text: 'Indeed, the righteous will be among gardens and rivers,' },
  { surahId: 54, ayahNumber: 55, text: 'In a seat of honor near a Sovereign, Perfect in Ability.' },
  { surahId: 55, ayahNumber: 1, text: 'The Most Merciful' },
  { surahId: 55, ayahNumber: 2, text: 'Taught the Qur\'an,' },
  { surahId: 55, ayahNumber: 3, text: 'Created man,' },
  { surahId: 55, ayahNumber: 4, text: '[And] taught him eloquence.' },
  { surahId: 55, ayahNumber: 5, text: 'The sun and the moon [move] by precise calculation,' },
  { surahId: 55, ayahNumber: 6, text: 'And the stars and trees prostrate.' },
  { surahId: 55, ayahNumber: 7, text: 'And the heaven He raised and imposed the balance' },
  { surahId: 55, ayahNumber: 8, text: 'That you not transgress within the balance.' },
  { surahId: 55, ayahNumber: 9, text: 'And establish weight in justice and do not make deficient the balance.' },
  { surahId: 55, ayahNumber: 10, text: 'And the earth He laid [out] for the creatures.' },
  { surahId: 55, ayahNumber: 11, text: 'Therein is fruit and palm trees having sheaths [of dates]' },
  { surahId: 55, ayahNumber: 12, text: 'And grain having husks and scented plants.' },
  { surahId: 55, ayahNumber: 13, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 14, text: 'He created man from clay like [that of] pottery.' },
  { surahId: 55, ayahNumber: 15, text: 'And He created the jinn from a smokeless flame of fire.' },
  { surahId: 55, ayahNumber: 16, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 17, text: '[He is] Lord of the two sunrises and Lord of the two sunsets.' },
  { surahId: 55, ayahNumber: 18, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 19, text: 'He released the two seas, meeting [side by side];' },
  { surahId: 55, ayahNumber: 20, text: 'Between them is a barrier [so] neither of them transgresses.' },
  { surahId: 55, ayahNumber: 21, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 22, text: 'From both of them emerge pearl and coral.' },
  { surahId: 55, ayahNumber: 23, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 24, text: 'And to Him belong the ships [with sails] elevated in the sea like mountains.' },
  { surahId: 55, ayahNumber: 25, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 26, text: 'Everyone upon the earth will perish,' },
  { surahId: 55, ayahNumber: 27, text: 'And there will remain the Face of your Lord, Owner of Majesty and Honor.' },
  { surahId: 55, ayahNumber: 28, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 29, text: 'Whoever is within the heavens and earth asks Him; every day He is bringing about a matter.' },
  { surahId: 55, ayahNumber: 30, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 31, text: 'We will attend to you, O prominent beings.' },
  { surahId: 55, ayahNumber: 32, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 33, text: 'O company of jinn and mankind, if you are able to pass beyond the regions of the heavens and the earth, then pass. You will not pass except by authority [from Allah].' },
  { surahId: 55, ayahNumber: 34, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 35, text: 'There will be sent upon you a flame of fire and smoke, and you will not defend yourselves.' },
  { surahId: 55, ayahNumber: 36, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 37, text: 'And when the heaven is split open and becomes rose-colored like oil -' },
  { surahId: 55, ayahNumber: 38, text: 'So which of the favors of your Lord would you deny? -' },
  { surahId: 55, ayahNumber: 39, text: 'Then on that Day none will be asked about his sin among men or jinn.' },
  { surahId: 55, ayahNumber: 40, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 41, text: 'The criminals will be known by their marks, and they will be seized by the forelocks and the feet.' },
  { surahId: 55, ayahNumber: 42, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 43, text: 'This is Hell, which the criminals deny.' },
  { surahId: 55, ayahNumber: 44, text: 'They will go around between it and scalding water, heated [to the utmost degree].' },
  { surahId: 55, ayahNumber: 45, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 46, text: 'But for he who has feared the position of his Lord are two gardens -' },
  { surahId: 55, ayahNumber: 47, text: 'So which of the favors of your Lord would you deny? -' },
  { surahId: 55, ayahNumber: 48, text: 'Having [spreading] branches.' },
  { surahId: 55, ayahNumber: 49, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 50, text: 'In both of them are two springs, flowing.' },
  { surahId: 55, ayahNumber: 51, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 52, text: 'In both of them are of every fruit, two kinds.' },
  { surahId: 55, ayahNumber: 53, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 54, text: '[They are] reclining on beds whose linings are of silk brocade, and the fruit of the two gardens is hanging low.' },
  { surahId: 55, ayahNumber: 55, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 56, text: 'In them are women limiting [their] glances, untouched before them by man or jinni -' },
  { surahId: 55, ayahNumber: 57, text: 'So which of the favors of your Lord would you deny? -' },
  { surahId: 55, ayahNumber: 58, text: 'As if they were rubies and coral.' },
  { surahId: 55, ayahNumber: 59, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 60, text: 'Is the reward for good [anything] but good?' },
  { surahId: 55, ayahNumber: 61, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 62, text: 'And below them both [in excellence] are two [other] gardens -' },
  { surahId: 55, ayahNumber: 63, text: 'So which of the favors of your Lord would you deny? -' },
  { surahId: 55, ayahNumber: 64, text: 'Dark green [in color].' },
  { surahId: 55, ayahNumber: 65, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 66, text: 'In both of them are two springs, spouting.' },
  { surahId: 55, ayahNumber: 67, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 68, text: 'In both of them are fruit and palm trees and pomegranates.' },
  { surahId: 55, ayahNumber: 69, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 70, text: 'In them are good and beautiful women -' },
  { surahId: 55, ayahNumber: 71, text: 'So which of the favors of your Lord would you deny? -' },
  { surahId: 55, ayahNumber: 72, text: 'Fair ones reserved in pavilions -' },
  { surahId: 55, ayahNumber: 73, text: 'So which of the favors of your Lord would you deny? -' },
  { surahId: 55, ayahNumber: 74, text: 'Untouched before them by man or jinni -' },
  { surahId: 55, ayahNumber: 75, text: 'So which of the favors of your Lord would you deny? -' },
  { surahId: 55, ayahNumber: 76, text: 'Reclining on green cushions and beautiful fine carpets.' },
  { surahId: 55, ayahNumber: 77, text: 'So which of the favors of your Lord would you deny?' },
  { surahId: 55, ayahNumber: 78, text: 'Blessed is the name of your Lord, Owner of Majesty and Honor.' },
  { surahId: 56, ayahNumber: 1, text: 'When the Occurrence occurs,' },
  { surahId: 56, ayahNumber: 2, text: 'There is, at its occurrence, no denial.' },
  { surahId: 56, ayahNumber: 3, text: 'It will bring down [some] and raise up [others].' },
  { surahId: 56, ayahNumber: 4, text: 'When the earth is shaken with convulsion' },
  { surahId: 56, ayahNumber: 5, text: 'And the mountains are broken down, crumbling' },
  { surahId: 56, ayahNumber: 6, text: 'And become dust dispersing.' },
  { surahId: 56, ayahNumber: 7, text: 'And you become [of] three kinds:' },
  { surahId: 56, ayahNumber: 8, text: 'Then the companions of the right - what are the companions of the right?' },
  { surahId: 56, ayahNumber: 9, text: 'And the companions of the left - what are the companions of the left?' },
  { surahId: 56, ayahNumber: 10, text: 'And the forerunners, the forerunners -' },
  { surahId: 56, ayahNumber: 11, text: 'Those are the ones brought near [to Allah]' },
  { surahId: 56, ayahNumber: 12, text: 'In the Gardens of Pleasure,' },
  { surahId: 56, ayahNumber: 13, text: 'A [large] company of the former peoples' },
  { surahId: 56, ayahNumber: 14, text: 'And a few of the later peoples,' },
  { surahId: 56, ayahNumber: 15, text: 'On thrones woven [with ornament],' },
  { surahId: 56, ayahNumber: 16, text: 'Reclining on them, facing each other.' },
  { surahId: 56, ayahNumber: 17, text: 'There will circulate among them young boys made eternal' },
  { surahId: 56, ayahNumber: 18, text: 'With vessels, pitchers and a cup [of wine] from a flowing spring -' },
  { surahId: 56, ayahNumber: 19, text: 'No headache will they have therefrom, nor will they be intoxicated -' },
  { surahId: 56, ayahNumber: 20, text: 'And fruit of what they select' },
  { surahId: 56, ayahNumber: 21, text: 'And the meat of fowl, from whatever they desire.' },
  { surahId: 56, ayahNumber: 22, text: 'And [for them are] fair women with large, [beautiful] eyes,' },
  { surahId: 56, ayahNumber: 23, text: 'The likenesses of pearls well-protected,' },
  { surahId: 56, ayahNumber: 24, text: 'As reward for what they used to do.' },
  { surahId: 56, ayahNumber: 25, text: 'They will not hear therein ill speech or commission of sin -' },
  { surahId: 56, ayahNumber: 26, text: 'Only a saying: "Peace, peace."' },
  { surahId: 56, ayahNumber: 27, text: 'The companions of the right - what are the companions of the right?' },
  { surahId: 56, ayahNumber: 28, text: '[They will be] among lote trees with thorns removed' },
  { surahId: 56, ayahNumber: 29, text: 'And [banana] trees layered [with fruit]' },
  { surahId: 56, ayahNumber: 30, text: 'And shade extended' },
  { surahId: 56, ayahNumber: 31, text: 'And water poured out' },
  { surahId: 56, ayahNumber: 32, text: 'And fruit, abundant [and varied],' },
  { surahId: 56, ayahNumber: 33, text: 'Neither limited [to season] nor forbidden,' },
  { surahId: 56, ayahNumber: 34, text: 'And [upon] beds raised high.' },
  { surahId: 56, ayahNumber: 35, text: 'Indeed, We have produced the women of Paradise in a [new] creation' },
  { surahId: 56, ayahNumber: 36, text: 'And made them virgins,' },
  { surahId: 56, ayahNumber: 37, text: 'Devoted [to their husbands] and of equal age,' },
  { surahId: 56, ayahNumber: 38, text: 'For the companions of the right [who are]' },
  { surahId: 56, ayahNumber: 39, text: 'A company of the former peoples' },
  { surahId: 56, ayahNumber: 40, text: 'And a company of the later peoples.' },
  { surahId: 56, ayahNumber: 41, text: 'And the companions of the left - what are the companions of the left?' },
  { surahId: 56, ayahNumber: 42, text: '[They will be] in scorching fire and scalding water' },
  { surahId: 56, ayahNumber: 43, text: 'And a shade of black smoke,' },
  { surahId: 56, ayahNumber: 44, text: 'Neither cool nor beneficial.' },
  { surahId: 56, ayahNumber: 45, text: 'Indeed they were, before that, indulging in affluence,' },
  { surahId: 56, ayahNumber: 46, text: 'And they used to persist in the great violation,' },
  { surahId: 56, ayahNumber: 47, text: 'And they used to say, "When we die and become dust and bones, are we indeed to be resurrected?' },
  { surahId: 56, ayahNumber: 48, text: 'And our forefathers [as well]?"' },
  { surahId: 56, ayahNumber: 49, text: 'Say, [O Muhammad], "Indeed, the former and the later peoples' },
  { surahId: 56, ayahNumber: 50, text: 'Are to be gathered together for the appointment of a known Day."' },
  { surahId: 56, ayahNumber: 51, text: 'Then indeed you, O those astray [who are] deniers,' },
  { surahId: 56, ayahNumber: 52, text: 'Will be eating from trees of zaqqum' },
  { surahId: 56, ayahNumber: 53, text: 'And filling with it your bellies' },
  { surahId: 56, ayahNumber: 54, text: 'And drinking on top of it from scalding water' },
  { surahId: 56, ayahNumber: 55, text: 'And will drink as the drinking of thirsty camels.' },
  { surahId: 56, ayahNumber: 56, text: 'That is their accommodation on the Day of Recompense.' },
  { surahId: 56, ayahNumber: 57, text: 'We have created you, so why do you not believe?' },
  { surahId: 56, ayahNumber: 58, text: 'Have you seen that which you emit?' },
  { surahId: 56, ayahNumber: 59, text: 'Is it you who creates it, or are We the Creator?' },
  { surahId: 56, ayahNumber: 60, text: 'We have decreed death among you, and We are not to be outdone' },
  { surahId: 56, ayahNumber: 61, text: 'In that We will change your likenesses and produce you in that [form] which you do not know.' },
  { surahId: 56, ayahNumber: 62, text: 'And you have already known the first creation, so will you not remember?' },
  { surahId: 56, ayahNumber: 63, text: 'And have you seen that [seed] which you sow?' },
  { surahId: 56, ayahNumber: 64, text: 'Is it you who makes it grow, or are We the grower?' },
  { surahId: 56, ayahNumber: 65, text: 'If We willed, We could make it [dry] debris, and you would remain in wonder,' },
  { surahId: 56, ayahNumber: 66, text: '[Saying], "Indeed, we are [now] in debt;' },
  { surahId: 56, ayahNumber: 67, text: 'Rather, we have been deprived."' },
  { surahId: 56, ayahNumber: 68, text: 'And have you seen the water that you drink?' },
  { surahId: 56, ayahNumber: 69, text: 'Is it you who brought it down from the clouds, or is it We who bring it down?' },
  { surahId: 56, ayahNumber: 70, text: 'If We willed, We could make it bitter, so why are you not grateful?' },
  { surahId: 56, ayahNumber: 71, text: 'And have you seen the fire that you ignite?' },
  { surahId: 56, ayahNumber: 72, text: 'Is it you who produced its tree, or are We the producer?' },
  { surahId: 56, ayahNumber: 73, text: 'We have made it a reminder and provision for the travelers,' },
  { surahId: 56, ayahNumber: 74, text: 'So exalt the name of your Lord, the Most Great.' },
  { surahId: 56, ayahNumber: 75, text: 'Then I swear by the setting of the stars,' },
  { surahId: 56, ayahNumber: 76, text: 'And indeed, it is an oath - if you could know - [most] great.' },
  { surahId: 56, ayahNumber: 77, text: 'Indeed, it is a noble Qur\'an' },
  { surahId: 56, ayahNumber: 78, text: 'In a Register well-protected;' },
  { surahId: 56, ayahNumber: 79, text: 'None touch it except the purified.' },
  { surahId: 56, ayahNumber: 80, text: '[It is] a revelation from the Lord of the worlds.' },
  { surahId: 56, ayahNumber: 81, text: 'Then is it to this statement that you are indifferent' },
  { surahId: 56, ayahNumber: 82, text: 'And make [the thanks for] your provision that you deny [the Provider]?' },
  { surahId: 56, ayahNumber: 83, text: 'Then why, when the soul at death reaches the throat' },
  { surahId: 56, ayahNumber: 84, text: 'And you are at that time looking on -' },
  { surahId: 56, ayahNumber: 85, text: 'And Our angels are nearer to him than you, but you do not see -' },
  { surahId: 56, ayahNumber: 86, text: 'Then why do you not, if you are not to be recompensed,' },
  { surahId: 56, ayahNumber: 87, text: 'Bring it back, if you should be truthful?' },
  { surahId: 56, ayahNumber: 88, text: 'And if the deceased was of those brought near to Allah,' },
  { surahId: 56, ayahNumber: 89, text: 'Then [for him is] rest and bounty and a garden of pleasure.' },
  { surahId: 56, ayahNumber: 90, text: 'And if he was of the companions of the right,' },
  { surahId: 56, ayahNumber: 91, text: 'Then [the angels will say], "Peace for you; [you are] from the companions of the right."' },
  { surahId: 56, ayahNumber: 92, text: 'But if he was of the deniers [who were] astray,' },
  { surahId: 56, ayahNumber: 93, text: 'Then [for him is] accommodation of scalding water' },
  { surahId: 56, ayahNumber: 94, text: 'And burning in Hellfire' },
  { surahId: 56, ayahNumber: 95, text: 'Indeed, this is the true certainty,' },
  { surahId: 56, ayahNumber: 96, text: 'So exalt the name of your Lord, the Most Great.' },
  { surahId: 57, ayahNumber: 1, text: 'Whatever is in the heavens and earth exalts Allah, and He is the Exalted in Might, the Wise.' },
  { surahId: 57, ayahNumber: 2, text: 'His is the dominion of the heavens and earth. He gives life and causes death, and He is over all things competent.' },
  { surahId: 57, ayahNumber: 3, text: 'He is the First and the Last, the Ascendant and the Intimate, and He is, of all things, Knowing.' },
  { surahId: 57, ayahNumber: 4, text: 'It is He who created the heavens and earth in six days and then established Himself above the Throne. He knows what penetrates into the earth and what emerges from it and what descends from the heaven and what ascends therein; and He is with you wherever you are. And Allah, of what you do, is Seeing.' },
  { surahId: 57, ayahNumber: 5, text: 'His is the dominion of the heavens and earth. And to Allah are returned [all] matters.' },
  { surahId: 57, ayahNumber: 6, text: 'He causes the night to enter the day and causes the day to enter the night, and he is Knowing of that within the breasts.' },
  { surahId: 57, ayahNumber: 7, text: 'Believe in Allah and His Messenger and spend out of that in which He has made you successors. For those who have believed among you and spent, there will be a great reward.' },
  { surahId: 57, ayahNumber: 8, text: 'And why do you not believe in Allah while the Messenger invites you to believe in your Lord and He has taken your covenant, if you should [truly] be believers?' },
  { surahId: 57, ayahNumber: 9, text: 'It is He who sends down upon His Servant [Muhammad] verses of clear evidence that He may bring you out from darknesses into the light. And indeed, Allah is to you Kind and Merciful.' },
  { surahId: 57, ayahNumber: 10, text: 'And why do you not spend in the cause of Allah while to Allah belongs the heritage of the heavens and the earth? Not equal among you are those who spent before the conquest [of Makkah] and fought [and those who did so after it]. Those are greater in degree than they who spent afterwards and fought. But to all Allah has promised the best [reward]. And Allah, with what you do, is Acquainted.' },
  { surahId: 57, ayahNumber: 11, text: 'Who is it that would loan Allah a goodly loan so He will multiply it for him and he will have a noble reward?' },
  { surahId: 57, ayahNumber: 12, text: 'On the Day you see the believing men and believing women, their light proceeding before them and on their right, [it will be said], "Your good tidings today are [of] gardens beneath which rivers flow, wherein you will abide eternally." That is what is the great attainment.' },
  { surahId: 57, ayahNumber: 13, text: 'On the [same] Day the hypocrite men and hypocrite women will say to those who believed, "Wait for us that we may acquire some of your light." It will be said, "Go back behind you and seek light." And a wall will be placed between them with a door, its interior containing mercy, but on the outside of it is torment.' },
  { surahId: 57, ayahNumber: 14, text: 'The hypocrites will call to the believers, "Were we not with you?" They will say, "Yes, but you afflicted yourselves and awaited [misfortune for us] and doubted, and wishful thinking deluded you until there came the command of Allah. And the Deceiver deceived you concerning Allah.' },
  { surahId: 57, ayahNumber: 15, text: 'So today no ransom will be taken from you or from those who disbelieved. Your refuge is the Fire. It is most worthy of you, and wretched is the destination.' },
  { surahId: 57, ayahNumber: 16, text: 'Has the time not come for those who have believed that their hearts should become humbly submissive at the remembrance of Allah and what has come down of the truth? And let them not be like those who were given the Scripture before, and a long period passed over them, so their hearts hardened; and many of them are defiantly disobedient.' },
  { surahId: 57, ayahNumber: 17, text: 'Know that Allah gives life to the earth after its lifelessness. We have made clear to you the signs; perhaps you will understand.' },
  { surahId: 57, ayahNumber: 18, text: 'Indeed, the men who practice charity and the women who practice charity and [they who] have loaned Allah a goodly loan - it will be multiplied for them, and they will have a noble reward.' },
  { surahId: 57, ayahNumber: 19, text: 'And those who have believed in Allah and His messengers - those are [in the ranks of] the supporters of truth and the martyrs, with their Lord. For them is their reward and their light. But those who have disbelieved and denied Our verses - those are the companions of Hellfire.' },
  { surahId: 57, ayahNumber: 20, text: 'Know that the life of this world is but amusement and diversion and adornment and boasting to one another and competition in increase of wealth and children - like the example of a rain whose [resulting] plant growth pleases the tillers; then it dries and you see it turned yellow; then it becomes [scattered] debris. And in the Hereafter is severe punishment and forgiveness from Allah and approval. And what is the worldly life except the enjoyment of delusion.' },
  { surahId: 57, ayahNumber: 21, text: 'Race toward forgiveness from your Lord and a Garden whose width is like the width of the heavens and earth, prepared for those who believed in Allah and His messengers. That is the bounty of Allah which He gives to whom He wills, and Allah is the possessor of great bounty.' },
  { surahId: 57, ayahNumber: 22, text: 'No disaster strikes upon the earth or among yourselves except that it is in a register before We bring it into being - indeed that, for Allah, is easy -' },
  { surahId: 57, ayahNumber: 23, text: 'In order that you not despair over what has eluded you and not exult [in pride] over what He has given you. And Allah does not like everyone self-deluded and boastful -' },
  { surahId: 57, ayahNumber: 24, text: '[Those] who are stingy and enjoin upon people stinginess. And whoever turns away - then indeed, Allah is the Free of need, the Praiseworthy.' },
  { surahId: 57, ayahNumber: 25, text: 'We have already sent Our messengers with clear evidences and sent down with them the Scripture and the balance that the people may maintain [their affairs] in justice. And We sent down iron, wherein is great military might and benefits for the people, and so that Allah may make evident those who support Him and His messengers unseen. Indeed, Allah is Powerful and Exalted in Might.' },
  { surahId: 57, ayahNumber: 26, text: 'And We have already sent Noah and Abraham and placed in their descendants prophethood and scripture; and among them is he who is guided, but many of them are defiantly disobedient.' },
  { surahId: 57, ayahNumber: 27, text: 'Then We sent following their footsteps Our messengers and followed [them] with Jesus, the son of Mary, and gave him the Gospel. And We placed in the hearts of those who followed him compassion and mercy and monasticism, which they innovated; We did not prescribe it for them except [that they did so] seeking the approval of Allah. But they did not observe it with due observance. So We gave the ones who believed among them their reward, but many of them are defiantly disobedient.' },
  { surahId: 57, ayahNumber: 28, text: 'O you who have believed, fear Allah and believe in His Messenger; He will [then] give you a double portion of His mercy and make for you a light by which you will walk and forgive you; and Allah is Forgiving and Merciful.' },
  { surahId: 57, ayahNumber: 29, text: '[This is] so that the People of the Scripture may know that they are not able [to obtain] anything from the bounty of Allah and that [all] bounty is in the hand of Allah; He gives it to whom He wills. And Allah is the possessor of great bounty.' },
  { surahId: 58, ayahNumber: 1, text: 'Certainly has Allah heard the speech of the one who argues with you, [O Muhammad], concerning her husband and directs her complaint to Allah. And Allah hears your dialogue; indeed, Allah is Hearing and Seeing.' },
  { surahId: 58, ayahNumber: 2, text: 'Those who pronounce thihar among you [to separate] from their wives - they are not [consequently] their mothers. Their mothers are none but those who gave birth to them. And indeed, they are saying an objectionable statement and a falsehood. But indeed, Allah is Pardoning and Forgiving.' },
  { surahId: 58, ayahNumber: 3, text: 'And those who pronounce thihar from their wives and then [wish to] go back on what they said - then [there must be] the freeing of a slave before they touch one another. That is what you are admonished thereby; and Allah is Acquainted with what you do.' },
  { surahId: 58, ayahNumber: 4, text: 'And he who does not find [a slave] - then a fast for two months consecutively before they touch one another; and he who is unable - then the feeding of sixty poor persons. That is for you to believe [completely] in Allah and His Messenger; and those are the limits [set by] Allah. And for the disbelievers is a painful punishment.' },
  { surahId: 58, ayahNumber: 5, text: 'Indeed, those who oppose Allah and His Messenger are abased as those before them were abased. And We have certainly sent down verses of clear evidence. And for the disbelievers is a humiliating punishment.' },
  { surahId: 58, ayahNumber: 6, text: 'On the Day when Allah will resurrect them all and inform them of what they did. Allah had enumerated it, while they forgot it; and Allah is, over all things, Witness.' },
  { surahId: 58, ayahNumber: 7, text: 'Have you not considered that Allah knows what is in the heavens and what is on the earth? There is in no private conversation three but that He is the fourth of them, nor are there five but that He is the sixth of them - and no less than that and no more except that He is with them [in knowledge] wherever they are. Then He will inform them of what they did, on the Day of Resurrection. Indeed Allah is, of all things, Knowing.' },
  { surahId: 58, ayahNumber: 8, text: 'Have you not considered those who were forbidden from private conversation, then they return to that which they were forbidden and converse among themselves about sin and aggression and disobedience to the Messenger? And when they come to you, they greet you with that [word] by which Allah does not greet you and say among themselves, "Why does Allah not punish us for what we say?" Sufficient for them is Hell, which they will [enter to] burn, and wretched is the destination.' },
  { surahId: 58, ayahNumber: 9, text: 'O you who have believed, when you converse privately, do not converse about sin and aggression and disobedience to the Messenger but converse about righteousness and piety. And fear Allah, to whom you will be gathered.' },
  { surahId: 58, ayahNumber: 10, text: 'Private conversation is only from Satan that he may grieve those who have believed, but he will not harm them at all except by permission of Allah. And upon Allah let the believers rely.' },
  { surahId: 58, ayahNumber: 11, text: 'O you who have believed, when you are told, "Space yourselves" in assemblies, then make space; Allah will make space for you. And when you are told, "Arise," then arise; Allah will raise those who have believed among you and those who were given knowledge, by degrees. And Allah is Acquainted with what you do.' },
  { surahId: 58, ayahNumber: 12, text: 'O you who have believed, when you [wish to] privately consult the Messenger, present before your consultation a charity. That is better for you and purer. But if you find not [the means] - then indeed, Allah is Forgiving and Merciful.' },
  { surahId: 58, ayahNumber: 13, text: 'Have you feared to present before your consultation charities? Then when you do not and Allah has forgiven you, then [at least] establish prayer and give zakah and obey Allah and His Messenger. And Allah is Acquainted with what you do.' },
  { surahId: 58, ayahNumber: 14, text: 'Have you not considered those who make allies of a people with whom Allah has become angry? They are neither of you nor of them, and they swear to untruth while they know [they are lying].' },
  { surahId: 58, ayahNumber: 15, text: 'Allah has prepared for them a severe punishment. Indeed, it was evil that they were doing.' },
  { surahId: 58, ayahNumber: 16, text: 'They took their [false] oaths as a cover, so they averted [people] from the way of Allah, and for them is a humiliating punishment.' },
  { surahId: 58, ayahNumber: 17, text: 'Never will their wealth or their children avail them against Allah at all. Those are the companions of the Fire; they will abide therein eternally' },
  { surahId: 58, ayahNumber: 18, text: 'On the Day Allah will resurrect them all, and they will swear to Him as they swear to you and think that they are [standing] on something. Unquestionably, it is they who are the liars.' },
  { surahId: 58, ayahNumber: 19, text: 'Satan has overcome them and made them forget the remembrance of Allah. Those are the party of Satan. Unquestionably, the party of Satan - they will be the losers.' },
  { surahId: 58, ayahNumber: 20, text: 'Indeed, the ones who oppose Allah and His Messenger - those will be among the most humbled.' },
  { surahId: 58, ayahNumber: 21, text: 'Allah has written, "I will surely overcome, I and My messengers." Indeed, Allah is Powerful and Exalted in Might.' },
  { surahId: 58, ayahNumber: 22, text: 'You will not find a people who believe in Allah and the Last Day having affection for those who oppose Allah and His Messenger, even if they were their fathers or their sons or their brothers or their kindred. Those - He has decreed within their hearts faith and supported them with spirit from Him. And We will admit them to gardens beneath which rivers flow, wherein they abide eternally. Allah is pleased with them, and they are pleased with Him - those are the party of Allah. Unquestionably, the party of Allah - they are the successful.' },
  { surahId: 59, ayahNumber: 1, text: 'Whatever is in the heavens and whatever is on the earth exalts Allah, and He is the Exalted in Might, the Wise.' },
  { surahId: 59, ayahNumber: 2, text: 'It is He who expelled the ones who disbelieved among the People of the Scripture from their homes at the first gathering. You did not think they would leave, and they thought that their fortresses would protect them from Allah; but [the decree of] Allah came upon them from where they had not expected, and He cast terror into their hearts [so] they destroyed their houses by their [own] hands and the hands of the believers. So take warning, O people of vision.' },
  { surahId: 59, ayahNumber: 3, text: 'And if not that Allah had decreed for them evacuation, He would have punished them in [this] world, and for them in the Hereafter is the punishment of the Fire.' },
  { surahId: 59, ayahNumber: 4, text: 'That is because they opposed Allah and His Messenger. And whoever opposes Allah - then indeed, Allah is severe in penalty.' },
  { surahId: 59, ayahNumber: 5, text: 'Whatever you have cut down of [their] palm trees or left standing on their trunks - it was by permission of Allah and so He would disgrace the defiantly disobedient.' },
  { surahId: 59, ayahNumber: 6, text: 'And what Allah restored [of property] to His Messenger from them - you did not spur for it [in an expedition] any horses or camels, but Allah gives His messengers power over whom He wills, and Allah is over all things competent.' },
  { surahId: 59, ayahNumber: 7, text: 'And what Allah restored to His Messenger from the people of the towns - it is for Allah and for the Messenger and for [his] near relatives and orphans and the [stranded] traveler - so that it will not be a perpetual distribution among the rich from among you. And whatever the Messenger has given you - take; and what he has forbidden you - refrain from. And fear Allah; indeed, Allah is severe in penalty.' },
  { surahId: 59, ayahNumber: 8, text: 'For the poor emigrants who were expelled from their homes and their properties, seeking bounty from Allah and [His] approval and supporting Allah and His Messenger, [there is also a share]. Those are the truthful.' },
  { surahId: 59, ayahNumber: 9, text: 'And [also for] those who were settled in al-Madinah and [adopted] the faith before them. They love those who emigrated to them and find not any want in their breasts of what the emigrants were given but give [them] preference over themselves, even though they are in privation. And whoever is protected from the stinginess of his soul - it is those who will be the successful.' },
  { surahId: 59, ayahNumber: 10, text: 'And [there is a share for] those who came after them, saying, "Our Lord, forgive us and our brothers who preceded us in faith and put not in our hearts [any] resentment toward those who have believed. Our Lord, indeed You are Kind and Merciful."' },
  { surahId: 59, ayahNumber: 11, text: 'Have you not considered those who practice hypocrisy, saying to their brothers who have disbelieved among the People of the Scripture, "If you are expelled, we will surely leave with you, and we will not obey, in regard to you, anyone - ever; and if you are fought, we will surely aid you." But Allah testifies that they are liars.' },
  { surahId: 59, ayahNumber: 12, text: 'If they are expelled, they will not leave with them, and if they are fought, they will not aid them. And [even] if they should aid them, they will surely turn their backs; then [thereafter] they will not be aided.' },
  { surahId: 59, ayahNumber: 13, text: 'You [believers] are more fearful within their breasts than Allah. That is because they are a people who do not understand.' },
  { surahId: 59, ayahNumber: 14, text: 'They will not fight you all except within fortified cities or from behind walls. Their violence among themselves is severe. You think they are together, but their hearts are diverse. That is because they are a people who do not reason.' },
  { surahId: 59, ayahNumber: 15, text: '[Theirs is] like the example of those shortly before them: they tasted the bad consequence of their affair, and they will have a painful punishment.' },
  { surahId: 59, ayahNumber: 16, text: '[The hypocrites are] like the example of Satan when he says to man, "Disbelieve." But when he disbelieves, he says, "Indeed, I am disassociated from you. Indeed, I fear Allah, Lord of the worlds."' },
  { surahId: 59, ayahNumber: 17, text: 'So the outcome for both of them is that they will be in the Fire, abiding eternally therein. And that is the recompense of the wrong-doers.' },
  { surahId: 59, ayahNumber: 18, text: 'O you who have believed, fear Allah. And let every soul look to what it has put forth for tomorrow - and fear Allah. Indeed, Allah is Acquainted with what you do.' },
  { surahId: 59, ayahNumber: 19, text: 'And be not like those who forgot Allah, so He made them forget themselves. Those are the defiantly disobedient.' },
  { surahId: 59, ayahNumber: 20, text: 'Not equal are the companions of the Fire and the companions of Paradise. The companions of Paradise - they are the attainers [of success].' },
  { surahId: 59, ayahNumber: 21, text: 'If We had sent down this Qur\'an upon a mountain, you would have seen it humbled and coming apart from fear of Allah. And these examples We present to the people that perhaps they will give thought.' },
  { surahId: 59, ayahNumber: 22, text: 'He is Allah, other than whom there is no deity, Knower of the unseen and the witnessed. He is the Entirely Merciful, the Especially Merciful.' },
  { surahId: 59, ayahNumber: 23, text: 'He is Allah, other than whom there is no deity, the Sovereign, the Pure, the Perfection, the Bestower of Faith, the Overseer, the Exalted in Might, the Compeller, the Superior. Exalted is Allah above whatever they associate with Him.' },
  { surahId: 59, ayahNumber: 24, text: 'He is Allah, the Creator, the Inventor, the Fashioner; to Him belong the best names. Whatever is in the heavens and earth is exalting Him. And He is the Exalted in Might, the Wise.' },
  { surahId: 60, ayahNumber: 1, text: 'O you who have believed, do not take My enemies and your enemies as allies, extending to them affection while they have disbelieved in what came to you of the truth, having driven out the Prophet and yourselves [only] because you believe in Allah, your Lord. If you have come out for jihad in My cause and seeking means to My approval, [take them not as friends]. You confide to them affection, but I am most knowing of what you have concealed and what you have declared. And whoever does it among you has certainly strayed from the soundness of the way.' },
  { surahId: 60, ayahNumber: 2, text: 'If they gain dominance over you, they would be to you as enemies and extend against you their hands and their tongues with evil, and they wish you would disbelieve.' },
  { surahId: 60, ayahNumber: 3, text: 'Never will your relatives or your children benefit you; the Day of Resurrection He will judge between you. And Allah, of what you do, is Seeing.' },
  { surahId: 60, ayahNumber: 4, text: 'There has already been for you an excellent pattern in Abraham and those with him, when they said to their people, "Indeed, we are disassociated from you and from whatever you worship other than Allah. We have denied you, and there has appeared between us and you animosity and hatred forever until you believe in Allah alone" except for the saying of Abraham to his father, "I will surely ask forgiveness for you, but I have not [power to do] for you anything against Allah. Our Lord, upon You we have relied, and to You we have returned, and to You is the destination.' },
  { surahId: 60, ayahNumber: 5, text: 'Our Lord, make us not [objects of] torment for the disbelievers and forgive us, our Lord. Indeed, it is You who is the Exalted in Might, the Wise."' },
  { surahId: 60, ayahNumber: 6, text: 'There has certainly been for you in them an excellent pattern for anyone whose hope is in Allah and the Last Day. And whoever turns away - then indeed, Allah is the Free of need, the Praiseworthy.' },
  { surahId: 60, ayahNumber: 7, text: 'Perhaps Allah will put, between you and those to whom you have been enemies among them, affection. And Allah is competent, and Allah is Forgiving and Merciful.' },
  { surahId: 60, ayahNumber: 8, text: 'Allah does not forbid you from those who do not fight you because of religion and do not expel you from your homes - from being righteous toward them and acting justly toward them. Indeed, Allah loves those who act justly.' },
  { surahId: 60, ayahNumber: 9, text: 'Allah only forbids you from those who fight you because of religion and expel you from your homes and aid in your expulsion - [forbids] that you make allies of them. And whoever makes allies of them, then it is those who are the wrongdoers.' },
  { surahId: 60, ayahNumber: 10, text: 'O you who have believed, when the believing women come to you as emigrants, examine them. Allah is most knowing as to their faith. And if you know them to be believers, then do not return them to the disbelievers; they are not lawful [wives] for them, nor are they lawful [husbands] for them. But give the disbelievers what they have spent. And there is no blame upon you if you marry them when you have given them their due compensation. And hold not to marriage bonds with disbelieving women, but ask for what you have spent and let them ask for what they have spent. That is the judgement of Allah; He judges between you. And Allah is Knowing and Wise.' },
  { surahId: 60, ayahNumber: 11, text: 'And if you have lost any of your wives to the disbelievers and you subsequently obtain [something], then give those whose wives have gone the equivalent of what they had spent. And fear Allah, in whom you are believers.' },
  { surahId: 60, ayahNumber: 12, text: 'O Prophet, when the believing women come to you pledging to you that they will not associate anything with Allah, nor will they steal, nor will they commit unlawful sexual intercourse, nor will they kill their children, nor will they bring forth a slander they have invented between their arms and legs, nor will they disobey you in what is right - then accept their pledge and ask forgiveness for them of Allah. Indeed, Allah is Forgiving and Merciful.' },
  { surahId: 60, ayahNumber: 13, text: 'O you who have believed, do not make allies of a people with whom Allah has become angry. They have despaired of [reward in] the Hereafter just as the disbelievers have despaired of [meeting] the inhabitants of the graves.' },
  { surahId: 61, ayahNumber: 1, text: 'Whatever is in the heavens and whatever is on the earth exalts Allah, and He is the Exalted in Might, the Wise.' },
  { surahId: 61, ayahNumber: 2, text: 'O you who have believed, why do you say what you do not do?' },
  { surahId: 61, ayahNumber: 3, text: 'Great is hatred in the sight of Allah that you say what you do not do.' },
  { surahId: 61, ayahNumber: 4, text: 'Indeed, Allah loves those who fight in His cause in a row as though they are a [single] structure joined firmly.' },
  { surahId: 61, ayahNumber: 5, text: 'And [mention, O Muhammad], when Moses said to his people, "O my people, why do you harm me while you certainly know that I am the messenger of Allah to you?" And when they deviated, Allah caused their hearts to deviate. And Allah does not guide the defiantly disobedient people.' },
  { surahId: 61, ayahNumber: 6, text: 'And [mention] when Jesus, the son of Mary, said, "O children of Israel, indeed I am the messenger of Allah to you confirming what came before me of the Torah and bringing good tidings of a messenger to come after me, whose name is Ahmad." But when he came to them with clear evidences, they said, "This is obvious magic."' },
  { surahId: 61, ayahNumber: 7, text: 'And who is more unjust than one who invents about Allah untruth while he is being invited to Islam. And Allah does not guide the wrongdoing people.' },
  { surahId: 61, ayahNumber: 8, text: 'They want to extinguish the light of Allah with their mouths, but Allah will perfect His light, although the disbelievers dislike it.' },
  { surahId: 61, ayahNumber: 9, text: 'It is He who sent His Messenger with guidance and the religion of truth to manifest it over all religion, although those who associate others with Allah dislike it.' },
  { surahId: 61, ayahNumber: 10, text: 'O you who have believed, shall I guide you to a transaction that will save you from a painful punishment?' },
  { surahId: 61, ayahNumber: 11, text: '[It is that] you believe in Allah and His Messenger and strive in the cause of Allah with your wealth and your lives. That is best for you, if you should know.' },
  { surahId: 61, ayahNumber: 12, text: 'He will forgive for you your sins and admit you to gardens beneath which rivers flow and pleasant dwellings in gardens of perpetual residence. That is the great attainment.' },
  { surahId: 61, ayahNumber: 13, text: 'And [you will obtain] another [favor] that you love - victory from Allah and an imminent conquest; and give good tidings to the believers.' },
  { surahId: 61, ayahNumber: 14, text: 'O you who have believed, be supporters of Allah, as when Jesus, the son of Mary, said to the disciples, "Who are my supporters for Allah?" The disciples said, "We are supporters of Allah." And a faction of the Children of Israel believed and a faction disbelieved. So We supported those who believed against their enemy, and they became dominant.' },
  { surahId: 62, ayahNumber: 1, text: 'Whatever is in the heavens and whatever is on the earth is exalting Allah, the Sovereign, the Pure, the Exalted in Might, the Wise.' },
  { surahId: 62, ayahNumber: 2, text: 'It is He who has sent among the unlettered a Messenger from themselves reciting to them His verses and purifying them and teaching them the Book and wisdom - although they were before in clear error -' },
  { surahId: 62, ayahNumber: 3, text: 'And [to] others of them who have not yet joined them. And He is the Exalted in Might, the Wise.' },
  { surahId: 62, ayahNumber: 4, text: 'That is the bounty of Allah, which He gives to whom He wills, and Allah is the possessor of great bounty.' },
  { surahId: 62, ayahNumber: 5, text: 'The example of those who were entrusted with the Torah and then did not take it on is like that of a donkey who carries volumes [of books]. Wretched is the example of the people who deny the signs of Allah. And Allah does not guide the wrongdoing people.' },
  { surahId: 62, ayahNumber: 6, text: 'Say, "O you who are Jews, if you claim that you are allies of Allah, excluding the [other] people, then wish for death, if you should be truthful."' },
  { surahId: 62, ayahNumber: 7, text: 'But they will not wish for it, ever, because of what their hands have put forth. And Allah is Knowing of the wrongdoers.' },
  { surahId: 62, ayahNumber: 8, text: 'Say, "Indeed, the death from which you flee - indeed, it will meet you. Then you will be returned to the Knower of the unseen and the witnessed, and He will inform you about what you used to do."' },
  { surahId: 62, ayahNumber: 9, text: 'O you who have believed, when [the adhan] is called for the prayer on the day of Jumu\'ah [Friday], then proceed to the remembrance of Allah and leave trade. That is better for you, if you only knew.' },
  { surahId: 62, ayahNumber: 10, text: 'And when the prayer has been concluded, disperse within the land and seek from the bounty of Allah, and remember Allah often that you may succeed.' },
  { surahId: 62, ayahNumber: 11, text: 'But when they saw a transaction or a diversion, [O Muhammad], they rushed to it and left you standing. Say, "What is with Allah is better than diversion and than a transaction, and Allah is the best of providers."' },
  { surahId: 63, ayahNumber: 1, text: 'When the hypocrites come to you, [O Muhammad], they say, "We testify that you are the Messenger of Allah." And Allah knows that you are His Messenger, and Allah testifies that the hypocrites are liars.' },
  { surahId: 63, ayahNumber: 2, text: 'They have taken their oaths as a cover, so they averted [people] from the way of Allah. Indeed, it was evil that they were doing.' },
  { surahId: 63, ayahNumber: 3, text: 'That is because they believed, and then they disbelieved; so their hearts were sealed over, and they do not understand.' },
  { surahId: 63, ayahNumber: 4, text: 'And when you see them, their forms please you, and if they speak, you listen to their speech. [They are] as if they were pieces of wood propped up - they think that every shout is against them. They are the enemy, so beware of them. May Allah destroy them; how are they deluded?' },
  { surahId: 63, ayahNumber: 5, text: 'And when it is said to them, "Come, the Messenger of Allah will ask forgiveness for you," they turn their heads aside and you see them evading while they are arrogant.' },
  { surahId: 63, ayahNumber: 6, text: 'It is all the same for them whether you ask forgiveness for them or do not ask forgiveness for them; never will Allah forgive them. Indeed, Allah does not guide the defiantly disobedient people.' },
  { surahId: 63, ayahNumber: 7, text: 'They are the ones who say, "Do not spend on those who are with the Messenger of Allah until they disband." And to Allah belongs the depositories of the heavens and the earth, but the hypocrites do not understand.' },
  { surahId: 63, ayahNumber: 8, text: 'They say, "If we return to al-Madinah, the more honored [for power] will surely expel therefrom the more humble." And to Allah belongs [all] honor, and to His Messenger, and to the believers, but the hypocrites do not know.' },
  { surahId: 63, ayahNumber: 9, text: 'O you who have believed, let not your wealth and your children divert you from remembrance of Allah. And whoever does that - then those are the losers.' },
  { surahId: 63, ayahNumber: 10, text: 'And spend [in the way of Allah] from what We have provided you before death approaches one of you and he says, "My Lord, if only You would delay me for a brief term so I would give charity and be among the righteous."' },
  { surahId: 63, ayahNumber: 11, text: 'But never will Allah delay a soul when its time has come. And Allah is Acquainted with what you do.' },
  { surahId: 64, ayahNumber: 1, text: 'Whatever is in the heavens and whatever is on the earth is exalting Allah. To Him belongs dominion, and to Him belongs [all] praise, and He is over all things competent.' },
  { surahId: 64, ayahNumber: 2, text: 'It is He who created you, and among you is the disbeliever, and among you is the believer. And Allah, of what you do, is Seeing.' },
  { surahId: 64, ayahNumber: 3, text: 'He created the heavens and earth in truth and formed you and perfected your forms; and to Him is the [final] destination.' },
  { surahId: 64, ayahNumber: 4, text: 'He knows what is within the heavens and earth and knows what you conceal and what you declare. And Allah is Knowing of that within the breasts.' },
  { surahId: 64, ayahNumber: 5, text: 'Has there not come to you the news of those who disbelieved before? So they tasted the bad consequence of their affair, and they will have a painful punishment.' },
  { surahId: 64, ayahNumber: 6, text: 'That is because their messengers used to come to them with clear evidences, but they said, "Shall human beings guide us?" and disbelieved and turned away. And Allah dispensed [with them]; and Allah is Free of need and Praiseworthy.' },
  { surahId: 64, ayahNumber: 7, text: 'Those who disbelieve have claimed that they will never be resurrected. Say, "Yes, by my Lord, you will surely be resurrected; then you will surely be informed of what you did. And that, for Allah, is easy."' },
  { surahId: 64, ayahNumber: 8, text: 'So believe in Allah and His Messenger and the Qur\'an which We have sent down. And Allah is Acquainted with what you do.' },
  { surahId: 64, ayahNumber: 9, text: 'The Day He will assemble you for the Day of Assembly - that is the Day of Deprivation. And whoever believes in Allah and does righteousness - He will remove from him his misdeeds and admit him to gardens beneath which rivers flow, wherein they will abide forever. That is the great attainment.' },
  { surahId: 64, ayahNumber: 10, text: 'But the ones who disbelieved and denied Our verses - those are the companions of the Fire, abiding eternally therein; and wretched is the destination.' },
  { surahId: 64, ayahNumber: 11, text: 'No disaster strikes except by permission of Allah. And whoever believes in Allah - He will guide his heart. And Allah is Knowing of all things.' },
  { surahId: 64, ayahNumber: 12, text: 'And obey Allah and obey the Messenger; but if you turn away - then upon Our Messenger is only [the duty of] clear notification.' },
  { surahId: 64, ayahNumber: 13, text: 'Allah - there is no deity except Him. And upon Allah let the believers rely.' },
  { surahId: 64, ayahNumber: 14, text: 'O you who have believed, indeed, among your wives and your children are enemies to you, so beware of them. But if you pardon and overlook and forgive - then indeed, Allah is Forgiving and Merciful.' },
  { surahId: 64, ayahNumber: 15, text: 'Your wealth and your children are but a trial, and Allah has with Him a great reward.' },
  { surahId: 64, ayahNumber: 16, text: 'So fear Allah as much as you are able and listen and obey and spend [in the way of Allah]; it is better for your selves. And whoever is protected from the stinginess of his soul - it is those who will be the successful.' },
  { surahId: 64, ayahNumber: 17, text: 'If you loan Allah a goodly loan, He will multiply it for you and forgive you. And Allah is Most Appreciative and Forbearing.' },
  { surahId: 64, ayahNumber: 18, text: 'Knower of the unseen and the witnessed, the Exalted in Might, the Wise.' },
  { surahId: 65, ayahNumber: 1, text: 'O Prophet, when you [Muslims] divorce women, divorce them for [the commencement of] their waiting period and keep count of the waiting period, and fear Allah, your Lord. Do not turn them out of their [husbands\'] houses, nor should they [themselves] leave [during that period] unless they are committing a clear immorality. And those are the limits [set by] Allah. And whoever transgresses the limits of Allah has certainly wronged himself. You know not; perhaps Allah will bring about after that a [different] matter.' },
  { surahId: 65, ayahNumber: 2, text: 'And when they have [nearly] fulfilled their term, either retain them according to acceptable terms or part with them according to acceptable terms. And bring to witness two just men from among you and establish the testimony for [the acceptance of] Allah. That is instructed to whoever should believe in Allah and the Last day. And whoever fears Allah - He will make for him a way out' },
  { surahId: 65, ayahNumber: 3, text: 'And will provide for him from where he does not expect. And whoever relies upon Allah - then He is sufficient for him. Indeed, Allah will accomplish His purpose. Allah has already set for everything a [decreed] extent.' },
  { surahId: 65, ayahNumber: 4, text: 'And those who no longer expect menstruation among your women - if you doubt, then their period is three months, and [also for] those who have not menstruated. And for those who are pregnant, their term is until they give birth. And whoever fears Allah - He will make for him of his matter ease.' },
  { surahId: 65, ayahNumber: 5, text: 'That is the command of Allah, which He has sent down to you; and whoever fears Allah - He will remove for him his misdeeds and make great for him his reward.' },
  { surahId: 65, ayahNumber: 6, text: 'Lodge them [in a section] of where you dwell out of your means and do not harm them in order to oppress them. And if they should be pregnant, then spend on them until they give birth. And if they breastfeed for you, then give them their payment and confer among yourselves in the acceptable way; but if you are in discord, then there may breastfeed for the father another woman.' },
  { surahId: 65, ayahNumber: 7, text: 'Let a man of wealth spend from his wealth, and he whose provision is restricted - let him spend from what Allah has given him. Allah does not charge a soul except [according to] what He has given it. Allah will bring about, after hardship, ease.' },
  { surahId: 65, ayahNumber: 8, text: 'And how many a city was insolent toward the command of its Lord and His messengers, so We took it to severe account and punished it with a terrible punishment.' },
  { surahId: 65, ayahNumber: 9, text: 'And it tasted the bad consequence of its affair, and the outcome of its affair was loss.' },
  { surahId: 65, ayahNumber: 10, text: 'Allah has prepared for them a severe punishment; so fear Allah, O you of understanding who have believed. Allah has sent down to you the Qur\'an.' },
  { surahId: 65, ayahNumber: 11, text: '[He sent] a Messenger [Muhammad] reciting to you the distinct verses of Allah that He may bring out those who believe and do righteous deeds from darknesses into the light. And whoever believes in Allah and does righteousness - He will admit him into gardens beneath which rivers flow to abide therein forever. Allah will have perfected for him a provision.' },
  { surahId: 65, ayahNumber: 12, text: 'It is Allah who has created seven heavens and of the earth, the like of them. [His] command descends among them so you may know that Allah is over all things competent and that Allah has encompassed all things in knowledge.' },
  { surahId: 66, ayahNumber: 1, text: 'O Prophet, why do you prohibit [yourself from] what Allah has made lawful for you, seeking the approval of your wives? And Allah is Forgiving and Merciful.' },
  { surahId: 66, ayahNumber: 2, text: 'Allah has already ordained for you [Muslims] the dissolution of your oaths. And Allah is your protector, and He is the Knowing, the Wise.' },
  { surahId: 66, ayahNumber: 3, text: 'And [remember] when the Prophet confided to one of his wives a statement; and when she informed [another] of it and Allah showed it to him, he made known part of it and ignored a part. And when he informed her about it, she said, "Who told you this?" He said, "I was informed by the Knowing, the Acquainted."' },
  { surahId: 66, ayahNumber: 4, text: 'If you two [wives] repent to Allah, [it is best], for your hearts have deviated. But if you cooperate against him - then indeed Allah is his protector, and Gabriel and the righteous of the believers and the angels, moreover, are [his] assistants.' },
  { surahId: 66, ayahNumber: 5, text: 'Perhaps his Lord, if he divorced you [all], would substitute for him wives better than you - submitting [to Allah], believing, devoutly obedient, repentant, worshipping, and traveling - [ones] previously married and virgins.' },
  { surahId: 66, ayahNumber: 6, text: 'O you who have believed, protect yourselves and your families from a Fire whose fuel is people and stones, over which are [appointed] angels, harsh and severe; they do not disobey Allah in what He commands them but do what they are commanded.' },
  { surahId: 66, ayahNumber: 7, text: 'O you who have disbelieved, make no excuses that Day. You will only be recompensed for what you used to do.' },
  { surahId: 66, ayahNumber: 8, text: 'O you who have believed, repent to Allah with sincere repentance. Perhaps your Lord will remove from you your misdeeds and admit you into gardens beneath which rivers flow [on] the Day when Allah will not disgrace the Prophet and those who believed with him. Their light will proceed before them and on their right; they will say, "Our Lord, perfect for us our light and forgive us. Indeed, You are over all things competent."' },
  { surahId: 66, ayahNumber: 9, text: 'O Prophet, strive against the disbelievers and the hypocrites and be harsh upon them. And their refuge is Hell, and wretched is the destination.' },
  { surahId: 66, ayahNumber: 10, text: 'Allah presents an example of those who disbelieved: the wife of Noah and the wife of Lot. They were under two of Our righteous servants but betrayed them, so those prophets did not avail them from Allah at all, and it was said, "Enter the Fire with those who enter."' },
  { surahId: 66, ayahNumber: 11, text: 'And Allah presents an example of those who believed: the wife of Pharaoh, when she said, "My Lord, build for me near You a house in Paradise and save me from Pharaoh and his deeds and save me from the wrongdoing people."' },
  { surahId: 66, ayahNumber: 12, text: 'And [the example of] Mary, the daughter of \'Imran, who guarded her chastity, so We blew into [her garment] through Our angel, and she believed in the words of her Lord and His scriptures and was of the devoutly obedient.' },
  { surahId: 67, ayahNumber: 1, text: 'Blessed is He in whose hand is dominion, and He is over all things competent -' },
  { surahId: 67, ayahNumber: 2, text: '[He] who created death and life to test you [as to] which of you is best in deed - and He is the Exalted in Might, the Forgiving -' },
  { surahId: 67, ayahNumber: 3, text: '[And] who created seven heavens in layers. You do not see in the creation of the Most Merciful any inconsistency. So return [your] vision [to the sky]; do you see any breaks?' },
  { surahId: 67, ayahNumber: 4, text: 'Then return [your] vision twice again. [Your] vision will return to you humbled while it is fatigued.' },
  { surahId: 67, ayahNumber: 5, text: 'And We have certainly beautified the nearest heaven with stars and have made [from] them what is thrown at the devils and have prepared for them the punishment of the Blaze.' },
  { surahId: 67, ayahNumber: 6, text: 'And for those who disbelieved in their Lord is the punishment of Hell, and wretched is the destination.' },
  { surahId: 67, ayahNumber: 7, text: 'When they are thrown into it, they hear from it a [dreadful] inhaling while it boils up.' },
  { surahId: 67, ayahNumber: 8, text: 'It almost bursts with rage. Every time a company is thrown into it, its keepers ask them, "Did there not come to you a warner?"' },
  { surahId: 67, ayahNumber: 9, text: 'They will say," Yes, a warner had come to us, but we denied and said, \'Allah has not sent down anything. You are not but in great error.\'"' },
  { surahId: 67, ayahNumber: 10, text: 'And they will say, "If only we had been listening or reasoning, we would not be among the companions of the Blaze."' },
  { surahId: 67, ayahNumber: 11, text: 'And they will admit their sin, so [it is] alienation for the companions of the Blaze.' },
  { surahId: 67, ayahNumber: 12, text: 'Indeed, those who fear their Lord unseen will have forgiveness and great reward.' },
  { surahId: 67, ayahNumber: 13, text: 'And conceal your speech or publicize it; indeed, He is Knowing of that within the breasts.' },
  { surahId: 67, ayahNumber: 14, text: 'Does He who created not know, while He is the Subtle, the Acquainted?' },
  { surahId: 67, ayahNumber: 15, text: 'It is He who made the earth tame for you - so walk among its slopes and eat of His provision - and to Him is the resurrection.' },
  { surahId: 67, ayahNumber: 16, text: 'Do you feel secure that He who [holds authority] in the heaven would not cause the earth to swallow you and suddenly it would sway?' },
  { surahId: 67, ayahNumber: 17, text: 'Or do you feel secure that He who [holds authority] in the heaven would not send against you a storm of stones? Then you would know how [severe] was My warning.' },
  { surahId: 67, ayahNumber: 18, text: 'And already had those before them denied, and how [terrible] was My reproach.' },
  { surahId: 67, ayahNumber: 19, text: 'Do they not see the birds above them with wings outspread and [sometimes] folded in? None holds them [aloft] except the Most Merciful. Indeed He is, of all things, Seeing.' },
  { surahId: 67, ayahNumber: 20, text: 'Or who is it that could be an army for you to aid you other than the Most Merciful? The disbelievers are not but in delusion.' },
  { surahId: 67, ayahNumber: 21, text: 'Or who is it that could provide for you if He withheld His provision? But they have persisted in insolence and aversion.' },
  { surahId: 67, ayahNumber: 22, text: 'Then is one who walks fallen on his face better guided or one who walks erect on a straight path?' },
  { surahId: 67, ayahNumber: 23, text: 'Say, "It is He who has produced you and made for you hearing and vision and hearts; little are you grateful."' },
  { surahId: 67, ayahNumber: 24, text: 'Say, "It is He who has multiplied you throughout the earth, and to Him you will be gathered."' },
  { surahId: 67, ayahNumber: 25, text: 'And they say, "When is this promise, if you should be truthful?"' },
  { surahId: 67, ayahNumber: 26, text: 'Say, "The knowledge is only with Allah, and I am only a clear warner."' },
  { surahId: 67, ayahNumber: 27, text: 'But when they see it approaching, the faces of those who disbelieve will be distressed, and it will be said, "This is that for which you used to call."' },
  { surahId: 67, ayahNumber: 28, text: 'Say, [O Muhammad], "Have you considered: whether Allah should cause my death and those with me or have mercy upon us, who can protect the disbelievers from a painful punishment?"' },
  { surahId: 67, ayahNumber: 29, text: 'Say, "He is the Most Merciful; we have believed in Him, and upon Him we have relied. And you will [come to] know who it is that is in clear error."' },
  { surahId: 67, ayahNumber: 30, text: 'Say, "Have you considered: if your water was to become sunken [into the earth], then who could bring you flowing water?"' },
  { surahId: 68, ayahNumber: 1, text: 'Nun. By the pen and what they inscribe,' },
  { surahId: 68, ayahNumber: 2, text: 'You are not, [O Muhammad], by the favor of your Lord, a madman.' },
  { surahId: 68, ayahNumber: 3, text: 'And indeed, for you is a reward uninterrupted.' },
  { surahId: 68, ayahNumber: 4, text: 'And indeed, you are of a great moral character.' },
  { surahId: 68, ayahNumber: 5, text: 'So you will see and they will see' },
  { surahId: 68, ayahNumber: 6, text: 'Which of you is the afflicted [by a devil].' },
  { surahId: 68, ayahNumber: 7, text: 'Indeed, your Lord is most knowing of who has gone astray from His way, and He is most knowing of the [rightly] guided.' },
  { surahId: 68, ayahNumber: 8, text: 'Then do not obey the deniers.' },
  { surahId: 68, ayahNumber: 9, text: 'They wish that you would soften [in your position], so they would soften [toward you].' },
  { surahId: 68, ayahNumber: 10, text: 'And do not obey every worthless habitual swearer' },
  { surahId: 68, ayahNumber: 11, text: '[And] scorner, going about with malicious gossip -' },
  { surahId: 68, ayahNumber: 12, text: 'A preventer of good, transgressing and sinful,' },
  { surahId: 68, ayahNumber: 13, text: 'Cruel, moreover, and an illegitimate pretender.' },
  { surahId: 68, ayahNumber: 14, text: 'Because he is a possessor of wealth and children,' },
  { surahId: 68, ayahNumber: 15, text: 'When Our verses are recited to him, he says, "Legends of the former peoples."' },
  { surahId: 68, ayahNumber: 16, text: 'We will brand him upon the snout.' },
  { surahId: 68, ayahNumber: 17, text: 'Indeed, We have tried them as We tried the companions of the garden, when they swore to cut its fruit in the [early] morning' },
  { surahId: 68, ayahNumber: 18, text: 'Without making exception.' },
  { surahId: 68, ayahNumber: 19, text: 'So there came upon the garden an affliction from your Lord while they were asleep.' },
  { surahId: 68, ayahNumber: 20, text: 'And it became as though reaped.' },
  { surahId: 68, ayahNumber: 21, text: 'And they called one another at morning,' },
  { surahId: 68, ayahNumber: 22, text: '[Saying], "Go early to your crop if you would cut the fruit."' },
  { surahId: 68, ayahNumber: 23, text: 'So they set out, while lowering their voices,' },
  { surahId: 68, ayahNumber: 24, text: '[Saying], "There will surely not enter it today upon you [any] poor person."' },
  { surahId: 68, ayahNumber: 25, text: 'And they went early in determination, [assuming themselves] able.' },
  { surahId: 68, ayahNumber: 26, text: 'But when they saw it, they said, "Indeed, we are lost;' },
  { surahId: 68, ayahNumber: 27, text: 'Rather, we have been deprived."' },
  { surahId: 68, ayahNumber: 28, text: 'The most moderate of them said, "Did I not say to you, \'Why do you not exalt [Allah]?\' "' },
  { surahId: 68, ayahNumber: 29, text: 'They said, "Exalted is our Lord! Indeed, we were wrongdoers."' },
  { surahId: 68, ayahNumber: 30, text: 'Then they approached one another, blaming each other.' },
  { surahId: 68, ayahNumber: 31, text: 'They said, "O woe to us; indeed we were transgressors.' },
  { surahId: 68, ayahNumber: 32, text: 'Perhaps our Lord will substitute for us [one] better than it. Indeed, we are toward our Lord desirous."' },
  { surahId: 68, ayahNumber: 33, text: 'Such is the punishment [of this world]. And the punishment of the Hereafter is greater, if they only knew.' },
  { surahId: 68, ayahNumber: 34, text: 'Indeed, for the righteous with their Lord are the Gardens of Pleasure.' },
  { surahId: 68, ayahNumber: 35, text: 'Then will We treat the Muslims like the criminals?' },
  { surahId: 68, ayahNumber: 36, text: 'What is [the matter] with you? How do you judge?' },
  { surahId: 68, ayahNumber: 37, text: 'Or do you have a scripture in which you learn' },
  { surahId: 68, ayahNumber: 38, text: 'That indeed for you is whatever you choose?' },
  { surahId: 68, ayahNumber: 39, text: 'Or do you have oaths [binding] upon Us, extending until the Day of Resurrection, that indeed for you is whatever you judge?' },
  { surahId: 68, ayahNumber: 40, text: 'Ask them which of them, for that [claim], is responsible.' },
  { surahId: 68, ayahNumber: 41, text: 'Or do they have partners? Then let them bring their partners, if they should be truthful.' },
  { surahId: 68, ayahNumber: 42, text: 'The Day the shin will be uncovered and they are invited to prostration but the disbelievers will not be able,' },
  { surahId: 68, ayahNumber: 43, text: 'Their eyes humbled, humiliation will cover them. And they used to be invited to prostration while they were sound.' },
  { surahId: 68, ayahNumber: 44, text: 'So leave Me, [O Muhammad], with [the matter of] whoever denies the Qur\'an. We will progressively lead them [to punishment] from where they do not know.' },
  { surahId: 68, ayahNumber: 45, text: 'And I will give them time. Indeed, My plan is firm.' },
  { surahId: 68, ayahNumber: 46, text: 'Or do you ask of them a payment, so they are by debt burdened down?' },
  { surahId: 68, ayahNumber: 47, text: 'Or have they [knowledge of] the unseen, so they write [it] down?' },
  { surahId: 68, ayahNumber: 48, text: 'Then be patient for the decision of your Lord, [O Muhammad], and be not like the companion of the fish when he called out while he was distressed.' },
  { surahId: 68, ayahNumber: 49, text: 'If not that a favor from his Lord overtook him, he would have been thrown onto the naked shore while he was censured.' },
  { surahId: 68, ayahNumber: 50, text: 'And his Lord chose him and made him of the righteous.' },
  { surahId: 68, ayahNumber: 51, text: 'And indeed, those who disbelieve would almost make you slip with their eyes when they hear the message, and they say, "Indeed, he is mad."' },
  { surahId: 68, ayahNumber: 52, text: 'But it is not except a reminder to the worlds.' },
  { surahId: 69, ayahNumber: 1, text: 'The Inevitable Reality -' },
  { surahId: 69, ayahNumber: 2, text: 'What is the Inevitable Reality?' },
  { surahId: 69, ayahNumber: 3, text: 'And what can make you know what is the Inevitable Reality?' },
  { surahId: 69, ayahNumber: 4, text: 'Thamud and \'Aad denied the Striking Calamity.' },
  { surahId: 69, ayahNumber: 5, text: 'So as for Thamud, they were destroyed by the overpowering [blast].' },
  { surahId: 69, ayahNumber: 6, text: 'And as for \'Aad, they were destroyed by a screaming, violent wind' },
  { surahId: 69, ayahNumber: 7, text: 'Which Allah imposed upon them for seven nights and eight days in succession, so you would see the people therein fallen as if they were hollow trunks of palm trees.' },
  { surahId: 69, ayahNumber: 8, text: 'Then do you see of them any remains?' },
  { surahId: 69, ayahNumber: 9, text: 'And there came Pharaoh and those before him and the overturned cities with sin.' },
  { surahId: 69, ayahNumber: 10, text: 'And they disobeyed the messenger of their Lord, so He seized them with a seizure exceeding [in severity].' },
  { surahId: 69, ayahNumber: 11, text: 'Indeed, when the water overflowed, We carried your ancestors in the sailing ship' },
  { surahId: 69, ayahNumber: 12, text: 'That We might make it for you a reminder and [that] a conscious ear would be conscious of it.' },
  { surahId: 69, ayahNumber: 13, text: 'Then when the Horn is blown with one blast' },
  { surahId: 69, ayahNumber: 14, text: 'And the earth and the mountains are lifted and leveled with one blow -' },
  { surahId: 69, ayahNumber: 15, text: 'Then on that Day, the Resurrection will occur,' },
  { surahId: 69, ayahNumber: 16, text: 'And the heaven will split [open], for that Day it is infirm.' },
  { surahId: 69, ayahNumber: 17, text: 'And the angels are at its edges. And there will bear the Throne of your Lord above them, that Day, eight [of them].' },
  { surahId: 69, ayahNumber: 18, text: 'That Day, you will be exhibited [for judgement]; not hidden among you is anything concealed.' },
  { surahId: 69, ayahNumber: 19, text: 'So as for he who is given his record in his right hand, he will say, "Here, read my record!' },
  { surahId: 69, ayahNumber: 20, text: 'Indeed, I was certain that I would be meeting my account."' },
  { surahId: 69, ayahNumber: 21, text: 'So he will be in a pleasant life -' },
  { surahId: 69, ayahNumber: 22, text: 'In an elevated garden,' },
  { surahId: 69, ayahNumber: 23, text: 'Its [fruit] to be picked hanging near.' },
  { surahId: 69, ayahNumber: 24, text: '[They will be told], "Eat and drink in satisfaction for what you put forth in the days past."' },
  { surahId: 69, ayahNumber: 25, text: 'But as for he who is given his record in his left hand, he will say, "Oh, I wish I had not been given my record' },
  { surahId: 69, ayahNumber: 26, text: 'And had not known what is my account.' },
  { surahId: 69, ayahNumber: 27, text: 'I wish my death had been the decisive one.' },
  { surahId: 69, ayahNumber: 28, text: 'My wealth has not availed me.' },
  { surahId: 69, ayahNumber: 29, text: 'Gone from me is my authority."' },
  { surahId: 69, ayahNumber: 30, text: '[Allah will say], "Seize him and shackle him.' },
  { surahId: 69, ayahNumber: 31, text: 'Then into Hellfire drive him.' },
  { surahId: 69, ayahNumber: 32, text: 'Then into a chain whose length is seventy cubits insert him."' },
  { surahId: 69, ayahNumber: 33, text: 'Indeed, he did not used to believe in Allah, the Most Great,' },
  { surahId: 69, ayahNumber: 34, text: 'Nor did he encourage the feeding of the poor.' },
  { surahId: 69, ayahNumber: 35, text: 'So there is not for him here this Day any devoted friend' },
  { surahId: 69, ayahNumber: 36, text: 'Nor any food except from the discharge of wounds;' },
  { surahId: 69, ayahNumber: 37, text: 'None will eat it except the sinners.' },
  { surahId: 69, ayahNumber: 38, text: 'So I swear by what you see' },
  { surahId: 69, ayahNumber: 39, text: 'And what you do not see' },
  { surahId: 69, ayahNumber: 40, text: '[That] indeed, the Qur\'an is the word of a noble Messenger.' },
  { surahId: 69, ayahNumber: 41, text: 'And it is not the word of a poet; little do you believe.' },
  { surahId: 69, ayahNumber: 42, text: 'Nor the word of a soothsayer; little do you remember.' },
  { surahId: 69, ayahNumber: 43, text: '[It is] a revelation from the Lord of the worlds.' },
  { surahId: 69, ayahNumber: 44, text: 'And if Muhammad had made up about Us some [false] sayings,' },
  { surahId: 69, ayahNumber: 45, text: 'We would have seized him by the right hand;' },
  { surahId: 69, ayahNumber: 46, text: 'Then We would have cut from him the aorta.' },
  { surahId: 69, ayahNumber: 47, text: 'And there is no one of you who could prevent [Us] from him.' },
  { surahId: 69, ayahNumber: 48, text: 'And indeed, the Qur\'an is a reminder for the righteous.' },
  { surahId: 69, ayahNumber: 49, text: 'And indeed, We know that among you are deniers.' },
  { surahId: 69, ayahNumber: 50, text: 'And indeed, it will be [a cause of] regret upon the disbelievers.' },
  { surahId: 69, ayahNumber: 51, text: 'And indeed, it is the truth of certainty.' },
  { surahId: 69, ayahNumber: 52, text: 'So exalt the name of your Lord, the Most Great.' },
  { surahId: 70, ayahNumber: 1, text: 'A supplicant asked for a punishment bound to happen' },
  { surahId: 70, ayahNumber: 2, text: 'To the disbelievers; of it there is no preventer.' },
  { surahId: 70, ayahNumber: 3, text: '[It is] from Allah, owner of the ways of ascent.' },
  { surahId: 70, ayahNumber: 4, text: 'The angels and the Spirit will ascend to Him during a Day the extent of which is fifty thousand years.' },
  { surahId: 70, ayahNumber: 5, text: 'So be patient with gracious patience.' },
  { surahId: 70, ayahNumber: 6, text: 'Indeed, they see it [as] distant,' },
  { surahId: 70, ayahNumber: 7, text: 'But We see it [as] near.' },
  { surahId: 70, ayahNumber: 8, text: 'On the Day the sky will be like murky oil,' },
  { surahId: 70, ayahNumber: 9, text: 'And the mountains will be like wool,' },
  { surahId: 70, ayahNumber: 10, text: 'And no friend will ask [anything of] a friend,' },
  { surahId: 70, ayahNumber: 11, text: 'They will be shown each other. The criminal will wish that he could be ransomed from the punishment of that Day by his children' },
  { surahId: 70, ayahNumber: 12, text: 'And his wife and his brother' },
  { surahId: 70, ayahNumber: 13, text: 'And his nearest kindred who shelter him' },
  { surahId: 70, ayahNumber: 14, text: 'And whoever is on earth entirely [so] then it could save him.' },
  { surahId: 70, ayahNumber: 15, text: 'No! Indeed, it is the Flame [of Hell],' },
  { surahId: 70, ayahNumber: 16, text: 'A remover of exteriors.' },
  { surahId: 70, ayahNumber: 17, text: 'It invites he who turned his back [on truth] and went away [from obedience]' },
  { surahId: 70, ayahNumber: 18, text: 'And collected [wealth] and hoarded.' },
  { surahId: 70, ayahNumber: 19, text: 'Indeed, mankind was created anxious:' },
  { surahId: 70, ayahNumber: 20, text: 'When evil touches him, impatient,' },
  { surahId: 70, ayahNumber: 21, text: 'And when good touches him, withholding [of it],' },
  { surahId: 70, ayahNumber: 22, text: 'Except the observers of prayer -' },
  { surahId: 70, ayahNumber: 23, text: 'Those who are constant in their prayer' },
  { surahId: 70, ayahNumber: 24, text: 'And those within whose wealth is a known right' },
  { surahId: 70, ayahNumber: 25, text: 'For the petitioner and the deprived -' },
  { surahId: 70, ayahNumber: 26, text: 'And those who believe in the Day of Recompense' },
  { surahId: 70, ayahNumber: 27, text: 'And those who are fearful of the punishment of their Lord -' },
  { surahId: 70, ayahNumber: 28, text: 'Indeed, the punishment of their Lord is not that from which one is safe -' },
  { surahId: 70, ayahNumber: 29, text: 'And those who guard their private parts' },
  { surahId: 70, ayahNumber: 30, text: 'Except from their wives or those their right hands possess, for indeed, they are not to be blamed -' },
  { surahId: 70, ayahNumber: 31, text: 'But whoever seeks beyond that, then they are the transgressors -' },
  { surahId: 70, ayahNumber: 32, text: 'And those who are to their trusts and promises attentive' },
  { surahId: 70, ayahNumber: 33, text: 'And those who are in their testimonies upright' },
  { surahId: 70, ayahNumber: 34, text: 'And those who [carefully] maintain their prayer:' },
  { surahId: 70, ayahNumber: 35, text: 'They will be in gardens, honored.' },
  { surahId: 70, ayahNumber: 36, text: 'So what is [the matter] with those who disbelieve, hastening [from] before you, [O Muhammad],' },
  { surahId: 70, ayahNumber: 37, text: '[To sit] on [your] right and [your] left in separate groups?' },
  { surahId: 70, ayahNumber: 38, text: 'Does every person among them aspire to enter a garden of pleasure?' },
  { surahId: 70, ayahNumber: 39, text: 'No! Indeed, We have created them from that which they know.' },
  { surahId: 70, ayahNumber: 40, text: 'So I swear by the Lord of [all] risings and settings that indeed We are able' },
  { surahId: 70, ayahNumber: 41, text: 'To replace them with better than them; and We are not to be outdone.' },
  { surahId: 70, ayahNumber: 42, text: 'So leave them to converse vainly and amuse themselves until they meet their Day which they are promised -' },
  { surahId: 70, ayahNumber: 43, text: 'The Day they will emerge from the graves rapidly as if they were, toward an erected idol, hastening.' },
  { surahId: 70, ayahNumber: 44, text: 'Their eyes humbled, humiliation will cover them. That is the Day which they had been promised.' },
  { surahId: 71, ayahNumber: 1, text: 'Indeed, We sent Noah to his people, [saying], "Warn your people before there comes to them a painful punishment."' },
  { surahId: 71, ayahNumber: 2, text: 'He said, "O my people, indeed I am to you a clear warner,' },
  { surahId: 71, ayahNumber: 3, text: '[Saying], \'Worship Allah, fear Him and obey me.' },
  { surahId: 71, ayahNumber: 4, text: 'Allah will forgive you of your sins and delay you for a specified term. Indeed, the time [set by] Allah, when it comes, will not be delayed, if you only knew.\' "' },
  { surahId: 71, ayahNumber: 5, text: 'He said, "My Lord, indeed I invited my people [to truth] night and day.' },
  { surahId: 71, ayahNumber: 6, text: 'But my invitation increased them not except in flight.' },
  { surahId: 71, ayahNumber: 7, text: 'And indeed, every time I invited them that You may forgive them, they put their fingers in their ears, covered themselves with their garments, persisted, and were arrogant with [great] arrogance.' },
  { surahId: 71, ayahNumber: 8, text: 'Then I invited them publicly.' },
  { surahId: 71, ayahNumber: 9, text: 'Then I announced to them and [also] confided to them secretly' },
  { surahId: 71, ayahNumber: 10, text: 'And said, \'Ask forgiveness of your Lord. Indeed, He is ever a Perpetual Forgiver.' },
  { surahId: 71, ayahNumber: 11, text: 'He will send [rain from] the sky upon you in [continuing] showers' },
  { surahId: 71, ayahNumber: 12, text: 'And give you increase in wealth and children and provide for you gardens and provide for you rivers.' },
  { surahId: 71, ayahNumber: 13, text: 'What is [the matter] with you that you do not attribute to Allah [due] grandeur' },
  { surahId: 71, ayahNumber: 14, text: 'While He has created you in stages?' },
  { surahId: 71, ayahNumber: 15, text: 'Do you not consider how Allah has created seven heavens in layers' },
  { surahId: 71, ayahNumber: 16, text: 'And made the moon therein a [reflected] light and made the sun a burning lamp?' },
  { surahId: 71, ayahNumber: 17, text: 'And Allah has caused you to grow from the earth a [progressive] growth.' },
  { surahId: 71, ayahNumber: 18, text: 'Then He will return you into it and extract you [another] extraction.' },
  { surahId: 71, ayahNumber: 19, text: 'And Allah has made for you the earth an expanse' },
  { surahId: 71, ayahNumber: 20, text: 'That you may follow therein roads of passage.\' "' },
  { surahId: 71, ayahNumber: 21, text: 'Noah said, "My Lord, indeed they have disobeyed me and followed him whose wealth and children will not increase him except in loss.' },
  { surahId: 71, ayahNumber: 22, text: 'And they conspired an immense conspiracy.' },
  { surahId: 71, ayahNumber: 23, text: 'And said, \'Never leave your gods and never leave Wadd or Suwa\' or Yaghuth and Ya\'uq and Nasr.' },
  { surahId: 71, ayahNumber: 24, text: 'And already they have misled many. And, [my Lord], do not increase the wrongdoers except in error."' },
  { surahId: 71, ayahNumber: 25, text: 'Because of their sins they were drowned and put into the Fire, and they found not for themselves besides Allah [any] helpers.' },
  { surahId: 71, ayahNumber: 26, text: 'And Noah said, "My Lord, do not leave upon the earth from among the disbelievers an inhabitant.' },
  { surahId: 71, ayahNumber: 27, text: 'Indeed, if You leave them, they will mislead Your servants and not beget except [every] wicked one and [confirmed] disbeliever.' },
  { surahId: 71, ayahNumber: 28, text: 'My Lord, forgive me and my parents and whoever enters my house a believer and the believing men and believing women. And do not increase the wrongdoers except in destruction."' },
  { surahId: 72, ayahNumber: 1, text: 'Say, [O Muhammad], "It has been revealed to me that a group of the jinn listened and said, \'Indeed, we have heard an amazing Qur\'an.' },
  { surahId: 72, ayahNumber: 2, text: 'It guides to the right course, and we have believed in it. And we will never associate with our Lord anyone.' },
  { surahId: 72, ayahNumber: 3, text: 'And [it teaches] that exalted is the nobleness of our Lord; He has not taken a wife or a son' },
  { surahId: 72, ayahNumber: 4, text: 'And that our foolish one has been saying about Allah an excessive transgression.' },
  { surahId: 72, ayahNumber: 5, text: 'And we had thought that mankind and the jinn would never speak about Allah a lie.' },
  { surahId: 72, ayahNumber: 6, text: 'And there were men from mankind who sought refuge in men from the jinn, so they [only] increased them in burden.' },
  { surahId: 72, ayahNumber: 7, text: 'And they had thought, as you thought, that Allah would never send anyone [as a messenger].' },
  { surahId: 72, ayahNumber: 8, text: 'And we have sought [to reach] the heaven but found it filled with powerful guards and burning flames.' },
  { surahId: 72, ayahNumber: 9, text: 'And we used to sit therein in positions for hearing, but whoever listens now will find a burning flame lying in wait for him.' },
  { surahId: 72, ayahNumber: 10, text: 'And we do not know [therefore] whether evil is intended for those on earth or whether their Lord intends for them a right course.' },
  { surahId: 72, ayahNumber: 11, text: 'And among us are the righteous, and among us are [others] not so; we were [of] divided ways.' },
  { surahId: 72, ayahNumber: 12, text: 'And we have become certain that we will never cause failure to Allah upon earth, nor can we escape Him by flight.' },
  { surahId: 72, ayahNumber: 13, text: 'And when we heard the guidance, we believed in it. And whoever believes in his Lord will not fear deprivation or burden.' },
  { surahId: 72, ayahNumber: 14, text: 'And among us are Muslims [in submission to Allah], and among us are the unjust. And whoever has become Muslim - those have sought out the right course.' },
  { surahId: 72, ayahNumber: 15, text: 'But as for the unjust, they will be, for Hell, firewood.\'' },
  { surahId: 72, ayahNumber: 16, text: 'And [Allah revealed] that if they had remained straight on the way, We would have given them abundant provision' },
  { surahId: 72, ayahNumber: 17, text: 'So We might test them therein. And whoever turns away from the remembrance of his Lord He will put into arduous punishment.' },
  { surahId: 72, ayahNumber: 18, text: 'And [He revealed] that the masjids are for Allah, so do not invoke with Allah anyone.' },
  { surahId: 72, ayahNumber: 19, text: 'And that when the Servant of Allah stood up supplicating Him, they almost became about him a compacted mass."' },
  { surahId: 72, ayahNumber: 20, text: 'Say, [O Muhammad], "I only invoke my Lord and do not associate with Him anyone."' },
  { surahId: 72, ayahNumber: 21, text: 'Say, "Indeed, I do not possess for you [the power of] harm or right direction."' },
  { surahId: 72, ayahNumber: 22, text: 'Say, "Indeed, there will never protect me from Allah anyone [if I should disobey], nor will I find in other than Him a refuge.' },
  { surahId: 72, ayahNumber: 23, text: 'But [I have for you] only notification from Allah, and His messages." And whoever disobeys Allah and His Messenger - then indeed, for him is the fire of Hell; they will abide therein forever.' },
  { surahId: 72, ayahNumber: 24, text: '[The disbelievers continue] until, when they see that which they are promised, then they will know who is weaker in helpers and less in number.' },
  { surahId: 72, ayahNumber: 25, text: 'Say, "I do not know if what you are promised is near or if my Lord will grant for it a [long] period."' },
  { surahId: 72, ayahNumber: 26, text: '[He is] Knower of the unseen, and He does not disclose His [knowledge of the] unseen to anyone' },
  { surahId: 72, ayahNumber: 27, text: 'Except whom He has approved of messengers, and indeed, He sends before each messenger and behind him observers' },
  { surahId: 72, ayahNumber: 28, text: 'That he may know that they have conveyed the messages of their Lord; and He has encompassed whatever is with them and has enumerated all things in number.' },
  { surahId: 73, ayahNumber: 1, text: 'O you who wraps himself [in clothing],' },
  { surahId: 73, ayahNumber: 2, text: 'Arise [to pray] the night, except for a little -' },
  { surahId: 73, ayahNumber: 3, text: 'Half of it - or subtract from it a little' },
  { surahId: 73, ayahNumber: 4, text: 'Or add to it, and recite the Qur\'an with measured recitation.' },
  { surahId: 73, ayahNumber: 5, text: 'Indeed, We will cast upon you a heavy word.' },
  { surahId: 73, ayahNumber: 6, text: 'Indeed, the hours of the night are more effective for concurrence [of heart and tongue] and more suitable for words.' },
  { surahId: 73, ayahNumber: 7, text: 'Indeed, for you by day is prolonged occupation.' },
  { surahId: 73, ayahNumber: 8, text: 'And remember the name of your Lord and devote yourself to Him with [complete] devotion.' },
  { surahId: 73, ayahNumber: 9, text: '[He is] the Lord of the East and the West; there is no deity except Him, so take Him as Disposer of [your] affairs.' },
  { surahId: 73, ayahNumber: 10, text: 'And be patient over what they say and avoid them with gracious avoidance.' },
  { surahId: 73, ayahNumber: 11, text: 'And leave Me with [the matter of] the deniers, those of ease [in life], and allow them respite a little.' },
  { surahId: 73, ayahNumber: 12, text: 'Indeed, with Us [for them] are shackles and burning fire' },
  { surahId: 73, ayahNumber: 13, text: 'And food that chokes and a painful punishment -' },
  { surahId: 73, ayahNumber: 14, text: 'On the Day the earth and the mountains will convulse and the mountains will become a heap of sand pouring down.' },
  { surahId: 73, ayahNumber: 15, text: 'Indeed, We have sent to you a Messenger as a witness upon you just as We sent to Pharaoh a messenger.' },
  { surahId: 73, ayahNumber: 16, text: 'But Pharaoh disobeyed the messenger, so We seized him with a ruinous seizure.' },
  { surahId: 73, ayahNumber: 17, text: 'Then how can you fear, if you disbelieve, a Day that will make the children white- haired?' },
  { surahId: 73, ayahNumber: 18, text: 'The heaven will break apart therefrom; ever is His promise fulfilled.' },
  { surahId: 73, ayahNumber: 19, text: 'Indeed, this is a reminder, so whoever wills may take to his Lord a way.' },
  { surahId: 73, ayahNumber: 20, text: 'Indeed, your Lord knows, [O Muhammad], that you stand [in prayer] almost two thirds of the night or half of it or a third of it, and [so do] a group of those with you. And Allah determines [the extent of] the night and the day. He has known that you [Muslims] will not be able to do it and has turned to you in forgiveness, so recite what is easy [for you] of the Qur\'an. He has known that there will be among you those who are ill and others traveling throughout the land seeking [something] of the bounty of Allah and others fighting for the cause of Allah. So recite what is easy from it and establish prayer and give zakah and loan Allah a goodly loan. And whatever good you put forward for yourselves - you will find it with Allah. It is better and greater in reward. And seek forgiveness of Allah. Indeed, Allah is Forgiving and Merciful.' },
  { surahId: 74, ayahNumber: 1, text: 'O you who covers himself [with a garment],' },
  { surahId: 74, ayahNumber: 2, text: 'Arise and warn' },
  { surahId: 74, ayahNumber: 3, text: 'And your Lord glorify' },
  { surahId: 74, ayahNumber: 4, text: 'And your clothing purify' },
  { surahId: 74, ayahNumber: 5, text: 'And uncleanliness avoid' },
  { surahId: 74, ayahNumber: 6, text: 'And do not confer favor to acquire more' },
  { surahId: 74, ayahNumber: 7, text: 'But for your Lord be patient.' },
  { surahId: 74, ayahNumber: 8, text: 'And when the trumpet is blown,' },
  { surahId: 74, ayahNumber: 9, text: 'That Day will be a difficult day' },
  { surahId: 74, ayahNumber: 10, text: 'For the disbelievers - not easy.' },
  { surahId: 74, ayahNumber: 11, text: 'Leave Me with the one I created alone' },
  { surahId: 74, ayahNumber: 12, text: 'And to whom I granted extensive wealth' },
  { surahId: 74, ayahNumber: 13, text: 'And children present [with him]' },
  { surahId: 74, ayahNumber: 14, text: 'And spread [everything] before him, easing [his life].' },
  { surahId: 74, ayahNumber: 15, text: 'Then he desires that I should add more.' },
  { surahId: 74, ayahNumber: 16, text: 'No! Indeed, he has been toward Our verses obstinate.' },
  { surahId: 74, ayahNumber: 17, text: 'I will cover him with arduous torment.' },
  { surahId: 74, ayahNumber: 18, text: 'Indeed, he thought and deliberated.' },
  { surahId: 74, ayahNumber: 19, text: 'So may he be destroyed [for] how he deliberated.' },
  { surahId: 74, ayahNumber: 20, text: 'Then may he be destroyed [for] how he deliberated.' },
  { surahId: 74, ayahNumber: 21, text: 'Then he considered [again];' },
  { surahId: 74, ayahNumber: 22, text: 'Then he frowned and scowled;' },
  { surahId: 74, ayahNumber: 23, text: 'Then he turned back and was arrogant' },
  { surahId: 74, ayahNumber: 24, text: 'And said, "This is not but magic imitated [from others].' },
  { surahId: 74, ayahNumber: 25, text: 'This is not but the word of a human being."' },
  { surahId: 74, ayahNumber: 26, text: 'I will drive him into Saqar.' },
  { surahId: 74, ayahNumber: 27, text: 'And what can make you know what is Saqar?' },
  { surahId: 74, ayahNumber: 28, text: 'It lets nothing remain and leaves nothing [unburned],' },
  { surahId: 74, ayahNumber: 29, text: 'Blackening the skins.' },
  { surahId: 74, ayahNumber: 30, text: 'Over it are nineteen [angels].' },
  { surahId: 74, ayahNumber: 31, text: 'And We have not made the keepers of the Fire except angels. And We have not made their number except as a trial for those who disbelieve - that those who were given the Scripture will be convinced and those who have believed will increase in faith and those who were given the Scripture and the believers will not doubt and that those in whose hearts is hypocrisy and the disbelievers will say, "What does Allah intend by this as an example?" Thus does Allah leave astray whom He wills and guides whom He wills. And none knows the soldiers of your Lord except Him. And mention of the Fire is not but a reminder to humanity.' },
  { surahId: 74, ayahNumber: 32, text: 'No! By the moon' },
  { surahId: 74, ayahNumber: 33, text: 'And [by] the night when it departs' },
  { surahId: 74, ayahNumber: 34, text: 'And [by] the morning when it brightens,' },
  { surahId: 74, ayahNumber: 35, text: 'Indeed, the Fire is of the greatest [afflictions]' },
  { surahId: 74, ayahNumber: 36, text: 'As a warning to humanity -' },
  { surahId: 74, ayahNumber: 37, text: 'To whoever wills among you to proceed or stay behind.' },
  { surahId: 74, ayahNumber: 38, text: 'Every soul, for what it has earned, will be retained' },
  { surahId: 74, ayahNumber: 39, text: 'Except the companions of the right,' },
  { surahId: 74, ayahNumber: 40, text: '[Who will be] in gardens, questioning each other' },
  { surahId: 74, ayahNumber: 41, text: 'About the criminals,' },
  { surahId: 74, ayahNumber: 42, text: '[And asking them], "What put you into Saqar?"' },
  { surahId: 74, ayahNumber: 43, text: 'They will say, "We were not of those who prayed,' },
  { surahId: 74, ayahNumber: 44, text: 'Nor did we used to feed the poor.' },
  { surahId: 74, ayahNumber: 45, text: 'And we used to enter into vain discourse with those who engaged [in it],' },
  { surahId: 74, ayahNumber: 46, text: 'And we used to deny the Day of Recompense' },
  { surahId: 74, ayahNumber: 47, text: 'Until there came to us the certainty."' },
  { surahId: 74, ayahNumber: 48, text: 'So there will not benefit them the intercession of [any] intercessors.' },
  { surahId: 74, ayahNumber: 49, text: 'Then what is [the matter] with them that they are, from the reminder, turning away' },
  { surahId: 74, ayahNumber: 50, text: 'As if they were alarmed donkeys' },
  { surahId: 74, ayahNumber: 51, text: 'Fleeing from a lion?' },
  { surahId: 74, ayahNumber: 52, text: 'Rather, every person among them desires that he would be given scriptures spread about.' },
  { surahId: 74, ayahNumber: 53, text: 'No! But they do not fear the Hereafter.' },
  { surahId: 74, ayahNumber: 54, text: 'No! Indeed, the Qur\'an is a reminder' },
  { surahId: 74, ayahNumber: 55, text: 'Then whoever wills will remember it.' },
  { surahId: 74, ayahNumber: 56, text: 'And they will not remember except that Allah wills. He is worthy of fear and adequate for [granting] forgiveness.' },
  { surahId: 75, ayahNumber: 1, text: 'I swear by the Day of Resurrection' },
  { surahId: 75, ayahNumber: 2, text: 'And I swear by the reproaching soul [to the certainty of resurrection].' },
  { surahId: 75, ayahNumber: 3, text: 'Does man think that We will not assemble his bones?' },
  { surahId: 75, ayahNumber: 4, text: 'Yes. [We are] Able [even] to proportion his fingertips.' },
  { surahId: 75, ayahNumber: 5, text: 'But man desires to continue in sin.' },
  { surahId: 75, ayahNumber: 6, text: 'He asks, "When is the Day of Resurrection?"' },
  { surahId: 75, ayahNumber: 7, text: 'So when vision is dazzled' },
  { surahId: 75, ayahNumber: 8, text: 'And the moon darkens' },
  { surahId: 75, ayahNumber: 9, text: 'And the sun and the moon are joined,' },
  { surahId: 75, ayahNumber: 10, text: 'Man will say on that Day, "Where is the [place of] escape?"' },
  { surahId: 75, ayahNumber: 11, text: 'No! There is no refuge.' },
  { surahId: 75, ayahNumber: 12, text: 'To your Lord, that Day, is the [place of] permanence.' },
  { surahId: 75, ayahNumber: 13, text: 'Man will be informed that Day of what he sent ahead and kept back.' },
  { surahId: 75, ayahNumber: 14, text: 'Rather, man, against himself, will be a witness,' },
  { surahId: 75, ayahNumber: 15, text: 'Even if he presents his excuses.' },
  { surahId: 75, ayahNumber: 16, text: 'Move not your tongue with it, [O Muhammad], to hasten with recitation of the Qur\'an.' },
  { surahId: 75, ayahNumber: 17, text: 'Indeed, upon Us is its collection [in your heart] and [to make possible] its recitation.' },
  { surahId: 75, ayahNumber: 18, text: 'So when We have recited it [through Gabriel], then follow its recitation.' },
  { surahId: 75, ayahNumber: 19, text: 'Then upon Us is its clarification [to you].' },
  { surahId: 75, ayahNumber: 20, text: 'No! But you love the immediate' },
  { surahId: 75, ayahNumber: 21, text: 'And leave the Hereafter.' },
  { surahId: 75, ayahNumber: 22, text: '[Some] faces, that Day, will be radiant,' },
  { surahId: 75, ayahNumber: 23, text: 'Looking at their Lord.' },
  { surahId: 75, ayahNumber: 24, text: 'And [some] faces, that Day, will be contorted,' },
  { surahId: 75, ayahNumber: 25, text: 'Expecting that there will be done to them [something] backbreaking.' },
  { surahId: 75, ayahNumber: 26, text: 'No! When the soul has reached the collar bones' },
  { surahId: 75, ayahNumber: 27, text: 'And it is said, "Who will cure [him]?"' },
  { surahId: 75, ayahNumber: 28, text: 'And the dying one is certain that it is the [time of] separation' },
  { surahId: 75, ayahNumber: 29, text: 'And the leg is wound about the leg,' },
  { surahId: 75, ayahNumber: 30, text: 'To your Lord, that Day, will be the procession.' },
  { surahId: 75, ayahNumber: 31, text: 'And the disbeliever had not believed, nor had he prayed.' },
  { surahId: 75, ayahNumber: 32, text: 'But [instead], he denied and turned away.' },
  { surahId: 75, ayahNumber: 33, text: 'And then he went to his people, swaggering [in pride].' },
  { surahId: 75, ayahNumber: 34, text: 'Woe to you, and woe!' },
  { surahId: 75, ayahNumber: 35, text: 'Then woe to you, and woe!' },
  { surahId: 75, ayahNumber: 36, text: 'Does man think that he will be left neglected?' },
  { surahId: 75, ayahNumber: 37, text: 'Had he not been a sperm from semen emitted?' },
  { surahId: 75, ayahNumber: 38, text: 'Then he was a clinging clot, and [Allah] created [his form] and proportioned [him]' },
  { surahId: 75, ayahNumber: 39, text: 'And made of him two mates, the male and the female.' },
  { surahId: 75, ayahNumber: 40, text: 'Is not that [Creator] Able to give life to the dead?' },
  { surahId: 76, ayahNumber: 1, text: 'Has there [not] come upon man a period of time when he was not a thing [even] mentioned?' },
  { surahId: 76, ayahNumber: 2, text: 'Indeed, We created man from a sperm-drop mixture that We may try him; and We made him hearing and seeing.' },
  { surahId: 76, ayahNumber: 3, text: 'Indeed, We guided him to the way, be he grateful or be he ungrateful.' },
  { surahId: 76, ayahNumber: 4, text: 'Indeed, We have prepared for the disbelievers chains and shackles and a blaze.' },
  { surahId: 76, ayahNumber: 5, text: 'Indeed, the righteous will drink from a cup [of wine] whose mixture is of Kafur,' },
  { surahId: 76, ayahNumber: 6, text: 'A spring of which the [righteous] servants of Allah will drink; they will make it gush forth in force [and abundance].' },
  { surahId: 76, ayahNumber: 7, text: 'They [are those who] fulfill [their] vows and fear a Day whose evil will be widespread.' },
  { surahId: 76, ayahNumber: 8, text: 'And they give food in spite of love for it to the needy, the orphan, and the captive,' },
  { surahId: 76, ayahNumber: 9, text: '[Saying], "We feed you only for the countenance of Allah. We wish not from you reward or gratitude.' },
  { surahId: 76, ayahNumber: 10, text: 'Indeed, We fear from our Lord a Day austere and distressful."' },
  { surahId: 76, ayahNumber: 11, text: 'So Allah will protect them from the evil of that Day and give them radiance and happiness' },
  { surahId: 76, ayahNumber: 12, text: 'And will reward them for what they patiently endured [with] a garden [in Paradise] and silk [garments].' },
  { surahId: 76, ayahNumber: 13, text: '[They will be] reclining therein on adorned couches. They will not see therein any [burning] sun or [freezing] cold.' },
  { surahId: 76, ayahNumber: 14, text: 'And near above them are its shades, and its [fruit] to be picked will be lowered in compliance.' },
  { surahId: 76, ayahNumber: 15, text: 'And there will be circulated among them vessels of silver and cups having been [created] clear [as glass],' },
  { surahId: 76, ayahNumber: 16, text: 'Clear glasses [made] from silver of which they have determined the measure.' },
  { surahId: 76, ayahNumber: 17, text: 'And they will be given to drink a cup [of wine] whose mixture is of ginger' },
  { surahId: 76, ayahNumber: 18, text: '[From] a fountain within Paradise named Salsabeel.' },
  { surahId: 76, ayahNumber: 19, text: 'There will circulate among them young boys made eternal. When you see them, you would think them [as beautiful as] scattered pearls.' },
  { surahId: 76, ayahNumber: 20, text: 'And when you look there [in Paradise], you will see pleasure and great dominion.' },
  { surahId: 76, ayahNumber: 21, text: 'Upon the inhabitants will be green garments of fine silk and brocade. And they will be adorned with bracelets of silver, and their Lord will give them a purifying drink.' },
  { surahId: 76, ayahNumber: 22, text: '[And it will be said], "Indeed, this is for you a reward, and your effort has been appreciated."' },
  { surahId: 76, ayahNumber: 23, text: 'Indeed, it is We who have sent down to you, [O Muhammad], the Qur\'an progressively.' },
  { surahId: 76, ayahNumber: 24, text: 'So be patient for the decision of your Lord and do not obey from among them a sinner or ungrateful [disbeliever].' },
  { surahId: 76, ayahNumber: 25, text: 'And mention the name of your Lord [in prayer] morning and evening' },
  { surahId: 76, ayahNumber: 26, text: 'And during the night prostrate to Him and exalt Him a long [part of the] night.' },
  { surahId: 76, ayahNumber: 27, text: 'Indeed, these [disbelievers] love the immediate and leave behind them a grave Day.' },
  { surahId: 76, ayahNumber: 28, text: 'We have created them and strengthened their forms, and when We will, We can change their likenesses with [complete] alteration.' },
  { surahId: 76, ayahNumber: 29, text: 'Indeed, this is a reminder, so he who wills may take to his Lord a way.' },
  { surahId: 76, ayahNumber: 30, text: 'And you do not will except that Allah wills. Indeed, Allah is ever Knowing and Wise.' },
  { surahId: 76, ayahNumber: 31, text: 'He admits whom He wills into His mercy; but the wrongdoers - He has prepared for them a painful punishment.' },
  { surahId: 77, ayahNumber: 1, text: 'By those [winds] sent forth in gusts' },
  { surahId: 77, ayahNumber: 2, text: 'And the winds that blow violently' },
  { surahId: 77, ayahNumber: 3, text: 'And [by] the winds that spread [clouds]' },
  { surahId: 77, ayahNumber: 4, text: 'And those [angels] who bring criterion' },
  { surahId: 77, ayahNumber: 5, text: 'And those [angels] who deliver a message' },
  { surahId: 77, ayahNumber: 6, text: 'As justification or warning,' },
  { surahId: 77, ayahNumber: 7, text: 'Indeed, what you are promised is to occur.' },
  { surahId: 77, ayahNumber: 8, text: 'So when the stars are obliterated' },
  { surahId: 77, ayahNumber: 9, text: 'And when the heaven is opened' },
  { surahId: 77, ayahNumber: 10, text: 'And when the mountains are blown away' },
  { surahId: 77, ayahNumber: 11, text: 'And when the messengers\' time has come...' },
  { surahId: 77, ayahNumber: 12, text: 'For what Day was it postponed?' },
  { surahId: 77, ayahNumber: 13, text: 'For the Day of Judgement.' },
  { surahId: 77, ayahNumber: 14, text: 'And what can make you know what is the Day of Judgement?' },
  { surahId: 77, ayahNumber: 15, text: 'Woe, that Day, to the deniers.' },
  { surahId: 77, ayahNumber: 16, text: 'Did We not destroy the former peoples?' },
  { surahId: 77, ayahNumber: 17, text: 'Then We will follow them with the later ones.' },
  { surahId: 77, ayahNumber: 18, text: 'Thus do We deal with the criminals.' },
  { surahId: 77, ayahNumber: 19, text: 'Woe, that Day, to the deniers.' },
  { surahId: 77, ayahNumber: 20, text: 'Did We not create you from a liquid disdained?' },
  { surahId: 77, ayahNumber: 21, text: 'And We placed it in a firm lodging' },
  { surahId: 77, ayahNumber: 22, text: 'For a known extent.' },
  { surahId: 77, ayahNumber: 23, text: 'And We determined [it], and excellent [are We] to determine.' },
  { surahId: 77, ayahNumber: 24, text: 'Woe, that Day, to the deniers.' },
  { surahId: 77, ayahNumber: 25, text: 'Have We not made the earth a container' },
  { surahId: 77, ayahNumber: 26, text: 'Of the living and the dead?' },
  { surahId: 77, ayahNumber: 27, text: 'And We placed therein lofty, firmly set mountains and have given you to drink sweet water.' },
  { surahId: 77, ayahNumber: 28, text: 'Woe, that Day, to the deniers.' },
  { surahId: 77, ayahNumber: 29, text: '[They will be told], "Proceed to that which you used to deny.' },
  { surahId: 77, ayahNumber: 30, text: 'Proceed to a shadow [of smoke] having three columns' },
  { surahId: 77, ayahNumber: 31, text: '[But having] no cool shade and availing not against the flame."' },
  { surahId: 77, ayahNumber: 32, text: 'Indeed, it throws sparks [as huge] as a fortress,' },
  { surahId: 77, ayahNumber: 33, text: 'As if they were yellowish [black] camels.' },
  { surahId: 77, ayahNumber: 34, text: 'Woe, that Day, to the deniers.' },
  { surahId: 77, ayahNumber: 35, text: 'This is a Day they will not speak,' },
  { surahId: 77, ayahNumber: 36, text: 'Nor will it be permitted for them to make an excuse.' },
  { surahId: 77, ayahNumber: 37, text: 'Woe, that Day, to the deniers.' },
  { surahId: 77, ayahNumber: 38, text: 'This is the Day of Judgement; We will have assembled you and the former peoples.' },
  { surahId: 77, ayahNumber: 39, text: 'So if you have a plan, then plan against Me.' },
  { surahId: 77, ayahNumber: 40, text: 'Woe, that Day, to the deniers.' },
  { surahId: 77, ayahNumber: 41, text: 'Indeed, the righteous will be among shades and springs' },
  { surahId: 77, ayahNumber: 42, text: 'And fruits from whatever they desire,' },
  { surahId: 77, ayahNumber: 43, text: '[Being told], "Eat and drink in satisfaction for what you used to do."' },
  { surahId: 77, ayahNumber: 44, text: 'Indeed, We thus reward the doers of good.' },
  { surahId: 77, ayahNumber: 45, text: 'Woe, that Day, to the deniers.' },
  { surahId: 77, ayahNumber: 46, text: '[O disbelievers], eat and enjoy yourselves a little; indeed, you are criminals.' },
  { surahId: 77, ayahNumber: 47, text: 'Woe, that Day, to the deniers.' },
  { surahId: 77, ayahNumber: 48, text: 'And when it is said to them, "Bow [in prayer]," they do not bow.' },
  { surahId: 77, ayahNumber: 49, text: 'Woe, that Day, to the deniers.' },
  { surahId: 77, ayahNumber: 50, text: 'Then in what statement after the Qur\'an will they believe?' },
];
